var e=`क्रिया`,t=`जोड़ें`,n=`एप्लिकेशन`,r=`आर्किटेक्चर`,i=`पहलू`,a=`प्रमाणीकरण`,o=`ऑथोरिटेटिव`,s=`Blowfish`,c=`ब्राउज़र`,l=`चुनौती`,u=`क्लाइंट`,d=`बंद करें`,f=`गोपनीयता`,p=`कनेक्शन`,m=`बचाव`,h=`गंतव्य`,g=`ETag`,_=`ईथरनेट`,v=`फ़ाइबर`,y=`बुनियादी बातें`,b=`गेटवे`,x=`Host`,S=`जानकारी`,C=`इंस्टॉल करें`,w=`इंटरनेट`,T=`लैब`,E=`लेयर`,D=`लिंक`,O=`माध्यम`,k=`मेथड`,A=`नेटवर्क`,j=`कभी नहीं`,M=`नया`,N=`कुछ नहीं`,P=`फ़िज़िकल`,F=`प्रेज़ेंटेशन`,I=`यादृच्छिक`,L=`फिर से करें`,R=`भरोसेमंदी`,z=`राउटर`,B=`रूटिंग`,V=`सुरक्षा`,H=`सीरियल`,U=`Server`,W=`सेशन`,G=`शेयर`,K=`हल`,q=`स्रोत`,J=`स्टैक`,Y=`छिपाव`,X=`स्विचिंग`,Z=`Telnet`,Q=`ट्रांसपोर्ट`,$=`समस्या निवारण`,ee=`पूर्ववत करें`,te=`वायरलेस`,ne=`हाँ`,re={"(connected / default gw)":`(जुड़ा हुआ / डिफ़ॉल्ट गेटवे)`,"(empty — send traffic to populate)":`(खाली — भरने के लिए ट्रैफ़िक भेजें)`,"(empty)":`(खाली)`,"(no NAT sessions)":`(कोई NAT सेशन नहीं)`,"(no active NAT translations)":`(कोई सक्रिय NAT ट्रांसलेशन नहीं)`,"(using connected subnet / default gateway)":`(जुड़ा हुआ सबनेट / डिफ़ॉल्ट गेटवे उपयोग में)`,"-ERR Auth Failed":`-ERR Auth Failed`,".com TLD":`.com TLD`,".com TLD nameserver returns the authoritative nameserver IP 198.51.100.53.":`.com TLD नेमसर्वर ऑथोरिटेटिव नेमसर्वर का IP 198.51.100.53 लौटाता है।`,".com TLD refers to example.com NS":`.com TLD, example.com के NS की ओर भेजता है`,"0 Echo Reply · 3 Dest Unreachable (Code 4: Frag Needed) · 8 Echo Request · 11 Time Exceeded (TTL=0)":`0 इको रिप्लाई · 3 गंतव्य पहुँच से बाहर (कोड 4: फ़्रैगमेंटेशन ज़रूरी) · 8 इको रिक्वेस्ट · 11 समय समाप्त (TTL=0)`,"0 RTT always":`हमेशा 0 RTT`,"0x0806 identifies ARP, 0x0800 identifies IPv4, 0x86DD identifies IPv6, and 0x8100 identifies 802.1Q VLAN.":`0x0806 ARP को, 0x0800 IPv4 को, 0x86DD IPv6 को और 0x8100 802.1Q VLAN को दर्शाता है।`,"1 duplicate ACK":`1 डुप्लिकेट ACK`,"1-RTT Initial (Transport + TLS)":`1-RTT Initial (ट्रांसपोर्ट + TLS)`,"1-RTT Noise_IK Handshake":`1-RTT Noise_IK हैंडशेक`,"1-RTT ServerHello, EncryptedExtensions, Cert, Finished":`1-RTT ServerHello, EncryptedExtensions, Cert, Finished`,"10.1.0.10 -> 10.2.0.20 encrypted inside 198.51.100.1 -> 203.0.113.1":`10.1.0.10 -> 10.2.0.20, 198.51.100.1 -> 203.0.113.1 के अंदर एन्क्रिप्टेड`,"101 Switching Protocols":`101 Switching Protocols`,"101 Switching Protocols transitions the TCP socket from HTTP to WebSocket framing.":`101 Switching Protocols, TCP सॉकेट को HTTP से WebSocket फ़्रेमिंग में बदलता है।`,"110 and 995":`110 और 995`,"128 bits":`128 बिट`,"14-byte Frame Header + 46–1500B Payload + 4B FCS":`14-बाइट फ़्रेम हेडर + 46–1500B पेलोड + 4B FCS`,"143 and 993":`143 और 993`,"1500 bytes":`1500 बाइट`,"16 bits":`16 बिट`,"161 and 162":`161 और 162`,"1xx Info (101 Switching) · 2xx OK (200, 201, 204) · 3xx Redirect (301, 304) · 4xx Client (400, 401, 403, 404) · 5xx Server (500, 502, 503)":`1xx सूचना (101 Switching) · 2xx सफल (200, 201, 204) · 3xx रीडायरेक्ट (301, 304) · 4xx क्लाइंट त्रुटि (400, 401, 403, 404) · 5xx सर्वर त्रुटि (500, 502, 503)`,"20 Preset Network Labs":`20 तैयार नेटवर्क लैब`,"20 bytes":`20 बाइट`,"20-byte IPv4 Header + L4 Payload (Max 65,535B)":`20-बाइट IPv4 हेडर + L4 पेलोड (अधिकतम 65,535B)`,"200 Connection Established":`200 Connection Established`,"200 OK application/dns-message":`200 OK application/dns-message`,"200 OK means the request succeeded and the response body contains the representation.":`200 OK का मतलब है अनुरोध सफल रहा और जवाब की बॉडी में अपेक्षित सामग्री है।`,"200 signals the tunnel is ready for raw TLS bytes.":`200 बताता है कि सुरंग कच्चे TLS बाइट के लिए तैयार है।`,"204 No Content":`204 No Content`,"20B Header + RFC 1071 Checksum":`20B हेडर + RFC 1071 चेकसम`,"20–60 Byte Header + Byte Stream Segments":`20–60 बाइट हेडर + बाइट-स्ट्रीम सेगमेंट`,"21 (Control) and 20 (Active Data)":`21 (कंट्रोल) और 20 (एक्टिव डेटा)`,"21 and 22":`21 और 22`,"22 and 23":`22 और 23`,"220 Ready -> EHLO -> 250 Capabilities":`220 Ready -> EHLO -> 250 Capabilities`,"224.0.0.0 through 239.255.255.255 (Class D) is reserved for IPv4 multicast.":`224.0.0.0 से 239.255.255.255 तक (क्लास D) IPv4 मल्टीकास्ट के लिए आरक्षित है।`,"25 and 465":`25 और 465`,"25 and 587":`25 और 587`,"256 bits":`256 बिट`,"3 duplicate ACKs":`3 डुप्लिकेट ACK`,"3-Way Handshake":`3-वे हैंडशेक`,"3-Way Handshake (SYN / SYN-ACK / ACK)":`3-वे हैंडशेक (SYN / SYN-ACK / ACK)`,"3-way TCP handshake establishes the reliable byte stream to port 443.":`3-वे TCP हैंडशेक पोर्ट 443 तक भरोसेमंद बाइट स्ट्रीम बनाता है।`,"301 Moved":`301 Moved`,"301 Moved Permanently":`301 Moved Permanently`,"302 Found":`302 Found`,"32 bits":`32 बिट`,"4-Way Handshake + PMF":`4-वे हैंडशेक + PMF`,"4-Way Handshake Msg 1 (ANonce)":`4-वे हैंडशेक संदेश 1 (ANonce)`,"4-Way Handshake Msg 2 (SNonce + MIC)":`4-वे हैंडशेक संदेश 2 (SNonce + MIC)`,"4-Way Teardown":`4-वे समापन`,"40 bytes":`40 बाइट`,"401 Unauthorized":`401 Unauthorized`,"404 Not Found":`404 Not Found`,"407 Proxy Auth Required":`407 Proxy Auth Required`,"4096 bytes":`4096 बाइट`,"445 and 139":`445 और 139`,"48-byte Fixed Binary Timestamps (T1, T2, T3, T4)":`48-बाइट निश्चित बाइनरी टाइमस्टैम्प (T1, T2, T3, T4)`,"486 Busy Here":`486 Busy Here`,"500 and 4500":`500 और 4500`,"502 Bad Gateway":`502 Bad Gateway`,"5060 and 5061":`5060 और 5061`,"53 and 54":`53 और 54`,"53 and 80":`53 और 80`,"53 and 853":`53 और 853`,"530 Login Incorrect":`530 Login Incorrect`,"576 bytes":`576 बाइट`,"60 bytes":`60 बाइट`,"64 bits":`64 बिट`,"65535 bytes":`65535 बाइट`,"67 and 68":`67 और 68`,"6B PPPoE header + 2B PPP protocol ID = 8 bytes overhead (1500 - 8 = 1492).":`6B PPPoE हेडर + 2B PPP प्रोटोकॉल ID = 8 बाइट का अतिरिक्त बोझ (1500 - 8 = 1492)।`,"7-byte MBAP Header + Function Code + Register Data":`7-बाइट MBAP हेडर + फ़ंक्शन कोड + रजिस्टर डेटा`,"8 bytes":`8 बाइट`,"8-byte Fixed Header + Datagram Payload":`8-बाइट निश्चित हेडर + डेटाग्राम पेलोड`,"8-byte ICMP Header + Echo/Error Payload":`8-बाइट ICMP हेडर + इको/त्रुटि पेलोड`,"8.8.8.8 already has a warm cached entry":`8.8.8.8 के पास पहले से कैश में जवाब है`,"80 and 443":`80 और 443`,"802.11 Auth & Association":`802.11 प्रमाणीकरण और असोसिएशन`,"802.1Q trunking isolates broadcast domains while allowing L3 inter-VLAN routing.":`802.1Q ट्रंकिंग ब्रॉडकास्ट डोमेन अलग रखती है और L3 इंटर-VLAN रूटिंग की अनुमति देती है।`,"802.1X supplicant connects; AP keeps port unauthorized and requests EAP identity.":`802.1X सप्लिकेंट जुड़ता है; AP पोर्ट को अनधिकृत रखता है और EAP पहचान माँगता है।`,"8–16 Byte IGMP Membership Report/Query":`8–16 बाइट IGMP सदस्यता रिपोर्ट/क्वेरी`,"A (IPv4) · AAAA (IPv6) · CNAME (Alias) · MX (Mail) · NS (Authority) · TXT (SPF/DKIM) · DS/RRSIG (DNSSEC)":`A (IPv4) · AAAA (IPv6) · CNAME (उपनाम) · MX (मेल) · NS (अधिकार) · TXT (SPF/DKIM) · DS/RRSIG (DNSSEC)`,"A 576-byte tunnel link sits in the path; send a 1400-byte ping and watch PMTUD / fragmentation.":`रास्ते में 576-बाइट का टनल लिंक है; 1400-बाइट का ping भेजें और PMTUD / फ़्रैगमेंटेशन देखें।`,"A broken clock":`एक ख़राब घड़ी`,"A firewall rule on the web server drops the traffic":`वेब सर्वर का एक फ़ायरवॉल नियम ट्रैफ़िक गिरा रहा है`,"A gateway cannot forge a valid TLS certificate for google.com, so browsers block MITM redirects on HTTPS.":`कोई गेटवे google.com का वैध TLS सर्टिफ़िकेट जाली नहीं बना सकता, इसलिए ब्राउज़र HTTPS पर MITM रीडायरेक्ट रोक देते हैं।`,"A link that is physically down fails at Layer 1: nothing is sent at all. Always check the lights and cables before blaming software.":`भौतिक रूप से डाउन लिंक लेयर 1 पर विफल होता है: कुछ भी भेजा ही नहीं जाता। सॉफ़्टवेयर को दोष देने से पहले हमेशा बत्तियाँ और केबल जाँचें।`,"A local browser clock":`ब्राउज़र की स्थानीय घड़ी`,"A restaurant host greets guests at the front door, checks reservations (WAF), and seats each party at whichever open kitchen table (backend server) isn’t busy.":`रेस्तराँ का स्वागतकर्ता मेहमानों का दरवाज़े पर स्वागत करता है, आरक्षण जाँचता है (WAF) और हर समूह को जो भी रसोई-मेज़ (बैकएंड सर्वर) व्यस्त न हो वहाँ बिठाता है।`,"A reverse proxy sits in front of origin backend servers to terminate TLS, enforce WAF rules, cache static content, and load-balance requests across healthy upstream workers.":`रिवर्स प्रॉक्सी मूल बैकएंड सर्वरों के आगे बैठता है: TLS समाप्त करता है, WAF नियम लगाता है, स्थिर सामग्री कैश करता है और अनुरोध स्वस्थ वर्करों में बाँटता है।`,"A rogue AS announces a more-specific IP prefix it does not own, blackholing or intercepting global traffic.":`कोई दुष्ट AS ऐसा अधिक विशिष्ट IP प्रीफ़िक्स घोषित करता है जो उसका नहीं है, जिससे वैश्विक ट्रैफ़िक ग़ायब या बीच में पकड़ा जाता है।`,"A rogue proxy presents an expired or self-signed certificate.":`कोई नकली प्रॉक्सी एक्सपायर्ड या सेल्फ़-साइन्ड सर्टिफ़िकेट पेश करता है।`,"A server directly attached to an atomic/GPS reference clock":`ऐसा सर्वर जो सीधे परमाणु/GPS संदर्भ घड़ी से जुड़ा हो`,"A single period on its own line (<CRLF>.<CRLF>)":`अलग पंक्ति में एक अकेला बिंदु (<CRLF>.<CRLF>)`,'AAAA ("quad-A") records store 128-bit IPv6 addresses.':`AAAA ("क्वाड-A") रिकॉर्ड 128-बिट IPv6 पते रखते हैं।`,"ACK and PSH":`ACK और PSH`,"AH (Authentication Header)":`AH (Authentication Header)`,"AH only authenticates headers; ESP provides encryption + authentication.":`AH केवल हेडर प्रमाणित करता है; ESP एन्क्रिप्शन + प्रमाणीकरण देता है।`,"AMF0 NetConnection.connect + publish(streamKey)":`AMF0 NetConnection.connect + publish(streamKey)`,"AP delivers Group Temporal Key (GTK), STA confirms Msg 4, and AES-CCMP data flows.":`AP ग्रुप टेम्पररी कुंजी (GTK) देता है, STA संदेश 4 से पुष्टि करता है, और AES-CCMP डेटा बहने लगता है।`,"AP forwards EAPOL frames as RADIUS UDP/1812 requests":`AP, EAPOL फ़्रेम को RADIUS UDP/1812 अनुरोध के रूप में आगे भेजता है`,"AP relays EAP inside UDP/1812 to RADIUS":`AP, UDP/1812 के भीतर EAP को RADIUS तक पहुँचाता है`,"AP sends random ANonce to STA":`AP, STA को यादृच्छिक ANonce भेजता है`,"AP wraps EAP payload into RADIUS Access-Request; RADIUS replies Access-Challenge (EAP-TLS).":`AP, EAP पेलोड को RADIUS Access-Request में लपेटता है; RADIUS Access-Challenge (EAP-TLS) से जवाब देता है।`,"ARP Broadcast":`ARP ब्रॉडकास्ट`,"ARP Spoofing / Cache Poisoning":`ARP स्पूफ़िंग / कैश पॉइज़निंग`,"ARP Spoofing / MITM & DAI Detection":`ARP स्पूफ़िंग / MITM और DAI से पहचान`,"ARP Unicast Reply":`ARP यूनिकास्ट रिप्लाई`,"ARP caching":`ARP कैशिंग`,"ARP replies":`ARP जवाब`,"ARP reply":`ARP रिप्लाई`,"AS64500 and AS64510 exchange OPEN messages with hold timers and confirm with KEEPALIVE.":`AS64500 और AS64510 होल्ड टाइमर के साथ OPEN संदेश बदलते हैं और KEEPALIVE से पुष्टि करते हैं।`,"AS64500 fails over automatically to alternate AS path when primary peering drops.":`मुख्य पीयरिंग गिरने पर AS64500 अपने-आप वैकल्पिक AS पथ पर चला जाता है।`,"AS64510 prepends ASN & forwards":`AS64510 अपना ASN जोड़कर आगे भेजता है`,"AS64511 advertises 203.0.113.0/24":`AS64511 203.0.113.0/24 घोषित करता है`,"ASCII Commands + RFC 5322 MIME Message":`ASCII कमांड + RFC 5322 MIME संदेश`,"ASCII Control Channel + Raw Binary Data Channel":`ASCII कंट्रोल चैनल + रॉ बाइनरी डेटा चैनल`,"ASCII Request/Response (+OK / -ERR)":`ASCII रिक्वेस्ट/रिस्पॉन्स (+OK / -ERR)`,"AUTH Failed (535)":`AUTH विफल (535)`,"Access Concentrator":`एक्सेस कंसन्ट्रेटर`,"Access-Accept & Port Open":`Access-Accept और पोर्ट खुला`,"Access-Reject (Invalid User)":`Access-Reject (अमान्य उपयोगकर्ता)`,Act:e,Add:t,"Add the missing A record":`ग़ायब A रिकॉर्ड जोड़ें`,"Add to Home Screen":`होम स्क्रीन पर जोड़ें`,"Add topology annotation (e.g. 'DMZ 203.0.113.0/24')...":`टोपोलॉजी पर टिप्पणी जोड़ें (जैसे 'DMZ 203.0.113.0/24')...`,"Admin Laptop":`एडमिन लैपटॉप`,"After ServerHello, TLS 1.3 encrypts the Certificate and CertificateVerify messages with the handshake key.":`ServerHello के बाद TLS 1.3 Certificate और CertificateVerify संदेश हैंडशेक कुंजी से एन्क्रिप्ट करता है।`,"After TCP handshake, both peers send plaintext SSH-2.0 protocol identification banners.":`TCP हैंडशेक के बाद दोनों पीयर सादे टेक्स्ट में SSH-2.0 प्रोटोकॉल पहचान बैनर भेजते हैं।`,"After sign-in, gateway permits guest MAC through NAT to the open internet.":`साइन-इन के बाद गेटवे अतिथि के MAC को NAT से होकर खुले इंटरनेट तक जाने देता है।`,"Agree encryption & signing capabilities":`एन्क्रिप्शन और साइनिंग क्षमताओं पर सहमति`,"All subsequent bytes pass transparently between client and target origin.":`इसके बाद के सारे बाइट क्लाइंट और लक्ष्य मूल सर्वर के बीच पारदर्शी रूप से गुज़रते हैं।`,"All-ones (ff:ff:ff:ff:ff:ff) instructs switches to flood the frame out every port in the broadcast domain.":`सभी एक (ff:ff:ff:ff:ff:ff) स्विचों को निर्देश देता है कि फ़्रेम को ब्रॉडकास्ट डोमेन के हर पोर्ट पर फ़्लड करें।`,"Allow HMI -> PLC TCP/502 while blocking Guest Laptop -> PLC TCP/502":`HMI -> PLC TCP/502 की अनुमति दें और अतिथि लैपटॉप -> PLC TCP/502 रोकें`,"Always mandate POP3S (implicit TLS on port 995) or STLS.":`हमेशा POP3S (पोर्ट 995 पर इम्प्लिसिट TLS) या STLS अनिवार्य करें।`,"Always stream over RTMPS (RTMP inside TLS) and rotate stream keys.":`हमेशा RTMPS (TLS के अंदर RTMP) से स्ट्रीम करें और स्ट्रीम कुंजियाँ बदलते रहें।`,"Always upgrade to HTTPS (TLS 1.3) and enforce HSTS (Strict-Transport-Security).":`हमेशा HTTPS (TLS 1.3) अपनाएँ और HSTS (Strict-Transport-Security) लागू करें।`,"Ambiguous Content-Length vs Transfer-Encoding headers trick proxies and backends into desync.":`अस्पष्ट Content-Length बनाम Transfer-Encoding हेडर प्रॉक्सी और बैकएंड का तालमेल बिगाड़ देते हैं।`,"An HTTP forward proxy relays client traffic to external servers. For HTTPS, the client sends an HTTP CONNECT host:443 request so the proxy opens a raw opaque TCP tunnel for end-to-end TLS.":`HTTP फ़ॉरवर्ड प्रॉक्सी क्लाइंट का ट्रैफ़िक बाहरी सर्वरों तक पहुँचाता है। HTTPS के लिए क्लाइंट HTTP CONNECT host:443 अनुरोध भेजता है ताकि प्रॉक्सी शुरू से अंत तक TLS के लिए एक कच्ची, अपारदर्शी TCP सुरंग खोल दे।`,"An active MITM forces peers back to obsolete SSL 3.0 or TLS 1.0 ciphers with padding oracle flaws.":`सक्रिय MITM दोनों पक्षों को पुराने SSL 3.0 या TLS 1.0 साइफ़र पर लौटने को मजबूर करता है, जिनमें पैडिंग ऑरेकल की कमज़ोरियाँ हैं।`,"An attacker answers DISCOVER faster than the real router, handing out their own IP as default gateway/DNS for MITM.":`हमलावर असली राउटर से पहले DISCOVER का जवाब देता है और बीच में घुसने (MITM) के लिए अपना IP डिफ़ॉल्ट गेटवे/DNS के रूप में बाँट देता है।`,"An attacker joins many multicast streams to saturate switch/access links.":`हमलावर स्विच/एक्सेस लिंक भरने के लिए बहुत सारी मल्टीकास्ट स्ट्रीम में शामिल हो जाता है।`,"An attacker races spoofed UDP replies with guessed transaction IDs to inject rogue IP records into a resolver cache.":`हमलावर ट्रांज़ैक्शन ID का अंदाज़ा लगाकर नकली UDP जवाब पहले पहुँचाने की होड़ करता है, ताकि रिज़ॉल्वर के कैश में ग़लत IP रिकॉर्ड डाल सके।`,"An attacker sends fake ICMPv6 Router Advertisements to hijack default gateway routing on a LAN.":`हमलावर LAN पर डिफ़ॉल्ट गेटवे रूटिंग हथियाने के लिए नकली ICMPv6 Router Advertisement भेजता है।`,"An attacker sends unsolicited ARP replies claiming to own the gateway’s IP, intercepting all LAN traffic (MITM).":`हमलावर बिना माँगे ARP जवाब भेजकर गेटवे का IP अपना बताता है और LAN का सारा ट्रैफ़िक बीच में पकड़ लेता है (MITM)।`,"An on-path attacker intercepts an initial plain HTTP request and prevents the redirect to HTTPS.":`रास्ते में बैठा हमलावर शुरुआती सादे HTTP अनुरोध को रोकता है और HTTPS पर रीडायरेक्ट होने से बचाता है।`,"Anonymous login":`अनाम लॉगिन`,"Another host replies claiming the same IP":`कोई और होस्ट उसी IP का दावा करते हुए जवाब देता है`,"Anyone able to send packets to TCP/502 can issue read/write commands to the PLC.":`TCP/502 पर पैकेट भेज सकने वाला कोई भी PLC को पढ़ने/लिखने के कमांड दे सकता है।`,"App Server":`ऐप सर्वर`,"App-Level Handling":`ऐप स्तर पर संभाल`,Application:n,"Application hands data to UDP; no SYN handshake occurs—datagram #1 leaves immediately.":`ऐप डेटा UDP को सौंपता है; कोई SYN हैंडशेक नहीं होता, डेटाग्राम #1 तुरंत निकल जाता है।`,'Application-Layer Protocol Negotiation (ALPN) picks "h2" or "http/1.1" in 0 extra round-trips.':`एप्लिकेशन-लेयर प्रोटोकॉल नेगोशिएशन (ALPN) बिना किसी अतिरिक्त राउंड-ट्रिप के "h2" या "http/1.1" चुनता है।`,"Arbitrary TCP/UDP payload relayed":`कोई भी TCP/UDP पेलोड आगे पहुँचाया जाता है`,Architecture:r,"Arrange the protocol messages into chronological wire order.":`प्रोटोकॉल संदेशों को उसी क्रम में लगाएँ जिसमें वे तार पर जाते हैं।`,Aspect:i,"Assign IP":`IP देना`,"Assign Session ID (e.g. 0x04a1)":`सेशन ID दें (जैसे 0x04a1)`,"Asymmetric Delay Spike":`असममित देरी में उछाल`,"Attacker injects forged ARP replies to intercept traffic between Victim PC and Gateway.":`हमलावर पीड़ित PC और गेटवे के बीच का ट्रैफ़िक पकड़ने के लिए जाली ARP जवाब डालता है।`,"Attackers send millions of forged SYN packets without completing the handshake, exhausting the server’s SYN_RCVD backlog.":`हमलावर हैंडशेक पूरा किए बिना लाखों नकली SYN पैकेट भेजते हैं, जिससे सर्वर की SYN_RCVD कतार भर जाती है।`,"Attribute-Value Pairs (AVPs) + Shared Secret Authenticator":`एट्रिब्यूट-वैल्यू जोड़े (AVP) + साझा-गुप्त ऑथेंटिकेटर`,"Audio, video, and metadata packets are interleaved into 128-byte/4KB RTMP chunks.":`ऑडियो, वीडियो और मेटाडेटा पैकेट 128-बाइट/4KB RTMP चंक में आपस में पिरोए जाते हैं।`,"Auth Failure (0xFF)":`प्रमाणीकरण विफल (0xFF)`,"Auth Rejected (Permission Denied)":`प्रमाणीकरण अस्वीकृत (अनुमति नहीं)`,"Auth returns A record + RRSIG signature":`ऑथोरिटेटिव सर्वर A रिकॉर्ड + RRSIG हस्ताक्षर लौटाता है`,"Authenticate & receive public IP (MTU 1492)":`प्रमाणित हों और सार्वजनिक IP पाएँ (MTU 1492)`,"Authenticate + mount \\\\filesrv\\shared":`प्रमाणित करें + \\\\filesrv\\shared माउंट करें`,"Authenticate peers & create Child ESP SA":`पीयर प्रमाणित करें और चाइल्ड ESP SA बनाएँ`,Authentication:a,Authoritative:o,"Authoritative Answer":`ऑथोरिटेटिव जवाब`,"Authoritative NS":`ऑथोरिटेटिव NS`,"Authoritative NS Down":`ऑथोरिटेटिव NS बंद`,"Authoritative NS returns A record + TTL":`ऑथोरिटेटिव NS, A रिकॉर्ड + TTL लौटाता है`,"Authoritative server returns A 203.0.113.10 paired with RRSIG signed by ZSK/KSK.":`ऑथोरिटेटिव सर्वर A 203.0.113.10 के साथ ZSK/KSK से हस्ताक्षरित RRSIG लौटाता है।`,"Authoritative server returns A 203.0.113.10 with AA=1 and TTL=300 seconds.":`ऑथोरिटेटिव सर्वर AA=1 और TTL=300 सेकंड के साथ A 203.0.113.10 लौटाता है।`,"Automated bots scan port 22 trying thousands of common username/password pairs.":`स्वचालित बॉट पोर्ट 22 को स्कैन करके हज़ारों आम यूज़रनेम/पासवर्ड जोड़े आज़माते हैं।`,"Autonomous System Number — globally unique identifier assigned to networks speaking BGP on the internet.":`ऑटोनॉमस सिस्टम नंबर — इंटरनेट पर BGP बोलने वाले नेटवर्क को दिया गया विश्व-स्तर पर अनोखा पहचान नंबर।`,"Autonomous Systems open a reliable TCP session on port 179 before exchanging BGP messages.":`BGP संदेश बदलने से पहले ऑटोनॉमस सिस्टम पोर्ट 179 पर भरोसेमंद TCP सेशन खोलते हैं।`,"BGP 3-AS Peering & Failover":`3-AS BGP पीयरिंग और फ़ेलओवर`,"BGP Prefix Hijacking":`BGP प्रीफ़िक्स हाइजैकिंग`,"BGP hijacking":`BGP हाइजैकिंग`,'BGP is how postal hubs across different countries tell each other: "To reach ZIP code 203.0.113.0/24, pass the letter through Hub 64510 and Hub 64511."':`BGP ऐसे है जैसे अलग-अलग देशों के डाक केंद्र एक-दूसरे को बताते हैं: "पिन कोड 203.0.113.0/24 तक पहुँचने के लिए चिट्ठी को केंद्र 64510 और केंद्र 64511 से गुज़ारो।"`,"BGP is the exterior routing protocol that glues together the global internet’s Autonomous Systems (ISPs, clouds, CDNs) by exchanging reachable IP prefixes and AS_PATH loop-free attributes.":`BGP वह बाहरी रूटिंग प्रोटोकॉल है जो पहुँच योग्य IP प्रीफ़िक्स और लूप-रहित AS_PATH विशेषताओं का आदान-प्रदान करके वैश्विक इंटरनेट के ऑटोनॉमस सिस्टम (ISP, क्लाउड, CDN) को जोड़ता है।`,"BGP peering":`BGP पीयरिंग`,"BGP peers establish TCP connection":`BGP पीयर TCP कनेक्शन बनाते हैं`,"BGP prefers shorter AS_PATHs when Local Preference is tied.":`Local Preference बराबर होने पर BGP छोटे AS_PATH को प्राथमिकता देता है।`,"BGP routes are advertised":`BGP रूट घोषित होते हैं`,"BGP runs over TCP port 179 for reliable incremental route updates.":`BGP भरोसेमंद क्रमिक रूट अपडेट के लिए TCP पोर्ट 179 पर चलता है।`,"BGP selects shortest loop-free AS_PATH":`BGP सबसे छोटा लूप-रहित AS_PATH चुनता है`,"BOOTP-derived Binary Options (TLV)":`BOOTP से बने बाइनरी विकल्प (TLV)`,"Backend #2 Down (Failover)":`बैकएंड #2 बंद (फ़ेलओवर)`,"Backend Pool #1":`बैकएंड पूल #1`,"Backend Pool #2":`बैकएंड पूल #2`,"Bandwidth (Mbps)":`बैंडविड्थ (Mbps)`,"Bastion Firewall":`बास्शन फ़ायरवॉल`,"Because Active mode requires the server to open a connection back to the client through NAT":`क्योंकि एक्टिव मोड में सर्वर को NAT के पार क्लाइंट की ओर वापस कनेक्शन खोलना पड़ता है`,"Because DNS failed":`क्योंकि DNS विफल हो गया`,"Because DoH blends into TCP/443 HTTPS, enterprise DNS firewalls cannot filter malicious domains unless configured.":`DoH, TCP/443 के HTTPS में घुल जाता है, इसलिए कॉन्फ़िगर किए बिना एंटरप्राइज़ DNS फ़ायरवॉल हानिकारक डोमेन फ़िल्टर नहीं कर पाते।`,"Because PASV uses UDP":`क्योंकि PASV UDP इस्तेमाल करता है`,"Because TCP requires encryption":`क्योंकि TCP को एन्क्रिप्शन चाहिए`,"Because UDP does not support unicast":`क्योंकि UDP यूनिकास्ट का समर्थन नहीं करता`,"Because UDP has no handshake, attackers spoof the victim’s source IP to trigger huge replies from DNS/NTP/Memcached.":`UDP में हैंडशेक नहीं होता, इसलिए हमलावर पीड़ित का सोर्स IP जाली बनाकर DNS/NTP/Memcached से बहुत बड़े जवाब भिजवाते हैं।`,"Because fiber is slower":`क्योंकि फ़ाइबर धीमा है`,"Before whispering secrets, you and the server publicly mix paint colors (key exchange) to create a shared secret key nobody watching can unmix, then verify their ID badge (certificate).":`राज़ की बात कहने से पहले आप और सर्वर सबके सामने रंग मिलाते हैं (की एक्सचेंज) और ऐसी साझा गुप्त कुंजी बनाते हैं जिसे देखने वाला कोई अलग नहीं कर सकता; फिर आप उसका पहचान-पत्र (सर्टिफ़िकेट) जाँचते हैं।`,"Bidirectional RTP audio packets flow directly until one party sends SIP BYE.":`दोनों दिशाओं के RTP ऑडियो पैकेट सीधे बहते हैं जब तक कोई पक्ष SIP BYE न भेजे।`,"Binary BGP Messages (OPEN, UPDATE, KEEPALIVE, NOTIFICATION)":`बाइनरी BGP संदेश (OPEN, UPDATE, KEEPALIVE, NOTIFICATION)`,"Binary DNS Wire Format (Header + QNAME labels + RRs)":`बाइनरी DNS वायर फ़ॉर्मैट (हेडर + QNAME लेबल + RR)`,"Binary Greeting + Auth + Relay Header":`बाइनरी अभिवादन + प्रमाणीकरण + रिले हेडर`,"Binary Packet Protocol (Encrypted + MAC/AEAD)":`बाइनरी पैकेट प्रोटोकॉल (एन्क्रिप्टेड + MAC/AEAD)`,"Binary SMB2/3 Header + AES-GCM Encrypted Payloads":`बाइनरी SMB2/3 हेडर + AES-GCM एन्क्रिप्टेड पेलोड`,"Binding Request discovers NAT external IP:port":`Binding Request NAT का बाहरी IP:पोर्ट खोजता है`,"BlastRADIUS (MD5 Collision Forgery)":`BlastRADIUS (MD5 टकराव से जालसाज़ी)`,"Blocking ICMP Fragmentation Needed causes PMTUD blackholes on links with smaller MTUs.":`ICMP Fragmentation Needed रोकने से छोटे MTU वाले लिंक पर PMTUD ब्लैकहोल बन जाते हैं।`,Blowfish:s,"Bogus / Forged Signature (SERVFAIL)":`फ़र्ज़ी / जाली हस्ताक्षर (SERVFAIL)`,"Bogus DNSSEC responses trigger SERVFAIL to protect clients from poisoned data.":`जाली DNSSEC जवाब क्लाइंट को ज़हरीले डेटा से बचाने के लिए SERVFAIL पैदा करते हैं।`,"Bogus spoofed answers fail RRSIG verification and return SERVFAIL":`नकली स्पूफ़ किए जवाब RRSIG जाँच में विफल होते हैं और SERVFAIL लौटाते हैं`,"Border Gateway Protocol (BGP-4)":`बॉर्डर गेटवे प्रोटोकॉल (BGP-4)`,"Both hosts need their subnet router interface as default gateway":`दोनों होस्ट को अपने सबनेट के राउटर इंटरफ़ेस को डिफ़ॉल्ट गेटवे बनाना होगा`,"Both share PMK (from PSK); AP sends ANonce so STA can derive the session PTK.":`दोनों के पास PMK (PSK से) है; AP ANonce भेजता है ताकि STA सेशन PTK निकाल सके।`,"Both sides cleanly close their half-duplex byte streams with FIN and final ACK.":`दोनों पक्ष FIN और अंतिम ACK से अपनी-अपनी बाइट-स्ट्रीम साफ़-सुथरे ढंग से बंद करते हैं।`,"Both verify Confirm tokens, proving both know the passphrase with Forward Secrecy.":`दोनों Confirm टोकन जाँचते हैं, जिससे फ़ॉरवर्ड सीक्रेसी के साथ साबित होता है कि दोनों को पासफ़्रेज़ पता है।`,"Breaking security":`सुरक्षा तोड़ना`,"Broadcast discovery -> BRAS offer":`ब्रॉडकास्ट डिस्कवरी -> BRAS की पेशकश`,"Broadcasting REQUEST lets competing DHCP servers withdraw their unchosen offers.":`REQUEST ब्रॉडकास्ट करने से प्रतिस्पर्धी DHCP सर्वर अपने न चुने गए ऑफ़र वापस ले सकते हैं।`,Browser:c,"Browser Client":`ब्राउज़र क्लाइंट`,"Browser aborts connection before sending HTTP cookies":`ब्राउज़र HTTP कुकी भेजने से पहले कनेक्शन रोक देता है`,"Browser blocks DoH if local proxy tampers with TLS certificate":`अगर कोई लोकल प्रॉक्सी TLS सर्टिफ़िकेट से छेड़छाड़ करे तो ब्राउज़र DoH रोक देता है`,"Browser cookies":`ब्राउज़र कुकी`,"Browser opens an HTTPS/TLS 1.3 tunnel to Cloudflare/Google DoH endpoint.":`ब्राउज़र Cloudflare/Google DoH एंडपॉइंट तक HTTPS/TLS 1.3 सुरंग खोलता है।`,"Browser parses HTML DOM, fetches linked CSS/JS assets over keep-alive, and renders the page.":`ब्राउज़र HTML DOM पार्स करता है, जुड़ी हुई CSS/JS फ़ाइलें keep-alive कनेक्शन पर लाता है और पेज दिखाता है।`,"Browser parses URL & builds HTTP GET":`ब्राउज़र URL पढ़कर HTTP GET बनाता है`,"Browser parses http://www.example.com/ and prepares a GET request before resolving the hostname.":`ब्राउज़र http://www.example.com/ को पढ़ता है और होस्टनेम रिज़ॉल्व करने से पहले GET अनुरोध तैयार करता है।`,"Browsers send cookies on WS upgrade; servers that skip Origin checks can be hijacked.":`ब्राउज़र WS अपग्रेड पर कुकी भेजते हैं; जो सर्वर Origin जाँच छोड़ देते हैं उन्हें हाइजैक किया जा सकता है।`,"Brute-Force Password Guessing":`ब्रूट-फ़ोर्स से पासवर्ड का अंदाज़ा`,"By broadcasting ARP":`ARP ब्रॉडकास्ट करके`,"By checking TTL=0":`TTL=0 जाँचकर`,"By disabling UDP":`UDP बंद करके`,"By flooding ARP":`ARP फ़्लड करके`,"By inspecting the source MAC address of incoming frames":`आने वाले फ़्रेम का सोर्स MAC पता जाँचकर`,"By keeping the same IP address":`वही IP पता बनाए रखकर`,"By opening TCP port 22":`TCP पोर्ट 22 खोलकर`,"By querying DNS":`DNS से पूछकर`,"By reading TCP sequence numbers":`TCP सीक्वेंस नंबर पढ़कर`,"By reading the destination IP":`गंतव्य IP पढ़कर`,"By rejecting routes whose AS_PATH already contains its own ASN":`उन रूटों को ठुकराकर जिनके AS_PATH में उसका अपना ASN पहले से है`,"By running DNS queries":`DNS क्वेरी चलाकर`,"By sending probes with incrementing TTL (1, 2, 3...)":`बढ़ते TTL (1, 2, 3...) वाली जाँचें भेजकर`,"C0/C1/C2 + S0/S1/S2 Handshake":`C0/C1/C2 + S0/S1/S2 हैंडशेक`,"CAs vouch that a public key genuinely belongs to the domain name.":`CA गारंटी देते हैं कि सार्वजनिक कुंजी सचमुच उसी डोमेन नाम की है।`,"CHAP Auth Failure":`CHAP प्रमाणीकरण विफल`,"CLI command input":`CLI कमांड इनपुट`,"CMD=0x01 Dst=example.com:443":`CMD=0x01 Dst=example.com:443`,"CONNECT Request":`CONNECT अनुरोध`,"CONNECT example.com:443 -> 200 Connection Established":`CONNECT example.com:443 -> 200 Connection Established`,"CONNECT host:port establishes a transparent TCP tunnel through an HTTP proxy.":`CONNECT host:port, HTTP प्रॉक्सी के आर-पार पारदर्शी TCP सुरंग बनाता है।`,"Cable Medium":`केबल का प्रकार`,"Cable Properties":`केबल के गुण`,"Cable Properties Inspector":`केबल गुण इंस्पेक्टर`,"Cache & Reply":`कैश और जवाब`,"Cache-Control":`Cache-Control`,"Call answered; media parameters agreed":`कॉल उठाई गई; मीडिया पैरामीटर तय`,"Callee rejects call with SIP 486 Busy Here":`कॉल पाने वाला SIP 486 Busy Here से कॉल ठुकराता है`,"Caller sends INVITE with SDP codecs":`कॉल करने वाला SDP कोडेक के साथ INVITE भेजता है`,"Camera requires Digest Authentication before DESCRIBE":`DESCRIBE से पहले कैमरा Digest प्रमाणीकरण माँगता है`,"Can IMAP download just an email’s headers without downloading a 20MB attachment?":`क्या IMAP 20MB अटैचमेंट उतारे बिना ईमेल के सिर्फ़ हेडर उतार सकता है?`,"Can a standard CONNECT proxy read your HTTPS payload without installing a root CA on your device?":`क्या मानक CONNECT प्रॉक्सी आपके डिवाइस पर रूट CA लगाए बिना आपका HTTPS पेलोड पढ़ सकता है?`,"Captive Gateway":`कैप्टिव गेटवे`,"Captive portals intercept unauthenticated guest Wi-Fi devices (using DHCP Option 114 or OS connectivity probes like /generate_204) and redirect them via HTTP 302 to a login/terms page before opening the firewall.":`कैप्टिव पोर्टल बिना प्रमाणित अतिथि Wi-Fi डिवाइस को (DHCP विकल्प 114 या /generate_204 जैसी OS कनेक्टिविटी जाँच से) रोकते हैं और फ़ायरवॉल खोलने से पहले HTTP 302 से लॉगिन/शर्तों वाले पेज पर भेज देते हैं।`,"Capturing EAPOL Msg 1–2 allows offline GPU dictionary attacks against weak Wi-Fi passphrases; KRACK replays Msg 3 to reset nonces.":`EAPOL संदेश 1–2 पकड़ने से कमज़ोर Wi-Fi पासफ़्रेज़ पर ऑफ़लाइन GPU डिक्शनरी हमले संभव होते हैं; KRACK संदेश 3 दोहराकर नॉन्स रीसेट करा देता है।`,"ChaCha20-Poly1305":`ChaCha20-Poly1305`,"Chain Verification (AD=1)":`कड़ी की जाँच (AD=1)`,Challenge:l,"Check Answers":`उत्तर जाँचें`,"Check `telnet 10.10.2.50 502` from both HMI and Guest":"HMI और अतिथि, दोनों से `telnet 10.10.2.50 502` जाँचें","Check port 25/993 connectivity":`पोर्ट 25/993 की कनेक्टिविटी जाँचें`,"Check that Home PC gateway points to 192.168.1.1":`जाँचें कि होम PC का गेटवे 192.168.1.1 है`,"Checking the server’s host key fingerprint (TOFU/known_hosts) prevents man-in-the-middle interception.":`सर्वर की होस्ट कुंजी फ़िंगरप्रिंट (TOFU/known_hosts) जाँचने से बीच में घुसपैठ (MITM) रुकती है।`,"Checks DNS":`DNS जाँचता है`,"Choose packet ordering challenge":`पैकेट क्रम की चुनौती चुनें`,"Choose quiz topic":`क्विज़ का विषय चुनें`,"Chunked Binary Audio/Video/AMF0 Messages":`टुकड़ों में बँटे बाइनरी ऑडियो/वीडियो/AMF0 संदेश`,"Classic Modbus TCP has no auth—anyone who can reach port 502 can stop motors or alter setpoints.":`क्लासिक Modbus TCP में प्रमाणीकरण नहीं है; पोर्ट 502 तक पहुँचने वाला कोई भी मोटर बंद कर सकता है या सेटपॉइंट बदल सकता है।`,"Classic Modbus TCP has zero built-in authentication or encryption":`क्लासिक Modbus TCP में कोई अंतर्निहित प्रमाणीकरण या एन्क्रिप्शन नहीं है`,"Classless Inter-Domain Routing — slash notation (e.g. 192.168.1.0/24) replacing rigid Class A/B/C boundaries.":`क्लासलेस इंटर-डोमेन रूटिंग — स्लैश नोटेशन (जैसे 192.168.1.0/24), जिसने कठोर क्लास A/B/C सीमाओं की जगह ली।`,"Clear capture filter":`कैप्चर फ़िल्टर हटाएँ`,"Cleartext Password Sniffing on Port 110":`पोर्ट 110 पर सादे पासवर्ड की जासूसी`,"Click a port number on the left, then click its protocol on the right.":`बाईं ओर कोई पोर्ट नंबर चुनें, फिर दाईं ओर उसका प्रोटोकॉल चुनें।`,"Click annotation to remove":`हटाने के लिए टिप्पणी पर क्लिक करें`,Client:u,"Client (0.0.0.0)":`क्लाइंट (0.0.0.0)`,"Client Finished & App Data":`क्लाइंट Finished और ऐप डेटा`,"Client Host":`क्लाइंट होस्ट`,"Client Request":`क्लाइंट का अनुरोध`,"Client TLS Termination":`क्लाइंट TLS समापन`,"Client Transmit (T1)":`क्लाइंट भेजता है (T1)`,"Client aborts handshake with TLS Fatal Alert (certificate_expired)":`क्लाइंट TLS फ़ेटल अलर्ट (certificate_expired) के साथ हैंडशेक रोक देता है`,"Client accepts offered IP":`क्लाइंट पेश किया गया IP स्वीकार करता है`,"Client and File Server negotiate SMB 3.1.1 with preauth integrity and AES-GCM.":`क्लाइंट और फ़ाइल सर्वर प्रीऑथ अखंडता और AES-GCM के साथ SMB 3.1.1 तय करते हैं।`,"Client and Server exchange initial sequence numbers (ISN) and negotiate MSS=1460.":`क्लाइंट और सर्वर शुरुआती सीक्वेंस नंबर (ISN) का आदान-प्रदान करते हैं और MSS=1460 तय करते हैं।`,"Client and server negotiate encryption algorithms and derive shared session keys via Curve25519.":`क्लाइंट और सर्वर एन्क्रिप्शन एल्गोरिद्म तय करते हैं और Curve25519 से साझा सेशन कुंजियाँ निकालते हैं।`,"Client asks SOCKS5 proxy to connect to domain/IP on port 443; proxy replies Succeeded (0x00).":`क्लाइंट SOCKS5 प्रॉक्सी से पोर्ट 443 पर डोमेन/IP से जुड़ने को कहता है; प्रॉक्सी Succeeded (0x00) से जवाब देता है।`,"Client authenticates via Kerberos/NTLMv2 and connects to the shared folder tree.":`क्लाइंट Kerberos/NTLMv2 से प्रमाणित होता है और साझा फ़ोल्डर ट्री से जुड़ता है।`,"Client authenticates with mail server over POP3S (995).":`क्लाइंट POP3S (995) पर मेल सर्वर से प्रमाणित होता है।`,"Client broadcasts DHCPDISCOVER":`क्लाइंट DHCPDISCOVER ब्रॉडकास्ट करता है`,"Client broadcasts DHCPREQUEST confirming it accepts 192.168.1.50 from server 192.168.1.1.":`क्लाइंट DHCPREQUEST ब्रॉडकास्ट करके पुष्टि करता है कि वह सर्वर 192.168.1.1 से 192.168.1.50 ले रहा है।`,"Client completes TLS 1.3 handshake with the edge Reverse Proxy.":`क्लाइंट एज रिवर्स प्रॉक्सी के साथ TLS 1.3 हैंडशेक पूरा करता है।`,"Client configures RTP transport ports with SETUP and triggers PLAY.":`क्लाइंट SETUP से RTP ट्रांसपोर्ट पोर्ट सेट करता है और PLAY चलाता है।`,"Client connects to port 50120; RETR downloads file and closes data socket.":`क्लाइंट पोर्ट 50120 से जुड़ता है; RETR फ़ाइल उतारता है और डेटा सॉकेट बंद कर देता है।`,"Client establishes TLS on port 993 and logs in with tagged command a001.":`क्लाइंट पोर्ट 993 पर TLS बनाता है और टैग वाले कमांड a001 से लॉगिन करता है।`,"Client increments TTL=2; ISP Router reveals its hop IP via ICMP Type 11.":`क्लाइंट TTL=2 करता है; ISP राउटर ICMP टाइप 11 से अपने हॉप का IP ज़ाहिर कर देता है।`,"Client inspects folder unread flags and fetches only headers before downloading attachments.":`क्लाइंट फ़ोल्डर के अनपढ़े फ़्लैग देखता है और अटैचमेंट उतारने से पहले सिर्फ़ हेडर लाता है।`,"Client offers No-Auth or Username/Password; SOCKS5 server selects method.":`क्लाइंट बिना प्रमाणीकरण या यूज़रनेम/पासवर्ड का विकल्प देता है; SOCKS5 सर्वर तरीक़ा चुनता है।`,"Client on Subnet A obtains an IP from a centralized DHCP server on Subnet B via IP Helper relay.":`सबनेट A का क्लाइंट IP Helper रिले से सबनेट B के केंद्रीय DHCP सर्वर से IP पाता है।`,"Client opens TCP control channel to port 21 and authenticates.":`क्लाइंट पोर्ट 21 पर TCP कंट्रोल चैनल खोलता है और प्रमाणित होता है।`,"Client opens TCP session to forward proxy 192.0.2.80:3128.":`क्लाइंट फ़ॉरवर्ड प्रॉक्सी 192.0.2.80:3128 तक TCP सेशन खोलता है।`,"Client opens a TCP connection to port 443 before starting TLS.":`TLS शुरू करने से पहले क्लाइंट पोर्ट 443 पर TCP कनेक्शन खोलता है।`,"Client opens ephemeral port 52344 and establishes a reliable TCP stream to port 80 on 203.0.113.10.":`क्लाइंट अस्थायी पोर्ट 52344 खोलता है और 203.0.113.10 के पोर्ट 80 तक भरोसेमंद TCP स्ट्रीम बनाता है।`,"Client opens report.xlsx and reads encrypted SMB3 data chunks.":`क्लाइंट report.xlsx खोलता है और एन्क्रिप्टेड SMB3 डेटा चंक पढ़ता है।`,"Client opens session channel, allocates PTY, and runs shell commands over ChaCha20-Poly1305.":`क्लाइंट सेशन चैनल खोलता है, PTY आवंटित करता है और ChaCha20-Poly1305 पर शेल कमांड चलाता है।`,"Client performs TLS 1.3 handshake directly with origin through the blind TCP tunnel.":`क्लाइंट अंधी TCP सुरंग से होकर सीधे मूल सर्वर के साथ TLS 1.3 हैंडशेक करता है।`,"Client records T4, computes symmetric round-trip delay and slews system clock smoothly.":`क्लाइंट T4 दर्ज करता है, सममित राउंड-ट्रिप देरी निकालता है और सिस्टम घड़ी को धीरे-धीरे ठीक करता है।`,"Client records local originate timestamp T1 and sends 48-byte UDP/123 packet.":`क्लाइंट स्थानीय मूल टाइमस्टैम्प T1 दर्ज करता है और 48-बाइट UDP/123 पैकेट भेजता है।`,"Client resolves the target domain to an IP address via DNS.":`क्लाइंट DNS से लक्ष्य डोमेन को IP पते में बदलता है।`,"Client sends ClientHello with TLS 1.3 cipher suites, SNI=example.com, and ephemeral ECDHE key share.":`क्लाइंट TLS 1.3 साइफ़र सूट, SNI=example.com और अस्थायी ECDHE की-शेयर के साथ ClientHello भेजता है।`,"Client sends GET / HTTP/1.1 (484 B) and Web Server streams back HTTP/1.1 200 OK text/html (12.8 KB).":`क्लाइंट GET / HTTP/1.1 (484 B) भेजता है और वेब सर्वर HTTP/1.1 200 OK text/html (12.8 KB) लौटाता है।`,"Client sends HTTP GET with Connection: Upgrade and a random base64 Sec-WebSocket-Key.":`क्लाइंट Connection: Upgrade और एक यादृच्छिक base64 Sec-WebSocket-Key के साथ HTTP GET भेजता है।`,"Client sends ICMP Type 8 Echo Request (TTL=64) across two routers to 203.0.113.10.":`क्लाइंट दो राउटरों के पार 203.0.113.10 तक ICMP टाइप 8 Echo Request (TTL=64) भेजता है।`,"Client sends OPTIONS and DESCRIBE rtsp://192.168.1.64:554/stream1; camera returns H.264 SDP.":`क्लाइंट OPTIONS और DESCRIBE rtsp://192.168.1.64:554/stream1 भेजता है; कैमरा H.264 SDP लौटाता है।`,"Client sends a 1200B UDP/443 Initial packet combining transport setup and TLS 1.3 ClientHello.":`क्लाइंट 1200B का UDP/443 Initial पैकेट भेजता है जिसमें ट्रांसपोर्ट सेटअप और TLS 1.3 ClientHello दोनों हैं।`,"Client sends a Fatal Alert (certificate_expired) and closes the connection":`क्लाइंट फ़ेटल अलर्ट (certificate_expired) भेजता है और कनेक्शन बंद कर देता है`,"Client sends recursive query to 8.8.8.8":`क्लाइंट 8.8.8.8 को रिकर्सिव क्वेरी भेजता है`,"Client verifies certificate signature, sends Finished, and streams encrypted HTTP Application Data.":`क्लाइंट सर्टिफ़िकेट के हस्ताक्षर की जाँच करता है, Finished भेजता है और एन्क्रिप्टेड HTTP डेटा भेजना शुरू करता है।`,"Client with IP 0.0.0.0 sends UDP broadcast (68 -> 67) asking for any DHCP server on the LAN.":`IP 0.0.0.0 वाला क्लाइंट UDP ब्रॉडकास्ट (68 -> 67) भेजकर LAN पर किसी भी DHCP सर्वर को खोजता है।`,"Client, Proxy, DNS":`क्लाइंट, प्रॉक्सी, DNS`,"Client-to-server XOR masking stops malicious scripts from crafting fake HTTP requests inside WebSocket frames.":`क्लाइंट से सर्वर तक XOR मास्किंग दुर्भावनापूर्ण स्क्रिप्ट को WebSocket फ़्रेम के भीतर नक़ली HTTP अनुरोध गढ़ने से रोकती है।`,"ClientHello (TLS 1.3)":`ClientHello (TLS 1.3)`,"ClientHello Lost":`ClientHello खो गया`,"Clients abort the TLS handshake with Alert level=Fatal, description=certificate_expired.":`क्लाइंट Alert level=Fatal, description=certificate_expired के साथ TLS हैंडशेक रोक देते हैं।`,Close:d,"Close Packet Inspector":`पैकेट इंस्पेक्टर बंद करें`,"Close node tables":`नोड तालिकाएँ बंद करें`,"Close port picker":`पोर्ट चयन बंद करें`,"Closing port 443":`पोर्ट 443 बंद करना`,"Code Complexity":`कोड की जटिलता`,"Collapse Hardware Rail":`हार्डवेयर पैनल सिकोड़ें`,"Collapse Rail":`पैनल सिकोड़ें`,"Collapsed Hardware Palette":`हार्डवेयर पैलेट (सिकुड़ा हुआ)`,"Compare plaintext HTTP credentials vs TLS 1.3 encrypted HTTPS packets on a shared Layer 1 Hub.":`साझा लेयर 1 हब पर सादे HTTP क्रेडेंशियल और TLS 1.3 से एन्क्रिप्टेड HTTPS पैकेट की तुलना करें।`,"Compare the address on Host B with the address of the router interface it connects to.":`होस्ट B का पता उस राउटर इंटरफ़ेस के पते से मिलाएँ जिससे वह जुड़ा है।`,"Compare unsigned DNS cache poisoning against cryptographic RRSIG validation in DNSSEC.":`बिना हस्ताक्षर वाले DNS कैश पॉइज़निंग की तुलना DNSSEC के क्रिप्टोग्राफ़िक RRSIG सत्यापन से करें।`,Confidentiality:f,"Configure port security MAC limits and DHCP snooping rate limits.":`पोर्ट सिक्योरिटी में MAC सीमा और DHCP snooping में रेट लिमिट लगाएँ।`,"Congestion Avoidance":`कंजेशन से बचाव`,"Congestion Control":`कंजेशन कंट्रोल`,"Congestion window doubles each RTT while cwnd < ssthresh.":`जब तक cwnd < ssthresh है, कंजेशन विंडो हर RTT पर दोगुनी होती है।`,"Connect Cable (Shortcut: C)":`केबल जोड़ें (शॉर्टकट: C)`,"Connect Office A (10.1.0.0/24) to Office B (10.2.0.0/24) over an encrypted UDP/51820 tunnel.":`दफ़्तर A (10.1.0.0/24) को दफ़्तर B (10.2.0.0/24) से एन्क्रिप्टेड UDP/51820 सुरंग के ज़रिए जोड़ें।`,"Connect Subnet A (192.168.1.0/24) and Subnet B (192.168.2.0/24) across a static router.":`स्थिर राउटर के पार सबनेट A (192.168.1.0/24) और सबनेट B (192.168.2.0/24) को जोड़ें।`,"Connect port 993 & authenticate":`पोर्ट 993 से जुड़ें और प्रमाणित हों`,"Connect to port 443":`पोर्ट 443 से जुड़ें`,"Connect to proxy :3128":`प्रॉक्सी :3128 से जुड़ें`,Connection:p,"Control Channel (Port 21)":`कंट्रोल चैनल (पोर्ट 21)`,"Control Plane":`कंट्रोल प्लेन`,"Copy packet summary":`पैकेट का सार कॉपी करें`,"Core Services":`मुख्य सेवाएँ`,"Corporate Visibility Bypass":`कॉर्पोरेट दृश्यता से बच निकलना`,"Covert channels hide arbitrary C2 data inside the Echo payload when firewalls block TCP/UDP.":`जब फ़ायरवॉल TCP/UDP रोकते हैं, तो छिपे चैनल Echo पेलोड के भीतर मनमाना C2 डेटा छिपा देते हैं।`,"Create, Read & Close":`बनाएँ, पढ़ें और बंद करें`,"Cross-Site WebSocket Hijacking (CSWSH)":`क्रॉस-साइट WebSocket हाइजैकिंग (CSWSH)`,"Crypto Agility":`क्रिप्टो लचीलापन`,"Cryptokey routing verifies AllowedIPs -> LAN B":`क्रिप्टोकी रूटिंग AllowedIPs जाँचती है -> LAN B`,"Cut / Restore Selected Link":`चुना हुआ लिंक काटें / बहाल करें`,"Cut link AS64500 <-> AS64510 to test failover":`फ़ेलओवर परखने के लिए AS64500 <-> AS64510 लिंक काटें`,"DAI validates ARP bindings against trusted DHCP leases.":`DAI, ARP बाइंडिंग को भरोसेमंद DHCP लीज़ से मिलाकर जाँचता है।`,"DAI validates ARP packets against trusted DHCP snooping bindings.":`DAI, ARP पैकेट को भरोसेमंद DHCP snooping बाइंडिंग से मिलाकर जाँचता है।`,"DHCP + OS Probe":`DHCP + OS जाँच`,"DHCP DORA IP Assignment":`DHCP DORA से IP आवंटन`,"DHCP DORA with Relay Across Router":`राउटर के पार रिले के साथ DHCP DORA`,"DHCP Option 114 / HTTP 302 Redirect + Firewall MAC Allowlist":`DHCP विकल्प 114 / HTTP 302 रीडायरेक्ट + फ़ायरवॉल MAC अनुमति-सूची`,"DHCP Server":`DHCP सर्वर`,"DHCP Server Down (APIPA)":`DHCP सर्वर बंद (APIPA)`,"DHCP Snooping":`DHCP Snooping`,"DHCP Snooping drops server-side DHCP messages arriving on untrusted user ports.":`DHCP Snooping अविश्वसनीय उपयोगकर्ता पोर्ट पर आने वाले सर्वर-पक्ष के DHCP संदेश गिरा देता है।`,"DHCP Starvation":`DHCP स्टार्वेशन`,"DHCP automatically assigns IPv4 addresses, subnet masks, default gateways, and DNS servers to devices joining a network through the 4-step DORA handshake.":`DHCP नेटवर्क से जुड़ने वाले डिवाइस को 4-चरणीय DORA हैंडशेक के ज़रिए IPv4 पता, सबनेट मास्क, डिफ़ॉल्ट गेटवे और DNS सर्वर अपने-आप दे देता है।`,"DHCP leases expire":`DHCP लीज़ समाप्त होती हैं`,"DHCP server":`DHCP सर्वर`,"DHCP server reserves 192.168.1.50 from its pool and sends DHCPOFFER with subnet mask, gateway, and DNS.":`DHCP सर्वर अपने पूल से 192.168.1.50 आरक्षित करता है और सबनेट मास्क, गेटवे और DNS के साथ DHCPOFFER भेजता है।`,"DMZ isolates public services so compromising the web tier does not expose the internal LAN.":`DMZ सार्वजनिक सेवाओं को अलग रखता है ताकि वेब स्तर पर सेंध लगने से आंतरिक LAN उजागर न हो।`,"DNS Amplification DDoS":`DNS एम्प्लिफ़िकेशन DDoS`,"DNS Cache Hit":`DNS कैश हिट`,"DNS Cache Poisoning":`DNS कैश पॉइज़निंग`,"DNS Cache Poisoning & DNSSEC Fix":`DNS कैश पॉइज़निंग और DNSSEC से समाधान`,"DNS Cached":`DNS कैश में`,"DNS Hierarchy (Root -> TLD -> Auth)":`DNS पदानुक्रम (रूट -> TLD -> ऑथोरिटेटिव)`,"DNS Lookup":`DNS खोज`,"DNS MX + SMTP + IMAP form the complete email delivery chain.":`DNS MX + SMTP + IMAP मिलकर ईमेल डिलीवरी की पूरी कड़ी बनाते हैं।`,"DNS MX Lookup":`DNS MX खोज`,"DNS Queries over HTTPS (DoH)":`HTTPS पर DNS क्वेरी (DoH)`,"DNS RRSIG, DNSKEY, DS, NSEC/NSEC3 Records":`DNS RRSIG, DNSKEY, DS, NSEC/NSEC3 रिकॉर्ड`,"DNS Record Types":`DNS रिकॉर्ड के प्रकार`,"DNS Resolution":`DNS रेज़ोल्यूशन`,"DNS Resolver":`DNS रिज़ॉल्वर`,"DNS Server":`DNS सर्वर`,"DNS caching":`DNS कैशिंग`,'DNS is the internet’s phonebook: you ask for "example.com" and it walks from the country directory (root) to the city book (.com) to find the exact street number (203.0.113.10).':`DNS इंटरनेट की फ़ोनबुक है: आप "example.com" पूछते हैं और वह देश की डायरेक्टरी (रूट) से शहर की किताब (.com) तक जाकर ठीक मकान नंबर (203.0.113.10) ढूँढ लाता है।`,"DNS over HTTPS (DoH) wraps binary DNS queries inside standard HTTPS port-443 traffic so ISPs and local Wi-Fi observers cannot snoop or tamper with the websites you look up.":`DNS over HTTPS (DoH) बाइनरी DNS क्वेरी को सामान्य HTTPS पोर्ट-443 ट्रैफ़िक में लपेटता है, ताकि ISP और स्थानीय Wi-Fi पर नज़र रखने वाले आपके खोजे गए वेबसाइटों में ताक-झाँक या छेड़छाड़ न कर सकें।`,"DNS queries":`DNS क्वेरी`,"DNS refreshes TTL":`DNS TTL ताज़ा कर देता है`,"DNS spoofing":`DNS स्पूफ़िंग`,"DNS translates human-readable domain names into IP addresses using a globally distributed, hierarchical tree of root, TLD, and authoritative nameservers backed by TTL-based caching.":`DNS इंसानों के पढ़ने लायक डोमेन नामों को IP पतों में बदलता है। इसके लिए रूट, TLD और ऑथोरिटेटिव नेमसर्वरों का दुनिया भर में फैला पदानुक्रमित ढाँचा और TTL-आधारित कैशिंग काम आती है।`,"DNS uses 8 bytes":`DNS 8 बाइट इस्तेमाल करता है`,"DNS uses UDP port 53 for low-latency single-packet queries, falling back to TCP 53 for large responses.":`कम देरी वाली एक-पैकेट क्वेरी के लिए DNS, UDP पोर्ट 53 इस्तेमाल करता है और बड़े जवाबों के लिए TCP 53 पर लौटता है।`,"DNSSEC adds cryptographic digital signatures (RRSIG) and a hierarchical chain of trust (Root -> TLD DS -> Zone DNSKEY) so validating resolvers detect forged or poisoned DNS answers—note it ensures authenticity, not encryption.":`DNSSEC क्रिप्टोग्राफ़िक डिजिटल हस्ताक्षर (RRSIG) और भरोसे की पदानुक्रमित कड़ी (रूट -> TLD DS -> ज़ोन DNSKEY) जोड़ता है, ताकि जाँच करने वाले रिज़ॉल्वर नकली या ज़हरीले DNS जवाब पकड़ सकें; ध्यान रहे यह प्रामाणिकता देता है, एन्क्रिप्शन नहीं।`,"DNSSEC cryptographic signature and public signing key verifying authenticity of DNS answers.":`DNSSEC क्रिप्टोग्राफ़िक हस्ताक्षर और सार्वजनिक साइनिंग कुंजी, जो DNS जवाबों की प्रामाणिकता जाँचते हैं।`,"DNSSEC guarantees forged A records cannot poison validating resolvers.":`DNSSEC गारंटी देता है कि जाली A रिकॉर्ड जाँच करने वाले रिज़ॉल्वर को ज़हरीला नहीं कर सकते।`,"DNSSEC is a wax royal seal on the phonebook page: anyone can still read the number, but nobody can fake it without breaking the seal.":`DNSSEC फ़ोनबुक के पन्ने पर लगी शाही लाख की मुहर है: नंबर तो कोई भी पढ़ सकता है, पर मुहर तोड़े बिना कोई उसे नकली नहीं बना सकता।`,"DNSSEC prevents tampering/spoofing via signatures; DoH/DoT provide privacy encryption.":`DNSSEC हस्ताक्षरों से छेड़छाड़/स्पूफ़िंग रोकता है; निजता वाला एन्क्रिप्शन DoH/DoT देते हैं।`,"DORA represents the four standard DHCP messages: DISCOVER, OFFER, REQUEST, ACK.":`DORA DHCP के चार मानक संदेश दर्शाता है: DISCOVER, OFFER, REQUEST, ACK.`,"Data Channel Transfer (RETR)":`डेटा चैनल ट्रांसफ़र (RETR)`,"Data Link":`डेटा लिंक`,"Data, Order, Route, Ack":`Data, Order, Route, Ack`,"Datagram Dropped":`डेटाग्राम गिरा`,"Datagrams #2 & #3 travel without ACK blocking":`डेटाग्राम #2 और #3 बिना ACK रुकावट के चलते हैं`,"Decapsulation at Office B":`दफ़्तर B में डीकैप्सुलेशन`,"Decreases by half":`आधा हो जाता है`,"Decrypting TLS at the edge proxy so backends receive plain or re-encrypted internal HTTP":`एज प्रॉक्सी पर TLS डिक्रिप्ट करना ताकि बैकएंड को सादा या दोबारा एन्क्रिप्ट किया आंतरिक HTTP मिले`,"Default Port":`डिफ़ॉल्ट पोर्ट`,Defense:m,"Delay (ms)":`देरी (ms)`,"Delay increases RTT variance; NTP filters outlier sample":`देरी RTT का उतार-चढ़ाव बढ़ाती है; NTP बाहरी नमूने को छान देता है`,"Deletes spam":`स्पैम हटाता है`,"Deletions are committed only when transitioning to UPDATE via QUIT.":`हटाना केवल QUIT के ज़रिए UPDATE स्थिति में जाने पर पक्का होता है।`,"Deploy BCP 38 egress filtering and Response Rate Limiting (RRL) on resolvers.":`रिज़ॉल्वर पर BCP 38 इग्रेस फ़िल्टरिंग और रिस्पॉन्स रेट लिमिटिंग (RRL) लगाएँ।`,"Deploy uRPF (Unicast Reverse Path Forwarding) and BCP 38 ingress filtering.":`uRPF (Unicast Reverse Path Forwarding) और BCP 38 इनग्रेस फ़िल्टरिंग लगाएँ।`,Destination:h,"Destination IP address":`गंतव्य IP पता`,"Destination Reached":`गंतव्य तक पहुँचे`,"Detect loop warning in Topology Validator":`टोपोलॉजी वैलिडेटर में लूप चेतावनी पकड़ें`,"Deterministic RNG Seed":`निश्चित रैंडम सीड`,"Device CLI Terminal":`डिवाइस CLI टर्मिनल`,"Device Hostname":`डिवाइस का होस्टनेम`,"Device Properties Inspector":`डिवाइस गुण इंस्पेक्टर`,"Device table types":`डिवाइस तालिका के प्रकार`,"Diffie-Hellman key exchange + host key verify":`Diffie-Hellman कुंजी विनिमय + होस्ट कुंजी की जाँच`,"Direct P2P UDP + encrypted media stream":`सीधा P2P UDP + एन्क्रिप्टेड मीडिया स्ट्रीम`,"Direct P2P fails; traffic falls back to TURN relay":`सीधा P2P विफल; ट्रैफ़िक TURN रिले पर लौट आता है`,"Disable PasswordAuthentication, require Ed25519 public keys, and rate-limit with fail2ban/MFA.":`PasswordAuthentication बंद करें, Ed25519 सार्वजनिक कुंजियाँ अनिवार्य करें और fail2ban/MFA से दर सीमित करें।`,"Disable SMBv1 completely, block port 445 at internet perimeters, and require SMB Signing + Encryption.":`SMBv1 पूरी तरह बंद करें, इंटरनेट की सीमा पर पोर्ट 445 रोकें और SMB साइनिंग + एन्क्रिप्शन अनिवार्य करें।`,"Disable SSL/TLS < 1.2 and rely on TLS 1.3 downgrade sentinel inside ServerHello.random.":`1.2 से पुराने SSL/TLS बंद करें और ServerHello.random के भीतर मौजूद TLS 1.3 डाउनग्रेड संकेत पर भरोसा करें।`,"Disable `monlist`, restrict control queries, and use NTS (Network Time Security, RFC 8915).":"`monlist` बंद करें, कंट्रोल क्वेरी सीमित करें और NTS (Network Time Security, RFC 8915) का उपयोग करें।","Disable directed broadcast forwarding on routers and rate-limit ICMP responses.":`राउटर पर डायरेक्टेड ब्रॉडकास्ट फ़ॉरवर्डिंग बंद करें और ICMP जवाबों की दर सीमित करें।`,"Disabling DNS":`DNS बंद करना`,"Disabling Nagle":`Nagle बंद करना`,"Disabling certificates":`सर्टिफ़िकेट बंद करना`,"Disconnect Cable":`केबल हटाएँ`,"Discover, Offer, Request, Acknowledge":`Discover, Offer, Request, Acknowledge`,"Distribute HTTPS requests across 3 backend workers and survive a node power-off.":`HTTPS अनुरोधों को 3 बैकएंड वर्करों में बाँटें और एक नोड के बंद होने पर भी चलते रहें।`,"Do IPv6 routers fragment packets in transit?":`क्या IPv6 राउटर रास्ते में पैकेट फ़्रैगमेंट करते हैं?`,"DoH Resolver (1.1.1.1)":`DoH रिज़ॉल्वर (1.1.1.1)`,"DoH server returns signed/resolved A record inside encrypted HTTPS 200 OK.":`DoH सर्वर एन्क्रिप्टेड HTTPS 200 OK के अंदर हस्ताक्षरित/हल किया हुआ A रिकॉर्ड लौटाता है।`,"DoH uses standard HTTPS port 443 (whereas DNS over TLS / DoT uses port 853).":`DoH मानक HTTPS पोर्ट 443 इस्तेमाल करता है (जबकि DNS over TLS / DoT पोर्ट 853 इस्तेमाल करता है)।`,"Does DNSSEC encrypt DNS queries from eavesdroppers?":`क्या DNSSEC जासूसों से DNS क्वेरी को एन्क्रिप्ट करता है?`,"Does RTSP carry the video pixels itself or control the stream?":`क्या RTSP ख़ुद वीडियो पिक्सेल ले जाता है या स्ट्रीम को नियंत्रित करता है?`,"Does WPA3-SAE provide Forward Secrecy?":`क्या WPA3-SAE फ़ॉरवर्ड सीक्रेसी देता है?`,"Does the WPA2 4-way handshake ever send the Wi-Fi password across the air?":`क्या WPA2 का 4-वे हैंडशेक कभी Wi-Fi पासवर्ड हवा में भेजता है?`,"Domain Name System":`डोमेन नेम सिस्टम`,"Domain Name System Security Extensions":`डोमेन नेम सिस्टम सिक्योरिटी एक्सटेंशन`,"Domain, Origin, Relay, Address":`Domain, Origin, Relay, Address`,"Dragonblood Side-Channel / Downgrade":`Dragonblood साइड-चैनल / डाउनग्रेड`,"Drop ClientHello and observe TCP retransmission":`ClientHello गिराएँ और TCP रीट्रांसमिशन देखें`,"Drop a TCP segment and observe RTO recovery":`एक TCP सेगमेंट गिराएँ और RTO रिकवरी देखें`,"Drop first DHCPOFFER and observe client retry":`पहला DHCPOFFER गिराएँ और क्लाइंट की दोबारा कोशिश देखें`,"Drops it silently (stealth)":`उसे चुपचाप गिरा देता है (छिपाव)`,"Duplicate IP / ARP Conflict":`डुप्लिकेट IP / ARP टकराव`,"Duplicate IP Conflict":`डुप्लिकेट IP टकराव`,"During TCP Slow Start, how does cwnd grow per RTT when no packets are lost?":`TCP स्लो स्टार्ट में, पैकेट न खोने पर cwnd हर RTT में कैसे बढ़ता है?`,"Dynamic ARP Inspection (DAI)":`Dynamic ARP Inspection (DAI)`,"Dynamic Host Configuration Protocol":`डायनामिक होस्ट कॉन्फ़िगरेशन प्रोटोकॉल`,"Dynamic, Open, Reserve, Assign":`Dynamic, Open, Reserve, Assign`,"EAP over LAN (EAPOL) uses EtherType 0x888E.":`EAP over LAN (EAPOL) EtherType 0x888E इस्तेमाल करता है।`,"EAPOL Start & Identity":`EAPOL Start और पहचान`,"EAPOL-Key Frames + AES-CCMP Encrypted MPDUs":`EAPOL-Key फ़्रेम + AES-CCMP एन्क्रिप्टेड MPDU`,"ECDH key exchange establishes ephemeral symmetric keys for the rest of the session.":`ECDH कुंजी विनिमय बाक़ी सेशन के लिए अस्थायी सममित कुंजियाँ बनाता है।`,"ECDHE + Certificate + ALPN h2":`ECDHE + सर्टिफ़िकेट + ALPN h2`,"ESP (Encapsulating Security Payload)":`ESP (Encapsulating Security Payload)`,"ESP Tunnel Encapsulation":`ESP टनल एनकैप्सुलेशन`,ETag:g,"Each datagram is self-contained; packet loss does not stall later packets (no head-of-line blocking).":`हर डेटाग्राम अपने-आप में पूरा है; पैकेट खोने से बाद के पैकेट नहीं रुकते (कोई हेड-ऑफ़-लाइन ब्लॉकिंग नहीं)।`,"Each router along the path drops the probe when TTL hits 0 and reveals itself via Time Exceeded.":`रास्ते का हर राउटर TTL के 0 होने पर जाँच गिरा देता है और Time Exceeded से अपनी पहचान बता देता है।`,"Eavesdropping / Credential Sniffing":`जासूसी / लॉगिन जानकारी की चोरी`,"Echo Reply":`इको रिप्लाई`,"Echo Request (Ping)":`इको रिक्वेस्ट (Ping)`,"Ed25519 public-key signature (or password)":`Ed25519 सार्वजनिक-कुंजी हस्ताक्षर (या पासवर्ड)`,"Ed25519/RSA keypairs resist password brute-forcing and never transmit secrets.":`Ed25519/RSA कुंजी-जोड़े पासवर्ड ब्रूट-फ़ोर्स झेलते हैं और कोई गुप्त बात कभी नहीं भेजते।`,"Edge Proxy":`एज प्रॉक्सी`,"Electrical pulses, optical wavelengths, and RF modulation over copper, fiber, and air.":`ताँबे, फ़ाइबर और हवा पर विद्युत स्पंद, प्रकाशीय तरंगदैर्घ्य और RF मॉड्यूलेशन।`,"Email Spoofing & Open Relay Abuse":`ईमेल स्पूफ़िंग और ओपन रिले का दुरुपयोग`,"Email relay":`ईमेल रिले`,"Enable DHCP Snooping on switches to block DHCPOFFER packets on untrusted access ports.":`स्विच पर DHCP Snooping चालू करें ताकि अविश्वसनीय एक्सेस पोर्ट पर DHCPOFFER पैकेट रोके जाएँ।`,"Enable Dynamic ARP Inspection (DAI) with DHCP Snooping on managed switches.":`मैनेज्ड स्विच पर DHCP Snooping के साथ Dynamic ARP Inspection (DAI) चालू करें।`,"Enable HSTS (Strict-Transport-Security) with preload so browsers refuse plain HTTP.":`preload के साथ HSTS (Strict-Transport-Security) चालू करें ताकि ब्राउज़र सादे HTTP से इनकार करें।`,"Enable IGMP Snooping and limit max multicast groups per switch port.":`IGMP Snooping चालू करें और प्रति स्विच पोर्ट मल्टीकास्ट समूहों की अधिकतम संख्या सीमित करें।`,"Enable RA Guard on Layer 2 switches to drop RAs on untrusted access ports.":`अविश्वसनीय एक्सेस पोर्ट पर RA गिराने के लिए लेयर 2 स्विच पर RA Guard चालू करें।`,"Enable SYN Cookies so the server encodes state into the ISN instead of allocating memory.":`SYN Cookies चालू करें ताकि सर्वर मेमोरी घेरने के बजाय स्थिति को ISN में ही कूटबद्ध कर दे।`,"Enable WPA3-only mode where supported and keep AP firmware patched.":`जहाँ समर्थित हो वहाँ केवल-WPA3 मोड चालू करें और AP का फ़र्मवेयर अद्यतन रखें।`,"Enabling SMBv1":`SMBv1 चालू करना`,"Encapsulated directly in IPv4":`सीधे IPv4 में समाया हुआ`,"Encapsulated in Ethernet / PPP / Fiber frames":`ईथरनेट / PPP / फ़ाइबर फ़्रेम में समाया हुआ`,"Encoder and Ingest Server exchange random 1536-byte C1/S1 blocks to sync timestamps.":`एन्कोडर और इनजेस्ट सर्वर टाइमस्टैम्प मिलाने के लिए 1536-बाइट के यादृच्छिक C1/S1 ब्लॉक बदलते हैं।`,"Encoder authenticates with stream key and requests publish rights.":`एन्कोडर स्ट्रीम कुंजी से प्रमाणित होता है और प्रकाशन का अधिकार माँगता है।`,"Encoders push via RTMP/RTMPS while viewers usually watch via HLS/DASH/WebRTC.":`एन्कोडर RTMP/RTMPS से स्ट्रीम भेजते हैं, जबकि दर्शक आमतौर पर HLS/DASH/WebRTC से देखते हैं।`,"Encrypt SMTP session with TLS":`SMTP सेशन को TLS से एन्क्रिप्ट करें`,"Encrypt sessions with TLS or IPsec and use strict RFC 5961 challenge ACKs.":`सेशन को TLS या IPsec से एन्क्रिप्ट करें और RFC 5961 के सख़्त चैलेंज ACK अपनाएँ।`,"Encrypt traffic":`ट्रैफ़िक एन्क्रिप्ट करना`,"Encrypted AEAD Application Data (0x17)":`एन्क्रिप्टेड AEAD एप्लिकेशन डेटा (0x17)`,"Encrypted DNS Response":`एन्क्रिप्टेड DNS जवाब`,"Encrypted GET / -> 200 OK":`एन्क्रिप्टेड GET / -> 200 OK`,"Encrypted HTTP/2 Exchange":`एन्क्रिप्टेड HTTP/2 आदान-प्रदान`,"Encrypted QUIC Packets + Independent Multiplexed Streams":`एन्क्रिप्टेड QUIC पैकेट + स्वतंत्र मल्टीप्लेक्स्ड स्ट्रीम`,"Encrypted auth request signs a challenge with the user’s Ed25519 private key.":`एन्क्रिप्टेड प्रमाणीकरण अनुरोध उपयोगकर्ता की Ed25519 निजी कुंजी से एक चुनौती पर हस्ताक्षर करता है।`,"Encrypted file read over port 445":`पोर्ट 445 पर एन्क्रिप्टेड फ़ाइल पठन`,"Encrypted wire-format DNS query":`एन्क्रिप्टेड वायर-फ़ॉर्मैट DNS क्वेरी`,"Encrypting DNS prevents local attackers or ISPs from reading or forging DNS replies.":`DNS एन्क्रिप्ट करने से स्थानीय हमलावर या ISP DNS जवाब पढ़ या जाली नहीं बना सकते।`,"Encryption, compression, encoding: TLS 1.3, X.509 certificates, MIME, UTF-8.":`एन्क्रिप्शन, कंप्रेशन, एन्कोडिंग: TLS 1.3, X.509 सर्टिफ़िकेट, MIME, UTF-8.`,"End-to-End Mail Flow (SMTP + MX + IMAP)":`शुरू से अंत तक मेल का सफ़र (SMTP + MX + IMAP)`,"End-to-End TLS Inside Tunnel":`सुरंग के भीतर शुरू से अंत तक TLS`,"End-to-end ports, reliability, congestion control: TCP, UDP, QUIC.":`एंड-टू-एंड पोर्ट, भरोसेमंदी, कंजेशन कंट्रोल: TCP, UDP, QUIC.`,"Enforce BCP 38 source-address validation and disable open unauthenticated UDP reflectors.":`BCP 38 सोर्स-एड्रेस सत्यापन लागू करें और खुले, बिना प्रमाणीकरण वाले UDP रिफ़्लेक्टर बंद करें।`,"Enforce IMAPS (TLS port 993) and OAuth2/XOAUTH2 tokens.":`IMAPS (TLS पोर्ट 993) और OAuth2/XOAUTH2 टोकन लागू करें।`,"Enforce Port Security limiting learned MACs per switchport.":`हर स्विचपोर्ट पर सीखे जाने वाले MAC सीमित करने वाली Port Security लागू करें।`,"Enterprise 802.1X authenticates each user individually via RADIUS.":`एंटरप्राइज़ 802.1X हर उपयोगकर्ता को RADIUS से अलग-अलग प्रमाणित करता है।`,"Envelope & message body delivery":`लिफ़ाफ़ा और संदेश-बॉडी की डिलीवरी`,"Ephemeral Diffie-Hellman keys are discarded after each session, providing Perfect Forward Secrecy.":`अस्थायी Diffie-Hellman कुंजियाँ हर सेशन के बाद हटा दी जाती हैं, जिससे परफ़ेक्ट फ़ॉरवर्ड सीक्रेसी मिलती है।`,Ethernet:_,"Ethernet Frames (Max MTU 1492B)":`ईथरनेट फ़्रेम (अधिकतम MTU 1492B)`,"Ethernet frames carry packets across local links using 48-bit MAC addresses. Switches dynamically learn MAC-to-port mappings, while ARP maps IPv4 addresses to MAC addresses.":`ईथरनेट फ़्रेम 48-बिट MAC पतों से स्थानीय लिंक पर पैकेट ले जाते हैं। स्विच अपने-आप सीखते हैं कि कौन-सा MAC किस पोर्ट पर है, जबकि ARP IPv4 पतों को MAC पतों से जोड़ता है।`,"Even if the Wi-Fi password leaks later, previously captured sessions cannot be decrypted.":`Wi-Fi पासवर्ड बाद में लीक हो भी जाए, तो पहले पकड़े गए सेशन डिक्रिप्ट नहीं हो सकते।`,"Even if two friends share a secret password, they don’t shout it in a crowded room. Each picks a random number, mixes it with the password, and checks if the other gets the same secret result.":`दो दोस्त गुप्त पासवर्ड साझा भी करते हों, तो भीड़ भरे कमरे में उसे चिल्लाकर नहीं बोलते। हर कोई एक यादृच्छिक संख्या चुनकर उसे पासवर्ड से मिलाता है और देखता है कि दूसरे को वही गुप्त नतीजा मिला या नहीं।`,"Even the router next door cannot be reached, so the problem is at or before the router.":`बगल का राउटर भी नहीं पहुँचता, इसलिए समस्या राउटर पर या उससे पहले है।`,"Every ACK increases cwnd by 1 MSS, doubling cwnd each round-trip time until ssthresh.":`हर ACK cwnd को 1 MSS बढ़ाता है, इसलिए ssthresh तक cwnd हर राउंड-ट्रिप पर दोगुना होता है।`,"Everyone can reach the network, but the website never answers. Traceroute even reaches the server.":`सब नेटवर्क तक पहुँचते हैं, पर वेबसाइट जवाब नहीं देती। traceroute भी सर्वर तक पहुँच जाता है।`,"Everything inside the HTTP layer (URI path, headers, cookies, body) is encrypted by TLS.":`HTTP परत के भीतर की हर चीज़ (URI पथ, हेडर, कुकी, बॉडी) TLS से एन्क्रिप्ट होती है।`,"Exchange codecs & candidate IPs via signaling":`सिग्नलिंग से कोडेक और कैंडिडेट IP का आदान-प्रदान`,"Expand Hardware & Cabling Rail":`हार्डवेयर और केबल पैनल खोलें`,"Expired Certificate (Alert)":`एक्सपायर्ड सर्टिफ़िकेट (अलर्ट)`,"Expired TLS Certificate":`एक्सपायर्ड TLS सर्टिफ़िकेट`,"Explanation:":`व्याख्या:`,"Explore Logs and Inspector Deck":`लॉग और इंस्पेक्टर पैनल`,"Exponentially (doubles)":`घातांकीय रूप से (दोगुना)`,"Export JSON":`JSON एक्सपोर्ट`,"Exposed Camera Streams on Port 554":`पोर्ट 554 पर खुली कैमरा स्ट्रीम`,"External Internet may access DMZ Web (:80/:443) but is blocked from reaching internal LAN DB (:5432).":`बाहरी इंटरनेट DMZ वेब (:80/:443) तक पहुँच सकता है, पर आंतरिक LAN के DB (:5432) तक नहीं।`,"FC 03 Read Holding Registers":`FC 03 Read Holding Registers`,"FC 03 reads contiguous 16-bit holding registers.":`FC 03 लगातार 16-बिट होल्डिंग रजिस्टर पढ़ता है।`,"FC 06 Write Setpoint":`FC 06 Write Setpoint`,"FIN and ACK":`FIN और ACK`,"FIN packet":`FIN पैकेट`,"FTP active mode":`FTP एक्टिव मोड`,"FTP uses two separate TCP connections: a Control channel on port 21 for commands, and a Data channel for file transfers. Passive mode (PASV) lets clients behind NAT initiate the data connection.":`FTP दो अलग TCP कनेक्शन इस्तेमाल करता है: कमांड के लिए पोर्ट 21 पर कंट्रोल चैनल, और फ़ाइल ट्रांसफ़र के लिए डेटा चैनल। पैसिव मोड (PASV) NAT के पीछे के क्लाइंट को डेटा कनेक्शन शुरू करने देता है।`,'FTP uses two walkie-talkies: one channel (#21) just for saying "Send file report.pdf", and a second cargo pipe where the file bytes actually travel.':`FTP दो वॉकी-टॉकी इस्तेमाल करता है: एक चैनल (#21) सिर्फ़ "report.pdf फ़ाइल भेजो" कहने के लिए, और दूसरा माल ढोने वाली पाइप जिसमें फ़ाइल के बाइट असल में चलते हैं।`,"Fetch camera SDP track metadata":`कैमरा SDP ट्रैक मेटाडेटा लाएँ`,"Fetch mailbox UIDs & subject lines only":`सिर्फ़ मेलबॉक्स के UID और विषय पंक्तियाँ लाएँ`,"Fetch message count and download email":`संदेश गिनती लाएँ और ईमेल डाउनलोड करें`,Fiber:v,"File Server":`फ़ाइल सर्वर`,"File Server replies with its MAC address":`फ़ाइल सर्वर अपने MAC पते से जवाब देता है`,"File Server sends an ARP Reply directly to Laptop A’s MAC; Switch learns MAC-B on Port 2.":`फ़ाइल सर्वर सीधे लैपटॉप A के MAC को ARP Reply भेजता है; स्विच पोर्ट 2 पर MAC-B सीखता है।`,"File Transfer Protocol (Active & Passive)":`फ़ाइल ट्रांसफ़र प्रोटोकॉल (एक्टिव और पैसिव)`,"Files are compressed":`फ़ाइलें संपीड़ित होती हैं`,"Final probe arrives at destination which returns Echo Reply / Port Unreachable.":`अंतिम जाँच गंतव्य पर पहुँचती है, जो Echo Reply / Port Unreachable लौटाता है।`,"Find mail server for recipient domain":`प्राप्तकर्ता के डोमेन का मेल सर्वर खोजें`,"Firewall (NAT)":`फ़ायरवॉल (NAT)`,"Firewall + DMZ Web Server":`फ़ायरवॉल + DMZ वेब सर्वर`,"Firewall Allow & Internet Open":`फ़ायरवॉल अनुमति और इंटरनेट खुला`,"Firewall Block :80":`फ़ायरवॉल :80 रोके`,"Firewall denies FC 06 write from untrusted IP":`फ़ायरवॉल अविश्वसनीय IP से FC 06 लिखना अस्वीकार करता है`,"Firewall permits TCP/80 & 443 to DMZ while denying inbound to Internal LAN":`फ़ायरवॉल DMZ तक TCP/80 और 443 की अनुमति देता है और आंतरिक LAN में आने वाले ट्रैफ़िक को रोकता है`,"First match":`पहला मिलान`,"First query is lost and client retries after timeout":`पहली क्वेरी खो जाती है और क्लाइंट टाइमआउट के बाद दोबारा भेजता है`,"First query walks Root -> TLD -> Auth; second query returns directly from 8.8.8.8 cache":`पहली क्वेरी रूट -> TLD -> ऑथोरिटेटिव तक जाती है; दूसरी सीधे 8.8.8.8 के कैश से लौटती है`,"Fit Diagram to View":`डायग्राम को स्क्रीन में फ़िट करें`,"Fit Topology":`टोपोलॉजी फ़िट करें`,"Fix R2’s route for 10.99.99.0/24 to point away from R1":`10.99.99.0/24 के लिए R2 का रूट ऐसे ठीक करें कि वह R1 से दूर इशारा करे`,"Fixed 40-byte Header + Extension Headers + Payload":`निश्चित 40-बाइट हेडर + एक्सटेंशन हेडर + पेलोड`,"Fixed 40B header, Hop Limit=64->63":`निश्चित 40B हेडर, हॉप लिमिट=64->63`,"Fixed-size binary handshake on TCP 1935":`TCP 1935 पर निश्चित आकार का बाइनरी हैंडशेक`,"Flooding DISCOVER requests with spoofed MAC addresses exhausts the entire IP pool.":`नकली MAC पतों से DISCOVER अनुरोधों की बाढ़ पूरा IP पूल ख़त्म कर देती है।`,"For encryption":`एन्क्रिप्शन के लिए`,"Force immediate TTL=0 Time Exceeded at first router":`पहले राउटर पर तुरंत TTL=0 Time Exceeded कराएँ`,"Forged / Untrusted Certificate MITM":`नकली / अविश्वसनीय सर्टिफ़िकेट वाला MITM`,"Forward Secrecy":`फ़ॉरवर्ड सीक्रेसी`,"Forward Secrecy (ECDHE)":`फ़ॉरवर्ड सीक्रेसी (ECDHE)`,"Forward acts on behalf of clients; reverse acts in front of origin servers":`फ़ॉरवर्ड क्लाइंट की ओर से काम करता है; रिवर्स मूल सर्वरों के सामने काम करता है`,"Forward encrypts DNS":`फ़ॉरवर्ड DNS एन्क्रिप्ट करता है`,"Forward proxies shield/govern clients; reverse proxies shield/scale backend servers.":`फ़ॉरवर्ड प्रॉक्सी क्लाइंट की ढाल बनते/उन्हें नियंत्रित करते हैं; रिवर्स प्रॉक्सी बैकएंड सर्वरों की ढाल बनते/उन्हें बढ़ाते हैं।`,Foundations:y,"Full-Duplex Frames":`फ़ुल-डुप्लेक्स फ़्रेम`,"GET requests only retrieve representations and are safe/idempotent.":`GET अनुरोध सिर्फ़ सामग्री लाते हैं और सुरक्षित/idempotent होते हैं।`,Gateway:b,"Gateway A authenticates with Curve25519 static/ephemeral keys in a single round-trip.":`गेटवे A एक ही राउंड-ट्रिप में Curve25519 स्थिर/अस्थायी कुंजियों से प्रमाणित होता है।`,"Gateway B decrypts, verifies AllowedIPs includes 10.1.0.10, and forwards to Office B Server.":`गेटवे B डिक्रिप्ट करता है, जाँचता है कि AllowedIPs में 10.1.0.10 है, और दफ़्तर B के सर्वर को भेजता है।`,"Gateway Router":`गेटवे राउटर`,"Gateway redirects to splash login page":`गेटवे स्प्लैश लॉगिन पेज पर भेजता है`,"Gateways verify certificates/PSK and install inbound/outbound ESP SPI keys.":`गेटवे सर्टिफ़िकेट/PSK जाँचते हैं और आने/जाने वाली ESP SPI कुंजियाँ लगाते हैं।`,"Gathering host/srflx ICE candidates can expose a user’s local LAN or real public IP behind a VPN.":`host/srflx ICE कैंडिडेट जुटाने से उपयोगकर्ता का स्थानीय LAN या VPN के पीछे का असली सार्वजनिक IP उजागर हो सकता है।`,"Generate Traffic:":`ट्रैफ़िक बनाएँ:`,"Generate traffic from Host 1 and Host 2":`होस्ट 1 और होस्ट 2 से ट्रैफ़िक बनाएँ`,"Give Host B an address in 192.168.2.0/24":`होस्ट B को 192.168.2.0/24 का पता दें`,"Gratuitous ARP replies overwrite Victim’s ARP table unless Dynamic ARP Inspection is enabled":`जब तक Dynamic ARP Inspection चालू न हो, ग्रैच्युटस ARP जवाब पीड़ित की ARP तालिका को बदल देते हैं`,"Guest Phone":`अतिथि फ़ोन`,"Guest sees hotel/airport terms & sign-in portal hosted inside the walled garden.":`अतिथि को होटल/हवाई अड्डे की शर्तें और दीवार वाले बाग़ के भीतर चलने वाला साइन-इन पोर्टल दिखता है।`,"H.264 NAL units streamed over RTP":`H.264 NAL यूनिट RTP पर स्ट्रीम होते हैं`,"H.264 video & AAC audio chunks":`H.264 वीडियो और AAC ऑडियो चंक`,"HMI opens TCP session through OT segmentation firewall to PLC port 502.":`HMI OT सेगमेंटेशन फ़ायरवॉल से होकर PLC के पोर्ट 502 तक TCP सेशन खोलता है।`,"HMI sends MBAP header + Function Code 03 to read 2 holding registers.":`HMI 2 होल्डिंग रजिस्टर पढ़ने के लिए MBAP हेडर + फ़ंक्शन कोड 03 भेजता है।`,"HMI updates Holding Register 0x0001 = 0x01F4 (500 RPM); PLC echoes confirmation.":`HMI होल्डिंग रजिस्टर 0x0001 = 0x01F4 (500 RPM) अपडेट करता है; PLC पुष्टि लौटाता है।`,"HSTS forces browsers to upgrade all future requests to HTTPS automatically.":`HSTS ब्राउज़र को आगे के सारे अनुरोध अपने-आप HTTPS पर अपग्रेड करने को मजबूर करता है।`,"HTML parse, subresource fetch & paint":`HTML पार्स, बाकी संसाधन लाना और चित्रण`,"HTTP 302 Redirect to Login":`लॉगिन के लिए HTTP 302 रीडायरेक्ट`,"HTTP CONNECT / Absolute-URI Requests":`HTTP CONNECT / पूर्ण-URI अनुरोध`,"HTTP CONNECT Tunnel":`HTTP CONNECT सुरंग`,"HTTP Exchange":`HTTP आदान-प्रदान`,"HTTP Forward Proxy & CONNECT Tunnel":`HTTP फ़ॉरवर्ड प्रॉक्सी और CONNECT टनल`,"HTTP Load":`HTTP लोड`,"HTTP Request Smuggling & Header Injection":`HTTP रिक्वेस्ट स्मगलिंग और हेडर इंजेक्शन`,"HTTP Status Classes":`HTTP स्टेटस श्रेणियाँ`,"HTTP Upgrade Handshake -> Binary Masked Frames (RFC 6455)":`HTTP अपग्रेड हैंडशेक -> मास्क किए बाइनरी फ़्रेम (RFC 6455)`,"HTTP Upgrade Request":`HTTP अपग्रेड अनुरोध`,"HTTP has no encryption layer, exposing session tokens and passwords to sniffers.":`HTTP में एन्क्रिप्शन परत नहीं है, इसलिए सेशन टोकन और पासवर्ड स्निफ़र के सामने खुले रहते हैं।`,"HTTP headers, cookies, and HTML payload are encrypted end-to-end inside TLS records.":`HTTP हेडर, कुकी और HTML पेलोड TLS रिकॉर्ड के अंदर शुरू से अंत तक एन्क्रिप्टेड रहते हैं।`,"HTTP is the stateless request-response protocol that powers the World Wide Web. A client opens a TCP connection (after DNS resolution), sends a structured method and headers, and receives status codes, headers, and a payload.":`HTTP वह स्टेटलेस रिक्वेस्ट-रिस्पॉन्स प्रोटोकॉल है जिस पर वर्ल्ड वाइड वेब चलता है। क्लाइंट (DNS रेज़ोल्यूशन के बाद) TCP कनेक्शन खोलता है, एक मेथड और हेडर भेजता है, और बदले में स्टेटस कोड, हेडर और पेलोड पाता है।`,"HTTP over TLS (Secure Hypertext Transfer Protocol)":`TLS पर HTTP (सुरक्षित हाइपरटेक्स्ट ट्रांसफ़र प्रोटोकॉल)`,"HTTP uses UDP":`HTTP UDP इस्तेमाल करता है`,"HTTP vs HTTPS Sniffing on Shared Hub":`साझा हब पर HTTP बनाम HTTPS स्निफ़िंग`,"HTTP-like Control Commands (DESCRIBE, SETUP, PLAY)":`HTTP जैसे कंट्रोल कमांड (DESCRIBE, SETUP, PLAY)`,"HTTP/1.1 relies on TCP for ordered, reliable byte delivery.":`HTTP/1.1 क्रमबद्ध, भरोसेमंद बाइट डिलीवरी के लिए TCP पर निर्भर है।`,"HTTP/2 Front-End -> Internal HTTP/1.1 + X-Forwarded-*":`HTTP/2 फ़्रंट-एंड -> आंतरिक HTTP/1.1 + X-Forwarded-*`,"HTTPS Interception Warnings & MAC Spoofing":`HTTPS इंटरसेप्शन चेतावनियाँ और MAC स्पूफ़िंग`,"HTTPS POST /dns-query":`HTTPS POST /dns-query`,"HTTPS Server":`HTTPS सर्वर`,"HTTPS has no port":`HTTPS का कोई पोर्ट नहीं होता`,"HTTPS is HTTP inside a locked armored briefcase: the postal worker still sees which building address you’re sending to (IP/SNI), but nobody can read or alter the letter inside.":`HTTPS ताला लगे बख़्तरबंद ब्रीफ़केस में रखा HTTP है: डाकिया अब भी देख लेता है कि आप किस इमारत के पते पर भेज रहे हैं (IP/SNI), पर अंदर की चिट्ठी कोई पढ़ या बदल नहीं सकता।`,"HTTPS is slower":`HTTPS धीमा है`,"HTTPS runs on TCP (or UDP/QUIC) port 443 by default.":`HTTPS डिफ़ॉल्ट रूप से TCP (या UDP/QUIC) पोर्ट 443 पर चलता है।`,"HTTPS terminates at edge Reverse Proxy":`HTTPS एज रिवर्स प्रॉक्सी पर समाप्त होता है`,"HTTPS wraps HTTP inside TLS encryption, protecting URLs, headers, cookies, and payloads against eavesdropping and tampering while authenticating the server via X.509 certificates.":`HTTPS, HTTP को TLS एन्क्रिप्शन में लपेटता है, जिससे URL, हेडर, कुकी और पेलोड जासूसी और छेड़छाड़ से बचते हैं, और X.509 सर्टिफ़िकेट से सर्वर की पहचान की पुष्टि होती है।`,"Handshake Overhead":`हैंडशेक का बोझ`,"Handshake with 1.1.1.1:443":`1.1.1.1:443 के साथ हैंडशेक`,"Head-of-Line Blocking":`हेड-ऑफ़-लाइन ब्लॉकिंग`,"Header Size":`हेडर का आकार`,"Headers and cookies travel in cleartext":`हेडर और कुकी सादे टेक्स्ट में जाते हैं`,"Health Checks":`स्वास्थ्य जाँच`,"Health check fails on #2; LB routes all traffic to #1":`#2 पर स्वास्थ्य जाँच विफल; LB पूरा ट्रैफ़िक #1 को भेजता है`,"Hide Hints & Solution":`संकेत और हल छिपाएँ`,"Highest MAC address":`सबसे ऊँचा MAC पता`,"Home Network (NAT/DHCP -> ISP -> Web)":`होम नेटवर्क (NAT/DHCP -> ISP -> वेब)`,"Home PC connects through a Wi-Fi NAT/DHCP router and ISP to reach a public web server.":`घर का PC, Wi-Fi NAT/DHCP राउटर और ISP से होकर एक सार्वजनिक वेब सर्वर तक पहुँचता है।`,"Home Router":`होम राउटर`,"Home Router broadcasts PADI (0x8863); ISP Access Server replies with PADO.":`होम राउटर PADI (0x8863) ब्रॉडकास्ट करता है; ISP का एक्सेस सर्वर PADO से जवाब देता है।`,"Home Router performs PAT outbound to 198.51.100.2":`होम राउटर बाहर जाते ट्रैफ़िक पर 198.51.100.2 के लिए PAT करता है`,"Home Router translates 192.168.1.10 -> 198.51.100.2 via PAT and forwards to 203.0.113.10.":`होम राउटर PAT से 192.168.1.10 -> 198.51.100.2 में बदलता है और 203.0.113.10 की ओर भेजता है।`,"Hop count 16":`हॉप गिनती 16`,Host:x,"Host A cannot reach Host B across the router, yet both hosts and the router look healthy.":`होस्ट A राउटर के पार होस्ट B तक नहीं पहुँच पा रहा, जबकि दोनों होस्ट और राउटर ठीक दिखते हैं।`,"Host A has no default gateway configured":`होस्ट A पर डिफ़ॉल्ट गेटवे सेट नहीं है`,"Host B is powered off":`होस्ट B बंद है`,"Host B's IP address is in a different subnet than its router interface":`होस्ट B का IP पता उसके राउटर इंटरफ़ेस से अलग सबनेट में है`,"Host Join Report":`होस्ट जॉइन रिपोर्ट`,"Host joins multicast group 239.1.1.5":`होस्ट मल्टीकास्ट समूह 239.1.1.5 में शामिल होता है`,"Host queries ff02::2 and Router announces prefix 2001:db8:1::/64 for stateless auto-config.":`होस्ट ff02::2 से पूछता है और राउटर स्टेटलेस ऑटो-कॉन्फ़िग के लिए प्रीफ़िक्स 2001:db8:1::/64 घोषित करता है।`,"Host sends ICMPv6 Neighbor Solicitation (135) to resolve next-hop link-layer MAC.":`होस्ट अगले हॉप का लिंक-लेयर MAC पता खोजने के लिए ICMPv6 Neighbor Solicitation (135) भेजता है।`,"Host sets Src/Dst IP, TTL=64, DF flag, and computes the 16-bit IPv4 header checksum.":`होस्ट स्रोत/गंतव्य IP, TTL=64, DF फ़्लैग सेट करता है और 16-बिट IPv4 हेडर चेकसम निकालता है।`,"Hosting AS64511":`होस्टिंग AS64511`,"Hosting AS64511 sends BGP UPDATE carrying NLRI 203.0.113.0/24 and AS_PATH [64511].":`होस्टिंग AS64511 NLRI 203.0.113.0/24 और AS_PATH [64511] के साथ BGP UPDATE भेजता है।`,"How do phones automatically pop up a hotel Wi-Fi login sheet?":`फ़ोन होटल के Wi-Fi की लॉगिन शीट अपने-आप कैसे दिखा देते हैं?`,"How do you encrypt RTMP stream keys in transit?":`रास्ते में RTMP स्ट्रीम कुंजियाँ कैसे एन्क्रिप्ट करें?`,"How does BGP prevent routing loops between Autonomous Systems?":`BGP ऑटोनॉमस सिस्टम के बीच रूटिंग लूप कैसे रोकता है?`,"How does POP3 differ from IMAP for multi-device users?":`कई डिवाइस इस्तेमाल करने वालों के लिए POP3, IMAP से कैसे अलग है?`,"How does QUIC keep a session alive when a phone switches from Wi-Fi to 5G?":`फ़ोन के Wi-Fi से 5G पर बदलने पर QUIC सेशन को जीवित कैसे रखता है?`,"How does WireGuard respond to an unauthenticated packet from an unknown peer?":`अज्ञात पीयर से आए अप्रमाणित पैकेट पर WireGuard कैसे प्रतिक्रिया देता है?`,"How does an Ethernet switch learn which port a device is connected to?":`ईथरनेट स्विच कैसे सीखता है कि कोई डिवाइस किस पोर्ट से जुड़ा है?`,"How does traceroute discover every router hop along a path?":`traceroute रास्ते के हर राउटर हॉप को कैसे खोजता है?`,"How large is a standard UDP header?":`मानक UDP हेडर कितना बड़ा होता है?`,"How long resolvers may cache the record":`रिज़ॉल्वर रिकॉर्ड को कितनी देर कैश कर सकते हैं`,"How many bits are in an IPv4 address?":`IPv4 पते में कितने बिट होते हैं?`,"How many bits is an IPv6 address?":`IPv6 पता कितने बिट का होता है?`,"How many round-trips (RTTs) does a standard TLS 1.3 handshake add after TCP connects?":`TCP जुड़ने के बाद मानक TLS 1.3 हैंडशेक कितने राउंड-ट्रिप (RTT) जोड़ता है?`,"How many timestamps does NTP use to compute clock offset and network delay?":`घड़ी का अंतर और नेटवर्क देरी निकालने के लिए NTP कितने टाइमस्टैम्प इस्तेमाल करता है?`,"Hypertext Transfer Protocol":`हाइपरटेक्स्ट ट्रांसफ़र प्रोटोकॉल`,"IANA assigned port 1080 to SOCKS.":`IANA ने SOCKS को पोर्ट 1080 दिया है।`,"ICE Hole Punch + DTLS-SRTP":`ICE होल पंच + DTLS-SRTP`,"ICE IP Leak":`ICE IP लीक`,"ICE connectivity checks succeed; DTLS establishes keys for encrypted SRTP audio/video.":`ICE कनेक्टिविटी जाँच सफल होती है; DTLS एन्क्रिप्टेड SRTP ऑडियो/वीडियो के लिए कुंजियाँ बनाता है।`,"ICMP Filtered / Lost":`ICMP फ़िल्टर / खोया`,"ICMP Ping Flood":`ICMP Ping फ़्लड`,"ICMP Redirect":`ICMP Redirect`,"ICMP Tunneling":`ICMP टनलिंग`,"ICMP Type Reference":`ICMP टाइप संदर्भ`,"ICMP delivers network-layer diagnostics and error reporting. Tools like ping (Echo Request/Reply) and traceroute (TTL expiration probes) rely on ICMP control messages.":`ICMP नेटवर्क-लेयर की जाँच और त्रुटि रिपोर्टिंग देता है। ping (Echo Request/Reply) और traceroute (TTL समाप्ति जाँच) जैसे टूल ICMP कंट्रोल संदेशों पर चलते हैं।`,'ICMP is like shouting "Marco!" across a canyon and timing how fast "Polo!" bounces back—or having each relay runner tell you when your message ran out of steps.':`ICMP ऐसा है जैसे घाटी में "मार्को!" चिल्लाकर देखना कि "पोलो!" कितनी जल्दी गूँजकर लौटता है, या हर रिले धावक का बताना कि आपके संदेश की क़दम-सीमा कहाँ ख़त्म हुई।`,"ICMPv6 Neighbor Discovery Protocol (NDP)":`ICMPv6 नेबर डिस्कवरी प्रोटोकॉल (NDP)`,"IDLE Push Notification":`IDLE पुश नोटिफ़िकेशन`,"IEEE 802.11 Frames":`IEEE 802.11 फ़्रेम`,"IEEE 802.11 Wireless Frames":`IEEE 802.11 वायरलेस फ़्रेम`,"IEEE 802.11i WPA2-PSK (4-Way Handshake)":`IEEE 802.11i WPA2-PSK (4-वे हैंडशेक)`,"IEEE 802.3 Ethernet & Address Resolution Protocol":`IEEE 802.3 ईथरनेट और एड्रेस रेज़ोल्यूशन प्रोटोकॉल`,"IGMP Flooding / Rogue Group Join":`IGMP फ़्लडिंग / नकली ग्रुप जॉइन`,"IGMP lets IPv4 hosts join and leave IP multicast groups (224.0.0.0/4) so routers and IGMP-snooping switches only forward live video/IPTV streams to interested receivers.":`IGMP IPv4 होस्ट को IP मल्टीकास्ट समूहों (224.0.0.0/4) में शामिल होने और छोड़ने देता है, ताकि राउटर और IGMP-स्नूपिंग स्विच लाइव वीडियो/IPTV केवल इच्छुक रिसीवर तक भेजें।`,"IGMP snooping listens to Join/Leave messages so multicast only goes to subscribed ports.":`IGMP snooping Join/Leave संदेश सुनता है ताकि मल्टीकास्ट केवल सब्सक्राइब किए पोर्ट तक जाए।`,"IGMP uses IPv4 protocol number 2.":`IGMP IPv4 प्रोटोकॉल नंबर 2 इस्तेमाल करता है।`,"IKE uses UDP 500 and switches to UDP 4500 when NAT-Traversal is detected.":`IKE UDP 500 इस्तेमाल करता है और NAT-ट्रैवर्सल मिलने पर UDP 4500 पर चला जाता है।`,"IKE_AUTH PSK Mismatch":`IKE_AUTH में PSK का बेमेल`,"IKEv1 Aggressive Mode PSK Cracking":`IKEv1 एग्रेसिव मोड में PSK क्रैकिंग`,"IKEv2 SA Payloads + ESP Tunnel Header (SPI, Seq, IV, AEAD)":`IKEv2 SA पेलोड + ESP टनल हेडर (SPI, Seq, IV, AEAD)`,"IMAP IDLE keeps the socket open for instant real-time new email alerts.":`IMAP IDLE सॉकेट खुला रखता है ताकि नई ईमेल की तुरंत रियल-टाइम सूचना मिले।`,"IMAP allows fetching headers or individual MIME parts on demand.":`IMAP हेडर या अलग-अलग MIME हिस्से माँग पर लाने देता है।`,"IMAP is a shared cloud library: your phone, laptop, and tablet all look at the same folders and see immediately when you read or star a message.":`IMAP एक साझा क्लाउड पुस्तकालय है: आपका फ़ोन, लैपटॉप और टैबलेट सभी वही फ़ोल्डर देखते हैं और संदेश पढ़ते या स्टार करते ही तुरंत दिख जाता है।`,"IMAP synchronizes mail folders, read/starred flags, and partial MIME attachments across multiple devices while keeping authoritative state on the mail server.":`IMAP मेल फ़ोल्डर, पढ़ा/स्टार किया गया फ़्लैग और आंशिक MIME अटैचमेंट को कई डिवाइसों में सिंक करता है, जबकि असली स्थिति मेल सर्वर पर ही रहती है।`,"IMAP uses 143 (STARTTLS) and 993 (IMAPS implicit TLS).":`IMAP 143 (STARTTLS) और 993 (IMAPS, इम्प्लिसिट TLS) इस्तेमाल करता है।`,"INVITE -> 180 Ringing":`INVITE -> 180 Ringing`,"IP Address":`IP पता`,"IP Camera":`IP कैमरा`,"IP Camera streams real-time H.264 video frames to client.":`IP कैमरा क्लाइंट को रियल-टाइम H.264 वीडियो फ़्रेम स्ट्रीम करता है।`,"IP Control Protocol (IPCP) negotiates IPv4 configuration after authentication.":`IP Control Protocol (IPCP) प्रमाणीकरण के बाद IPv4 कॉन्फ़िगरेशन तय करता है।`,"IP Proto 50 encrypts inner IP packet":`IP प्रोटो 50 भीतरी IP पैकेट एन्क्रिप्ट करता है`,"IP Source Spoofing":`IP सोर्स स्पूफ़िंग`,'IP addresses are like names on an envelope, while MAC addresses are the exact apartment mailbox numbers in the building. ARP shouts "Who lives in 192.168.1.20?" so the mail carrier knows which mailbox to use.':`IP पते लिफ़ाफ़े पर लिखे नामों जैसे हैं, और MAC पते इमारत में ठीक फ़्लैट के मेलबॉक्स नंबर। ARP चिल्लाकर पूछता है "192.168.1.20 में कौन रहता है?" ताकि डाकिया जान सके कौन-सा मेलबॉक्स चुनना है।`,"IP routing":`IP रूटिंग`,"IPsec is the classic corporate armored truck system: two gateways first sign contracts (IKEv2), then wrap entire internal packets inside an ESP armored outer envelope.":`IPsec क्लासिक कॉर्पोरेट बख़्तरबंद ट्रक व्यवस्था है: दोनों गेटवे पहले अनुबंध पर हस्ताक्षर करते हैं (IKEv2), फिर पूरे आंतरिक पैकेट ESP के बख़्तरबंद बाहरी लिफ़ाफ़े में लपेटते हैं।`,"IPsec secures IP traffic at Layer 3 using IKEv2 (UDP 500/4500) to negotiate Security Associations (SAs) and ESP (IP protocol 50) to encrypt and authenticate entire IP packets in Tunnel Mode.":`IPsec लेयर 3 पर IP ट्रैफ़िक सुरक्षित करता है: IKEv2 (UDP 500/4500) से सुरक्षा समझौते (SA) तय करता है और ESP (IP प्रोटोकॉल 50) से टनल मोड में पूरे IP पैकेट एन्क्रिप्ट व प्रमाणित करता है।`,"IPv4 Address":`IPv4 पता`,"IPv4 Encapsulation":`IPv4 एनकैप्सुलेशन`,"IPv4 Protocol field 17 indicates UDP.":`IPv4 के Protocol फ़ील्ड में 17 UDP दर्शाता है।`,"IPv4 addresses are 32-bit integers usually written as four dotted octets.":`IPv4 पते 32-बिट पूर्णांक हैं जो आमतौर पर बिंदुओं से अलग चार ऑक्टेट के रूप में लिखे जाते हैं।`,"IPv4 exhaustion":`IPv4 का ख़त्म होना`,"IPv4 is the foundational network-layer protocol that routes packets across interconnected networks using 32-bit addresses, longest-prefix matching, TTL hop limits, and optional MTU fragmentation.":`IPv4 नेटवर्क-लेयर का बुनियादी प्रोटोकॉल है जो 32-बिट पते, सबसे लंबे प्रीफ़िक्स का मिलान, TTL हॉप सीमा और वैकल्पिक MTU फ़्रैगमेंटेशन से जुड़े नेटवर्कों के पार पैकेट पहुँचाता है।`,"IPv4 puts a ZIP code and street address on every envelope and gives it 64 hops to reach its destination; each post office decrements the hop counter and picks the best next road.":`IPv4 हर लिफ़ाफ़े पर पिन कोड और गली का पता लगाता है और उसे मंज़िल तक पहुँचने के लिए 64 पड़ाव देता है; हर डाकघर गिनती घटाता है और अगला सबसे अच्छा रास्ता चुनता है।`,"IPv4 requires it":`IPv4 इसकी माँग करता है`,"IPv6 Host":`IPv6 होस्ट`,"IPv6 Packet Forwarding":`IPv6 पैकेट फ़ॉरवर्डिंग`,"IPv6 Router":`IPv6 राउटर`,"IPv6 Server":`IPv6 सर्वर`,"IPv6 eliminates router fragmentation for faster forwarding.":`तेज़ फ़ॉरवर्डिंग के लिए IPv6 राउटर पर फ़्रैगमेंटेशन ख़त्म कर देता है।`,"IPv6 expands address space to 128 bits, eliminates NAT necessity, streamlines routing with a fixed 40-byte header (no header checksum), and replaces ARP with ICMPv6 Neighbor Discovery (NDP) and SLAAC.":`IPv6 पता-स्थान को 128 बिट तक बढ़ाता है, NAT की ज़रूरत ख़त्म करता है, निश्चित 40-बाइट हेडर (बिना हेडर चेकसम) से रूटिंग सरल करता है, और ARP की जगह ICMPv6 नेबर डिस्कवरी (NDP) और SLAAC लाता है।`,"IPv6 gives every grain of sand on Earth billions of unique street addresses, and lets devices automatically configure their own address without needing a middleman.":`IPv6 धरती के हर रेत के कण को अरबों अनोखे पते दे सकता है, और डिवाइस बिना बिचौलिए के अपना पता ख़ुद सेट कर लेते हैं।`,"IPv6 routers never fragment; return ICMPv6 Type 2":`IPv6 राउटर कभी फ़्रैगमेंट नहीं करते; ICMPv6 टाइप 2 लौटाते हैं`,"IPv6 traffic flows using 128-bit addresses with Next Header chaining.":`IPv6 ट्रैफ़िक 128-बिट पतों और Next Header श्रृंखला के साथ चलता है।`,"IPv6 uses 128-bit addresses written as eight 16-bit hexadecimal groups.":`IPv6 128-बिट पते इस्तेमाल करता है जो आठ 16-बिट हेक्साडेसिमल समूहों में लिखे जाते हैं।`,"IPv6 uses ICMPv6 Neighbor Solicitation and Advertisement instead of ARP broadcasts.":`IPv6 ARP ब्रॉडकास्ट की जगह ICMPv6 Neighbor Solicitation और Advertisement इस्तेमाल करता है।`,"ISP BRAS / Access Server":`ISP BRAS / एक्सेस सर्वर`,"ISP Observer":`ISP पर्यवेक्षक`,"ISP Router":`ISP राउटर`,"ISP Router AS64500":`ISP राउटर AS64500`,"ISP Router returns Time Exceeded":`ISP राउटर Time Exceeded लौटाता है`,"ISP rejects wrong broadband PPPoE credentials":`ISP ग़लत ब्रॉडबैंड PPPoE क्रेडेंशियल ठुकराता है`,"ISP sees only opaque TLS packets on port 443—domain name is completely hidden.":`ISP को पोर्ट 443 पर सिर्फ़ अपारदर्शी TLS पैकेट दिखते हैं; डोमेन नाम पूरी तरह छिपा रहता है।`,"If a router sees its own ASN in the AS_PATH attribute, it discards the UPDATE.":`अगर राउटर को AS_PATH विशेषता में अपना ही ASN दिखे, तो वह UPDATE को छोड़ देता है।`,"If the proxy trusts client-supplied X-Forwarded-For headers blindly, attackers can bypass IP allowlists.":`अगर प्रॉक्सी क्लाइंट के भेजे X-Forwarded-For हेडर पर आँख मूँदकर भरोसा करे, तो हमलावर IP अनुमति-सूचियाँ पार कर सकते हैं।`,"If traceroute reaches the destination but traffic is refused, the path is fine: something at the destination, usually a firewall rule, is saying no.":`अगर traceroute गंतव्य तक पहुँचे पर ट्रैफ़िक ठुकराया जाए, तो रास्ता ठीक है: गंतव्य पर कुछ, आमतौर पर फ़ायरवॉल नियम, मना कर रहा है।`,'Imagine mailing a postcard saying "Please send me page 1 of your menu" (GET /), and the restaurant mails back the menu printed on paper anyone along the route could read.':`सोचिए आपने एक पोस्टकार्ड भेजा जिस पर लिखा है "कृपया अपने मेन्यू का पेज 1 भेजिए" (GET /), और रेस्तराँ मेन्यू को ऐसे काग़ज़ पर छापकर लौटाता है जिसे रास्ते में कोई भी पढ़ सकता है।`,"Immediate datagram emission (8B header)":`तुरंत डेटाग्राम भेजना (8B हेडर)`,"Immediately on DELE":`DELE करते ही तुरंत`,"Import JSON":`JSON इंपोर्ट`,"In 802.1X, what are the three architectural roles?":`802.1X में तीन संरचनात्मक भूमिकाएँ कौन-सी हैं?`,"In BGP best-path selection (assuming equal Local Pref), which attribute is normally preferred?":`BGP सर्वश्रेष्ठ-पथ चयन में (Local Pref बराबर मानकर) आमतौर पर कौन-सी विशेषता चुनी जाती है?`,"In ESP Tunnel Mode, what gets encrypted?":`ESP टनल मोड में क्या एन्क्रिप्ट होता है?`,"In HTTPS, which part of an HTTP request is hidden from network sniffers?":`HTTPS में HTTP अनुरोध का कौन-सा हिस्सा नेटवर्क स्निफ़र से छिपा रहता है?`,"In PASV mode, the client initiates both control and data TCP connections outbound.":`PASV मोड में क्लाइंट कंट्रोल और डेटा दोनों TCP कनेक्शन बाहर की ओर ख़ुद शुरू करता है।`,"In Passive mode, server tells NAT-behind client which data port to connect to.":`पैसिव मोड में सर्वर NAT के पीछे के क्लाइंट को बताता है कि किस डेटा पोर्ट से जुड़ना है।`,"In QUIC, packet loss only affects the stream carrying that lost frame, not other multiplexed streams.":`QUIC में पैकेट लॉस केवल उसी स्ट्रीम को प्रभावित करता है जिसमें वह खोया फ़्रेम था, अन्य मल्टीप्लेक्स्ड स्ट्रीम को नहीं।`,"In WPA3, even if a hacker records your entire Wi-Fi login, they cannot test password guesses at home—they only get one live try per connection with the router.":`WPA3 में अगर हैकर आपका पूरा Wi-Fi लॉगिन रिकॉर्ड कर भी ले, तो वह घर पर पासवर्ड अंदाज़े नहीं आज़मा सकता; राउटर के साथ हर कनेक्शन पर उसे बस एक लाइव कोशिश मिलती है।`,"Increasing TTL":`TTL बढ़ाना`,"Independent Datagrams":`स्वतंत्र डेटाग्राम`,"Independent HTTP/3 Streams":`स्वतंत्र HTTP/3 स्ट्रीम`,"Industrial OT Network & Modbus PLC":`औद्योगिक OT नेटवर्क और Modbus PLC`,"Industrial PLC":`औद्योगिक PLC`,Info:S,"Ingest server returns NetStream.Publish.BadName":`इनजेस्ट सर्वर NetStream.Publish.BadName लौटाता है`,"Initiation + Response over UDP/51820":`UDP/51820 पर आरंभ + जवाब`,"Inject Network Fault:":`नेटवर्क में ख़राबी डालें:`,"Inject Segment Loss":`सेगमेंट लॉस डालें`,"Inner LAN packet is encrypted with ChaCha20-Poly1305 and sent as an outer UDP/51820 datagram.":`भीतर का LAN पैकेट ChaCha20-Poly1305 से एन्क्रिप्ट होकर बाहरी UDP/51820 डेटाग्राम के रूप में भेजा जाता है।`,"Inner packet (10.1.0.10 -> 10.2.0.20) is encrypted and wrapped with a new outer IP header.":`भीतरी पैकेट (10.1.0.10 -> 10.2.0.20) एन्क्रिप्ट होकर नए बाहरी IP हेडर में लपेटा जाता है।`,"Inspect AP wireless clients & RADIUS exchange":`AP के वायरलेस क्लाइंट और RADIUS आदान-प्रदान जाँचें`,"Inspect Firewall ACL rules":`फ़ायरवॉल ACL नियम जाँचें`,"Inspect ICMP payload sizes and disallow anomalous non-standard Echo payloads.":`ICMP पेलोड के आकार जाँचें और असामान्य, गैर-मानक Echo पेलोड की अनुमति न दें।`,"Inspect NAT translation table on Home Router":`होम राउटर की NAT ट्रांसलेशन तालिका देखें`,"Inspect PAT translations on NAT Gateway":`NAT गेटवे पर PAT ट्रांसलेशन जाँचें`,"Inspect Switch MAC table (`show mac address-table`)":"स्विच की MAC तालिका जाँचें (`show mac address-table`)","Inspect `arp -a` on Victim PC":"पीड़ित PC पर `arp -a` जाँचें","Inspect live cwnd/ssthresh chart in Metrics panel":`मेट्रिक्स पैनल में लाइव cwnd/ssthresh चार्ट जाँचें`,"Inspect packet hex dump to see plaintext vs ciphertext":`सादा टेक्स्ट बनाम साइफ़रटेक्स्ट देखने के लिए पैकेट का हेक्स डंप जाँचें`,Install:C,"Install AES-CCMP/GCMP keys + 802.11w PMF":`AES-CCMP/GCMP कुंजियाँ + 802.11w PMF लगाएँ`,"Install App":`ऐप इंस्टॉल करें`,"Install GTK/PTK & encrypt 802.11 frames":`GTK/PTK लगाएँ और 802.11 फ़्रेम एन्क्रिप्ट करें`,"Install NetPulse on iPhone / iPad":`iPhone / iPad पर NetPulse इंस्टॉल करें`,"Instead of calling a store directly, you ask your office receptionist (proxy) to dial the number and connect the line without listening in on your private TLS conversation.":`किसी दुकान को सीधे फ़ोन करने के बजाय आप दफ़्तर की रिसेप्शनिस्ट (प्रॉक्सी) से कहते हैं कि नंबर मिलाकर लाइन जोड़ दे, और आपकी निजी TLS बातचीत न सुने।`,'Instead of mailing 1,000 copies of a TV broadcast to everyone on the street, IGMP lets houses put up a flag saying "Deliver Channel 5 here!"':`पूरी गली को टीवी प्रसारण की 1,000 प्रतियाँ डाक से भेजने के बजाय, IGMP घरों को झंडा लगाने देता है: "चैनल 5 यहाँ पहुँचाओ!"`,'Instead of mailing letters back and forth every second (HTTP polling), WebSocket knocks once via HTTP ("Upgrade?") and leaves the walkie-talkie channel open both ways.':`हर सेकंड चिट्ठियाँ भेजने (HTTP पोलिंग) की जगह, WebSocket एक बार HTTP से दस्तक देता है ("अपग्रेड?") और वॉकी-टॉकी चैनल दोनों ओर खुला छोड़ देता है।`,"Interactive Shell Channel":`इंटरैक्टिव शेल चैनल`,"Interactive network simulator canvas":`इंटरैक्टिव नेटवर्क सिम्युलेटर कैनवस`,"Intercepting HTTPS triggers a TLS certificate mismatch error in browsers":`HTTPS को रोकने से ब्राउज़र में TLS सर्टिफ़िकेट बेमेल की त्रुटि आती है`,Internet:w,"Internet Control Message Protocol (Ping & Traceroute)":`इंटरनेट कंट्रोल मैसेज प्रोटोकॉल (Ping और Traceroute)`,"Internet Group Management Protocol (v3)":`इंटरनेट ग्रुप मैनेजमेंट प्रोटोकॉल (v3)`,"Internet Message Access Protocol (IMAP4rev1)":`इंटरनेट मैसेज एक्सेस प्रोटोकॉल (IMAP4rev1)`,"Internet Protocol Security (IKEv2 + ESP)":`इंटरनेट प्रोटोकॉल सिक्योरिटी (IKEv2 + ESP)`,"Internet Protocol Version 4":`इंटरनेट प्रोटोकॉल संस्करण 4`,"Internet Protocol Version 6":`इंटरनेट प्रोटोकॉल संस्करण 6`,"Internet Web":`इंटरनेट वेब`,"Invalid Stream Key":`अमान्य स्ट्रीम कुंजी`,"Invalid Voucher Code":`अमान्य वाउचर कोड`,"Isolate cameras on a dedicated VLAN, disable UPnP, and wrap RTSP inside VPN/RTSPS.":`कैमरों को अलग VLAN में रखें, UPnP बंद करें और RTSP को VPN/RTSPS में लपेटें।`,"It blocks DNS caching":`यह DNS कैशिंग रोकता है`,"It breaks ARP":`यह ARP तोड़ देता है`,"It breaks DHCP":`यह DHCP तोड़ देता है`,"It breaks Path MTU Discovery (Type 3 Code 4)":`यह Path MTU Discovery तोड़ देता है (टाइप 3 कोड 4)`,"It broadcasts an HTTP packet":`वह HTTP पैकेट ब्रॉडकास्ट करता है`,"It cannot use port 80":`यह पोर्ट 80 इस्तेमाल नहीं कर सकता`,"It carries raw HDMI":`यह कच्चा HDMI ले जाता है`,"It controls the stream; RTP carries media":`यह स्ट्रीम को नियंत्रित करता है; RTP मीडिया ले जाता है`,"It disables TLS":`यह TLS बंद कर देता है`,"It lacks modern encryption and suffered catastrophic RCE flaws like EternalBlue":`इसमें आधुनिक एन्क्रिप्शन नहीं है और EternalBlue जैसी भयंकर रिमोट कोड निष्पादन की ख़ामियाँ थीं`,"It limits filenames to 3 letters":`यह फ़ाइलनाम 3 अक्षरों तक सीमित करता है`,"It only sends audio":`यह सिर्फ़ ऑडियो भेजता है`,"It only works on Linux":`यह सिर्फ़ Linux पर चलता है`,"It opens TLS immediately":`वह तुरंत TLS खोलता है`,"It performs a DNS lookup":`वह DNS खोज करता है`,"It replaces IP":`यह IP की जगह लेता है`,"It requires IPv6":`इसे IPv6 चाहिए`,"It sends a TCP RST":`वह TCP RST भेजता है`,"It sends an ICMP ping":`वह ICMP ping भेजता है`,"It steals 192.168.1.1":`वह 192.168.1.1 हथिया लेता है`,"It stops Ethernet switching":`यह ईथरनेट स्विचिंग रोक देता है`,"It uses UDP":`यह UDP इस्तेमाल करता है`,"It uses too much bandwidth":`यह बहुत ज़्यादा बैंडविड्थ लेता है`,"Iterative is encrypted":`इटेरेटिव एन्क्रिप्टेड होती है`,"Jitter (ms)":`जिटर (ms)`,"Jumbo Frames":`Jumbo Frames`,"KEXINIT & Curve25519 ECDH":`KEXINIT और Curve25519 ECDH`,"KRACK & Offline PMKID/Handshake Cracking":`KRACK और ऑफ़लाइन PMKID/हैंडशेक क्रैकिंग`,"Keep-Alive":`Keep-Alive`,"Key Exchange":`की एक्सचेंज`,"LAN Switch":`LAN स्विच`,"LB probes /healthz on Backends #1 & #2":`LB बैकएंड #1 और #2 पर /healthz जाँचता है`,"LPM picks the route with the highest prefix length (e.g. /24 beats /16).":`LPM सबसे लंबे प्रीफ़िक्स वाला रूट चुनता है (जैसे /24, /16 पर भारी पड़ता है)।`,Lab:T,"Laptop A":`लैपटॉप A`,"Laptop A needs File Server’s MAC address and emits an Ethernet broadcast ARP Request.":`लैपटॉप A को फ़ाइल सर्वर का MAC पता चाहिए और वह ईथरनेट ब्रॉडकास्ट ARP Request भेजता है।`,"Laptop STA":`लैपटॉप STA`,"Large Burst (1400B)":`बड़ा बर्स्ट (1400B)`,Layer:E,"Layer 2 (Data Link) / Network Access":`लेयर 2 (डेटा लिंक) / नेटवर्क एक्सेस`,"Layer 2 (Discovery & PPP Session)":`लेयर 2 (डिस्कवरी और PPP सेशन)`,"Layer 2 (Wireless Data Link)":`लेयर 2 (वायरलेस डेटा लिंक)`,"Layer 2 Framing":`लेयर 2 फ़्रेमिंग`,"Layer 3 (Network Control)":`लेयर 3 (नेटवर्क कंट्रोल)`,"Layer 3 (Network Tunnel over UDP)":`लेयर 3 (UDP पर नेटवर्क टनल)`,"Layer 3 (Network)":`लेयर 3 (नेटवर्क)`,"Layer 3 (Network) / TCP-IP Internet":`लेयर 3 (नेटवर्क) / TCP-IP इंटरनेट`,"Layer 4 (Transport)":`लेयर 4 (ट्रांसपोर्ट)`,"Layer 4 (Transport) / TCP-IP Transport":`लेयर 4 (ट्रांसपोर्ट) / TCP-IP ट्रांसपोर्ट`,"Layer 4–6 (UDP-based Encrypted Multiplexed Transport)":`लेयर 4–6 (UDP-आधारित एन्क्रिप्टेड मल्टीप्लेक्स्ड ट्रांसपोर्ट)`,"Layer 5 (Session)":`लेयर 5 (सेशन)`,"Layer 6 (Presentation) / Session Security":`लेयर 6 (प्रेज़ेंटेशन) / सेशन सुरक्षा`,"Layer 7 (AAA) / 802.1X EAP":`लेयर 7 (AAA) / 802.1X EAP`,"Layer 7 (Application Signaling)":`लेयर 7 (एप्लिकेशन सिग्नलिंग)`,"Layer 7 (Application)":`लेयर 7 (एप्लिकेशन)`,"Layer 7 (Application) / Control Plane over TCP":`लेयर 7 (एप्लिकेशन) / TCP पर कंट्रोल प्लेन`,"Layer 7 (Application) / TCP-IP Application":`लेयर 7 (एप्लिकेशन) / TCP-IP एप्लिकेशन`,"Layer 7 (Application) / UDP Transport":`लेयर 7 (एप्लिकेशन) / UDP ट्रांसपोर्ट`,"Layer 7 (Application) over TLS (Layer 6)":`लेयर 7 (एप्लिकेशन), TLS (लेयर 6) के ऊपर`,"Layer 7 (DNS Integrity & Authenticity)":`लेयर 7 (DNS की अखंडता और प्रामाणिकता)`,"Layer 7 (Encrypted DNS inside HTTPS)":`लेयर 7 (HTTPS के अंदर एन्क्रिप्टेड DNS)`,"Layer 7 (HTTP/DHCP Intercept)":`लेयर 7 (HTTP/DHCP रोक)`,"Layer 7 (Industrial OT)":`लेयर 7 (औद्योगिक OT)`,"Layer 7 / Session Media":`लेयर 7 / सेशन मीडिया`,"Learning Progress Summary":`सीखने की प्रगति का सार`,"Leave Lost":`Leave खो गया`,"Legacy NTP servers responded to tiny mode-7 monlist queries with massive client lists, enabling 500x DDoS amplification.":`पुराने NTP सर्वर छोटी मोड-7 monlist क्वेरी पर क्लाइंट की विशाल सूचियाँ लौटाते थे, जिससे 500 गुना DDoS एम्प्लिफ़िकेशन संभव हुआ।`,"Legacy PAP sends passwords in plaintext; PPPoE adds an 8-byte header shrinking Ethernet MTU from 1500 to 1492.":`पुराना PAP पासवर्ड सादे टेक्स्ट में भेजता है; PPPoE 8-बाइट हेडर जोड़कर ईथरनेट MTU को 1500 से घटाकर 1492 कर देता है।`,"Legacy RADIUS over UDP relies on MD5 Response Authenticator without Message-Authenticator.":`UDP पर पुराना RADIUS, Message-Authenticator के बिना MD5 Response Authenticator पर निर्भर है।`,"Legacy SMBv1 had critical RCE flaws and unsigned SMBv2 allows NTLM credential relay.":`पुराने SMBv1 में गंभीर रिमोट कोड निष्पादन की ख़ामियाँ थीं, और बिना हस्ताक्षर वाला SMBv2 NTLM क्रेडेंशियल रिले होने देता है।`,"Linear AIMD growth after ssthresh":`ssthresh के बाद रैखिक AIMD वृद्धि`,"Linearly (+1 MSS)":`रैखिक रूप से (+1 MSS)`,Link:D,"Link Flap & Re-converge":`लिंक का हिलना और दोबारा तालमेल`,"Link Utilization":`लिंक का उपयोग`,"Live video ingest from encoders (OBS) to streaming platforms":`एन्कोडर (OBS) से स्ट्रीमिंग प्लेटफ़ॉर्म तक लाइव वीडियो इनजेस्ट`,"Load balancer maintains availability despite individual backend failures.":`लोड बैलेंसर अलग-अलग बैकएंड के विफल होने पर भी उपलब्धता बनाए रखता है।`,"Local frame delivery, MAC switching, VLANs, Wi-Fi auth: Ethernet, ARP, PPPoE, WPA2, WPA3.":`स्थानीय फ़्रेम डिलीवरी, MAC स्विचिंग, VLAN, Wi-Fi प्रमाणीकरण: Ethernet, ARP, PPPoE, WPA2, WPA3.`,"Logical addressing and global routing: IPv4, IPv6, ICMP, IGMP, BGP, IPsec.":`लॉजिकल एड्रेसिंग और वैश्विक रूटिंग: IPv4, IPv6, ICMP, IGMP, BGP, IPsec.`,"Logs in plaintext":`सादे टेक्स्ट में लॉग करता है`,"Longest AS_PATH":`सबसे लंबा AS_PATH`,"Longest Prefix Match — router forwarding rule choosing the most specific route (highest prefix length /32 down to /0).":`लॉन्गेस्ट प्रीफ़िक्स मैच — राउटर का वह नियम जो सबसे विशिष्ट रूट चुनता है (सबसे लंबा प्रीफ़िक्स, /32 से /0 तक)।`,"Longest-Prefix Match (most specific mask)":`सबसे लंबा प्रीफ़िक्स मिलान (सबसे विशिष्ट मास्क)`,"Longest-prefix lookup & checksum update":`सबसे लंबे प्रीफ़िक्स की खोज और चेकसम अपडेट`,"Looking up example.com says the domain does not exist, but it worked yesterday.":`example.com खोजने पर कहता है कि डोमेन मौजूद नहीं, जबकि कल तक चल रहा था।`,"Loss & Recovery":`लॉस और रिकवरी`,"Loss on Stream 0 only pauses Stream 0; Stream 4 delivers CSS immediately.":`स्ट्रीम 0 में लॉस सिर्फ़ स्ट्रीम 0 को रोकता है; स्ट्रीम 4 CSS तुरंत पहुँचाती है।`,"MAC Flooding":`MAC फ़्लडिंग`,"MAC address":`MAC पता`,"MAC addresses":`MAC पते`,"MAC spoofing":`MAC स्पूफ़िंग`,"MAC table is wiped":`MAC तालिका मिट जाती है`,"MAC/IP allowlisted -> 204 probe passes":`MAC/IP अनुमति-सूची में -> 204 जाँच पास`,"MIC verification fails at AP on EAPOL Msg 2 -> Deauth":`EAPOL संदेश 2 पर AP में MIC जाँच विफल -> Deauth`,"MITM Cert Warning":`MITM सर्टिफ़िकेट चेतावनी`,"MTA sends 220 banner; sender issues EHLO and learns STARTTLS & AUTH extensions.":`MTA 220 बैनर भेजता है; भेजने वाला EHLO देता है और STARTTLS व AUTH एक्सटेंशन जान लेता है।`,"MTU (Bytes)":`MTU (बाइट)`,"MTU 576 Bottleneck":`MTU 576 की रुकावट`,"MTU 576 Fragmentation":`MTU 576 फ़्रैगमेंटेशन`,"MTU Check / Delivery":`MTU जाँच / डिलीवरी`,"MTU Mismatch & IP Fragmentation / PMTUD":`MTU का बेमेल और IP फ़्रैगमेंटेशन / PMTUD`,"MTU Too Small (PMTUD)":`MTU बहुत छोटा (PMTUD)`,"MX Record Lookup":`MX रिकॉर्ड खोज`,"Mail Client":`मेल क्लाइंट`,"Mail Exchanger (MX) records specify the hostnames handling email for a domain.":`Mail Exchanger (MX) रिकॉर्ड बताते हैं कि किसी डोमेन की ईमेल कौन-से होस्टनेम सँभालते हैं।`,"Mail Server (MTA)":`मेल सर्वर (MTA)`,"Mail server rejects login credentials":`मेल सर्वर लॉगिन क्रेडेंशियल ठुकराता है`,"Management Frames":`मैनेजमेंट फ़्रेम`,"Many IP cameras ship with default credentials or unencrypted RTSP exposed to the internet.":`कई IP कैमरे डिफ़ॉल्ट क्रेडेंशियल के साथ या इंटरनेट पर खुले बिना एन्क्रिप्शन वाले RTSP के साथ आते हैं।`,"Mark deleted & commit UPDATE state":`हटाने का निशान लगाएँ और UPDATE स्थिति पक्की करें`,"Maximum Segment Size — largest TCP payload advertised in SYN options (typically MTU - 40 = 1460 bytes).":`मैक्सिमम सेगमेंट साइज़ — SYN विकल्पों में बताया गया सबसे बड़ा TCP पेलोड (आमतौर पर MTU - 40 = 1460 बाइट)।`,"Maximum Transmission Unit — largest L3 packet size (typically 1500B on Ethernet) before fragmentation or ICMP Fragmentation Needed.":`मैक्सिमम ट्रांसमिशन यूनिट — L3 पैकेट का सबसे बड़ा आकार (ईथरनेट पर आमतौर पर 1500B), जिसके बाद फ़्रैगमेंटेशन या ICMP "Fragmentation Needed" होता है।`,"Maximum packet size":`अधिकतम पैकेट आकार`,Medium:O,"Method Greeting":`मेथड अभिवादन`,Methods:k,"Milliseconds (24.0 ms)":`मिलीसेकंड (24.0 ms)`,"Misconfigured proxies let external attackers bounce traffic through internal corporate networks.":`ग़लत कॉन्फ़िगर किए प्रॉक्सी बाहरी हमलावरों को अंदरूनी कॉर्पोरेट नेटवर्क के रास्ते ट्रैफ़िक उछालने देते हैं।`,"Misconfigured static routes bounce packets between R1 and R2 until TTL hits 0.":`ग़लत स्थिर रूट पैकेट को R1 और R2 के बीच तब तक उछालते हैं जब तक TTL 0 न हो जाए।`,"Mixed 10-Question Challenge":`10 सवालों की मिली-जुली चुनौती`,"Mixed WPA2/WPA3 transition mode can allow downgrades back to WPA2 unless transition disable is signaled.":`मिला-जुला WPA2/WPA3 ट्रांज़िशन मोड, जब तक ट्रांज़िशन-डिसेबल का संकेत न दिया जाए, WPA2 पर डाउनग्रेड होने दे सकता है।`,"Modbus TCP (Industrial Control / SCADA)":`Modbus TCP (औद्योगिक नियंत्रण / SCADA)`,"Modbus TCP (port 502) is the ubiquitous industrial automation protocol used by SCADA HMIs to poll sensors and write actuator registers on PLCs. By design, classic Modbus has zero authentication or encryption.":`Modbus TCP (पोर्ट 502) हर जगह मिलने वाला औद्योगिक ऑटोमेशन प्रोटोकॉल है, जिससे SCADA HMI सेंसर पोल करते हैं और PLC के एक्चुएटर रजिस्टर में लिखते हैं। डिज़ाइन के अनुसार क्लासिक Modbus में न प्रमाणीकरण है न एन्क्रिप्शन।`,"Modbus TCP uses IANA well-known port 502.":`Modbus TCP, IANA का प्रसिद्ध पोर्ट 502 इस्तेमाल करता है।`,'Modbus is a super simple factory language where a control screen asks a robot controller: "Read dial #40001" or "Set valve #40002 to 75%."':`Modbus बेहद सरल कारख़ाने की भाषा है, जिसमें कंट्रोल स्क्रीन रोबोट कंट्रोलर से कहती है: "डायल #40001 पढ़ो" या "वाल्व #40002 को 75% पर सेट करो।"`,"Modbus packets are too big":`Modbus पैकेट बहुत बड़े हैं`,"Mode 3 Client request stamps T1":`मोड 3 क्लाइंट अनुरोध T1 अंकित करता है`,"Mode 4 Server stamps receive & transmit":`मोड 4 सर्वर प्राप्ति और प्रेषण अंकित करता है`,"Modern SMB runs directly over TCP port 445.":`आधुनिक SMB सीधे TCP पोर्ट 445 पर चलता है।`,"Move down":`नीचे ले जाएँ`,"Move up":`ऊपर ले जाएँ`,"Msg 3 & 4 + Encrypted Traffic":`संदेश 3 और 4 + एन्क्रिप्टेड ट्रैफ़िक`,"Multicast Stream & Leave":`मल्टीकास्ट स्ट्रीम और लीव`,"Multicast flooding out ports with no interested listeners":`ऐसे पोर्ट पर मल्टीकास्ट फ़्लडिंग जिन पर कोई इच्छुक श्रोता नहीं`,"Multicast router sends periodic IGMP General Query to all-hosts 224.0.0.1.":`मल्टीकास्ट राउटर सभी होस्ट 224.0.0.1 को समय-समय पर IGMP General Query भेजता है।`,"Multiple private LAN hosts share one public WAN IP (198.51.100.1) using distinct source ports.":`निजी LAN के कई होस्ट अलग-अलग सोर्स पोर्ट से एक सार्वजनिक WAN IP (198.51.100.1) साझा करते हैं।`,"Multiplexed Media Chunks":`मल्टीप्लेक्स्ड मीडिया चंक`,"Multiplexed encrypted PTY / SFTP":`मल्टीप्लेक्स्ड एन्क्रिप्टेड PTY / SFTP`,"NAT / PAT Port Translation":`NAT / PAT पोर्ट ट्रांसलेशन`,"NAT Gateway maps 192.168.1.10 and 192.168.1.11 to unique ports on 198.51.100.1.":`NAT गेटवे 192.168.1.10 और 192.168.1.11 को 198.51.100.1 के अलग-अलग पोर्ट से जोड़ता है।`,"NAT exhaustion":`NAT का ख़त्म होना`,"NTP Monlist Amplification":`NTP Monlist एम्प्लिफ़िकेशन`,"NTP operates over UDP port 123.":`NTP UDP पोर्ट 123 पर चलता है।`,"NTP synchronizes computer clocks across variable-latency networks down to milliseconds by exchanging four timestamps (T1, T2, T3, T4) to separate network delay from true clock offset.":`NTP चार टाइमस्टैम्प (T1, T2, T3, T4) के आदान-प्रदान से नेटवर्क की देरी को घड़ी के असली अंतर से अलग करके, बदलती देरी वाले नेटवर्कों में कंप्यूटर की घड़ियों को मिलीसेकंड तक मिलाता है।`,"NXDOMAIN is a reply, not a timeout: the network works, but the zone is missing the record. A timeout would point at connectivity instead.":`NXDOMAIN एक जवाब है, टाइमआउट नहीं: नेटवर्क चल रहा है, पर ज़ोन में रिकॉर्ड नहीं है। टाइमआउट कनेक्टिविटी की ओर इशारा करता।`,'NXDOMAIN means "this name does not exist" according to whoever is responsible for the zone.':`NXDOMAIN का मतलब है ज़ोन के ज़िम्मेदार के अनुसार "यह नाम मौजूद नहीं है"।`,"Nagle Algorithm":`Nagle एल्गोरिद्म`,"Negotiate Dialect (SMBv3.1.1)":`डायलेक्ट तय करें (SMBv3.1.1)`,"Negotiate Diffie-Hellman & crypto suite":`Diffie-Hellman और क्रिप्टो सूट तय करें`,"Negotiate RTP ports and start stream":`RTP पोर्ट तय करें और स्ट्रीम शुरू करें`,"Negotiate smaller MSS=536 during SYN":`SYN के दौरान छोटा MSS=536 तय होता है`,"Neighbor Discovery (NDP)":`नेबर डिस्कवरी (NDP)`,Network:A,"Network Hardware & Cabling Rail":`नेटवर्क हार्डवेयर और केबल पैनल`,"Network Roaming":`नेटवर्क रोमिंग`,"Network Time Protocol (v4)":`नेटवर्क टाइम प्रोटोकॉल (v4)`,"Network/Port Address Translation — maps private RFC 1918 IPs and ports onto a public WAN IP.":`नेटवर्क/पोर्ट एड्रेस ट्रांसलेशन — निजी RFC 1918 IP और पोर्ट को एक सार्वजनिक WAN IP से जोड़ता है।`,Never:j,New:M,"Next Packet (Right Arrow)":`अगला पैकेट (दायाँ तीर)`,"No DHCP server responds; client falls back to 169.254.x.x":`कोई DHCP सर्वर जवाब नहीं देता; क्लाइंट 169.254.x.x पर चला जाता है`,"No protocol step events in this scenario.":`इस परिदृश्य में प्रोटोकॉल चरण की कोई घटना नहीं है।`,"No, DNSSEC provides cryptographic authenticity/integrity, not encryption":`नहीं, DNSSEC क्रिप्टोग्राफ़िक प्रामाणिकता/अखंडता देता है, एन्क्रिप्शन नहीं`,"No, TLS encrypts end-to-end between client and origin":`नहीं, TLS क्लाइंट और मूल सर्वर के बीच शुरू से अंत तक एन्क्रिप्ट करता है`,"No, it sends ANonce/SNonce and a cryptographic MIC":`नहीं, वह ANonce/SNonce और क्रिप्टोग्राफ़िक MIC भेजता है`,"No, only the source host fragments after ICMPv6 Packet Too Big":`नहीं, ICMPv6 Packet Too Big के बाद सिर्फ़ स्रोत होस्ट फ़्रैगमेंट करता है`,"Noise_IKpsk2 Handshake + ChaCha20-Poly1305 Encrypted IP Packets":`Noise_IKpsk2 हैंडशेक + ChaCha20-Poly1305 एन्क्रिप्टेड IP पैकेट`,Nothing:N,"Nothing works. The home PC cannot reach the web server and even basic pings fail immediately.":`कुछ भी नहीं चल रहा। घर का PC वेब सर्वर तक नहीं पहुँच पा रहा और साधारण ping भी तुरंत विफल हो जाते हैं।`,"OFFER Lost (Retry)":`OFFER खो गया (दोबारा कोशिश)`,"OS captive network assistants detect redirects on known probe URLs or RFC 8910 DHCP Option 114.":`OS के कैप्टिव नेटवर्क सहायक जाने-पहचाने जाँच URL पर रीडायरेक्ट या RFC 8910 के DHCP विकल्प 114 को पहचान लेते हैं।`,"OS detects captive network because probe receives HTTP 302 instead of 204 No Content.":`OS पहचान लेता है कि नेटवर्क कैप्टिव है, क्योंकि जाँच को 204 No Content की जगह HTTP 302 मिलता है।`,"OS stub resolver checks local cache, misses, and sends a UDP/53 recursive query (RD=1).":`OS का रिज़ॉल्वर लोकल कैश देखता है, जवाब नहीं मिलता, तो UDP/53 पर रिकर्सिव क्वेरी (RD=1) भेजता है।`,"OT Firewall":`OT फ़ायरवॉल`,"OT Firewall Blocks Write":`OT फ़ायरवॉल लिखना रोकता है`,"OT Firewall restricts Modbus TCP port 502 strictly to authorized SCADA HMIs.":`OT फ़ायरवॉल Modbus TCP पोर्ट 502 को केवल अधिकृत SCADA HMI तक सख़्ती से सीमित रखता है।`,"Observe DHCP Discover/Offer/Request/Ack relayed across Router":`राउटर के पार रिले होते DHCP Discover/Offer/Request/Ack देखें`,"Observe ICMP Fragmentation Needed (MTU 576)":`ICMP Fragmentation Needed (MTU 576) देखें`,"Observe encrypted ChaCha20 UDP/51820 outer packets":`एन्क्रिप्टेड ChaCha20 UDP/51820 बाहरी पैकेट देखें`,"Observe half-open SYN_RCVD exhaustion during a SYN burst and how SYN Cookies neutralize it.":`SYN बर्स्ट के दौरान आधी-खुली SYN_RCVD थकावट देखें और जानें कि SYN Cookies उसे कैसे बेअसर करती हैं।`,"Office A Host":`दफ़्तर A का होस्ट`,"Office B Server":`दफ़्तर B का सर्वर`,"Offline Cracking":`ऑफ़लाइन क्रैकिंग`,"Offline Mode — Cached app active":`ऑफ़लाइन मोड — कैश किया हुआ ऐप चल रहा है`,"Offset = ((T2-T1)+(T3-T4))/2":`ऑफ़सेट = ((T2-T1)+(T3-T4))/2`,"Offset Calculation (T4)":`ऑफ़सेट गणना (T4)`,"On-path or blind attackers inject forged RST segments matching the 4-tuple and sequence window to kill connections.":`रास्ते में बैठे या अंधाधुंध हमलावर 4-ट्यूपल और सीक्वेंस विंडो से मेल खाते नकली RST सेगमेंट डालकर कनेक्शन तोड़ देते हैं।`,"Only DNS queries":`सिर्फ़ DNS क्वेरी`,"Only HTTP support":`सिर्फ़ HTTP समर्थन`,"Only TCP ports":`सिर्फ़ TCP पोर्ट`,"Only for IPv6":`सिर्फ़ IPv6 के लिए`,"Only in Msg 4":`सिर्फ़ संदेश 4 में`,"Only on port 443":`सिर्फ़ पोर्ट 443 पर`,"Only on port 80":`सिर्फ़ पोर्ट 80 पर`,"Only via FTP":`सिर्फ़ FTP से`,"Only with POP3":`सिर्फ़ POP3 के साथ`,"Only with UDP":`सिर्फ़ UDP के साथ`,"Only with WEP":`सिर्फ़ WEP के साथ`,"Open Full Packet Inspector Drawer":`पूरा पैकेट इंस्पेक्टर खोलें`,"Open PC terminal and run `ping 203.0.113.10`":"PC का टर्मिनल खोलें और `ping 203.0.113.10` चलाएँ","Open Proxy Abuse & SSRF":`खुले प्रॉक्सी का दुरुपयोग और SSRF`,"Opening port 445 to the internet":`पोर्ट 445 इंटरनेट के लिए खोलना`,"Origin Server":`मूल सर्वर`,"Outer IP + ChaCha20 Encapsulation":`बाहरी IP + ChaCha20 एनकैप्सुलेशन`,"Overflowing a switch’s CAM table forces it to fail open as a hub and flood all frames.":`स्विच की CAM तालिका भर देने पर वह हब की तरह खुला होकर हर फ़्रेम फ़्लड करने लगता है।`,"PADI -> PADO -> PADR -> PADS establishes the PPPoE Session ID.":`PADI -> PADO -> PADR -> PADS, PPPoE सेशन ID स्थापित करता है।`,"PAP Cleartext Auth & MTU 1492 Blackhole":`PAP सादा प्रमाणीकरण और MTU 1492 ब्लैकहोल`,"PASV Negotiation":`PASV बातचीत`,"PAT rewrites both Source IP and Source Port to multiplex many hosts onto one public IP":`PAT कई होस्ट को एक सार्वजनिक IP पर समेटने के लिए सोर्स IP और सोर्स पोर्ट दोनों दोबारा लिखता है`,"PLAY instructs the server to begin sending RTP packets.":`PLAY सर्वर को RTP पैकेट भेजना शुरू करने का निर्देश देता है।`,"PMTUD discovers bottleneck MTU 576 via ICMP Type 3 Code 4.":`PMTUD, ICMP टाइप 3 कोड 4 से बाधा वाला MTU 576 खोज लेता है।`,"POP3 downloads messages locally and does not sync folder state across devices":`POP3 संदेश स्थानीय रूप से उतारता है और डिवाइसों के बीच फ़ोल्डर की स्थिति सिंक नहीं करता`,"POP3 empties your P.O. box into your backpack and takes the letters home so you can read them offline.":`POP3 आपके डाक बॉक्स को आपके बैग में खाली कर देता है और चिट्ठियाँ घर ले जाता है ताकि आप ऑफ़लाइन पढ़ सकें।`,"POP3 is designed for single-device download; IMAP keeps folders synced on the server.":`POP3 एक डिवाइस पर डाउनलोड के लिए बना है; IMAP सर्वर पर फ़ोल्डर सिंक रखता है।`,"POP3 retrieves stored emails from a mail server to a local client in a simple download-and-delete (or keep) workflow over TCP 110 or TLS 995.":`POP3 मेल सर्वर पर रखी ईमेल को TCP 110 या TLS 995 पर सरल डाउनलोड-और-हटाओ (या रखो) तरीक़े से स्थानीय क्लाइंट तक लाता है।`,"POP3 sends outbound mail":`POP3 भेजी जाने वाली मेल भेजता है`,"POP3 syncs folders in real time":`POP3 फ़ोल्डर को रियल-टाइम में सिंक करता है`,"POP3 uses 110 (plaintext) and 995 (POP3S over TLS).":`POP3 110 (सादा टेक्स्ट) और 995 (TLS पर POP3S) इस्तेमाल करता है।`,"POP3 uses UDP":`POP3 UDP इस्तेमाल करता है`,"PPPoE Discovery (PADI / PADO)":`PPPoE डिस्कवरी (PADI / PADO)`,"PPPoE Discovery (PADI/PADO/PADR/PADS) + PPP LCP/CHAP/IPCP":`PPPoE डिस्कवरी (PADI/PADO/PADR/PADS) + PPP LCP/CHAP/IPCP`,"PPPoE lets ISPs authenticate broadband subscribers (DSL/FTTH) and assign public IPv4 addresses over Ethernet using a 4-step Discovery phase (PADI/PADO/PADR/PADS) followed by PPP LCP, CHAP auth, and IPCP.":`PPPoE ISP को ब्रॉडबैंड ग्राहकों (DSL/FTTH) को प्रमाणित करने और ईथरनेट पर सार्वजनिक IPv4 पते देने देता है: पहले 4-चरणीय डिस्कवरी (PADI/PADO/PADR/PADS), फिर PPP LCP, CHAP प्रमाणीकरण और IPCP।`,"Packet Loss (%)":`पैकेट लॉस (%)`,"Packet Loss (Retransmit)":`पैकेट लॉस (रीट्रांसमिट)`,"Packet Time Format":`पैकेट समय का प्रारूप`,"Packet Too Big (PMTUDv6)":`पैकेट बहुत बड़ा (PMTUDv6)`,"Packet arrives at destination; if larger than link MTU, it fragments or returns ICMP Frag Needed.":`पैकेट गंतव्य पर पहुँचता है; अगर लिंक MTU से बड़ा हो तो वह बँटता है या ICMP "Frag Needed" लौटता है।`,"Packet arrives or fragments if > MTU":`पैकेट पहुँचता है या MTU से बड़ा हो तो टुकड़ों में बँटता है`,"Packet delivery timeline scrubber":`पैकेट डिलीवरी टाइमलाइन`,"Packet loss halves ssthresh and cuts cwnd, creating the classic TCP sawtooth":`पैकेट लॉस ssthresh को आधा करता है और cwnd घटाता है, जिससे क्लासिक TCP आरी बनती है`,"Page Rendering":`पेज रेंडरिंग`,"Passive sniffing and injection of plaintext UDP/53 DNS queries":`सादे UDP/53 DNS क्वेरी की निष्क्रिय जासूसी और इंजेक्शन`,"Path Selection & Propagation":`पथ चयन और प्रसार`,"Path, query string, headers, cookies, and body":`पथ, क्वेरी स्ट्रिंग, हेडर, कुकी और बॉडी`,"Peer A (Behind NAT)":`पीयर A (NAT के पीछे)`,"Peer A queries STUN (UDP 3478) to learn its public reflexive address.":`पीयर A अपना सार्वजनिक रिफ़्लेक्सिव पता जानने के लिए STUN (UDP 3478) से पूछता है।`,"Peer B (Their Laptop)":`पीयर B (उनका लैपटॉप)`,"Peer returns AUTHENTICATION_FAILED notify":`पीयर AUTHENTICATION_FAILED नोटिफ़ाई लौटाता है`,"Peers derive shared symmetric session keys using Diffie-Hellman":`पीयर Diffie-Hellman से साझा सममित सेशन कुंजियाँ निकालते हैं`,"Peers negotiate ASN & capabilities":`पीयर ASN और क्षमताओं पर सहमत होते हैं`,"Peers negotiate MTU 1492, verify CHAP hash, and IPCP assigns public IP 203.0.113.45.":`पीयर MTU 1492 तय करते हैं, CHAP हैश जाँचते हैं, और IPCP सार्वजनिक IP 203.0.113.45 देता है।`,"Peers negotiate TLS 1.3 encryption keys and select HTTP/2 via ALPN.":`पीयर TLS 1.3 एन्क्रिप्शन कुंजियाँ तय करते हैं और ALPN से HTTP/2 चुनते हैं।`,"Peers swap SDP descriptions and ICE candidate lists through the signaling server.":`पीयर सिग्नलिंग सर्वर के ज़रिए SDP विवरण और ICE कैंडिडेट सूचियाँ आपस में बदलते हैं।`,"Phone / STA":`फ़ोन / STA`,"Phone A sends SIP INVITE via SIP Proxy; Phone B alerts user with 180 Ringing.":`फ़ोन A, SIP प्रॉक्सी से SIP INVITE भेजता है; फ़ोन B 180 Ringing से उपयोगकर्ता को सूचित करता है।`,"Phone B answers with 200 OK; Phone A confirms with ACK.":`फ़ोन B 200 OK से जवाब देता है; फ़ोन A ACK से पुष्टि करता है।`,"Phone associates to Access Point, authenticates via RADIUS 802.1X, and reaches the web.":`फ़ोन एक्सेस पॉइंट से जुड़ता है, RADIUS 802.1X से प्रमाणित होता है और वेब तक पहुँचता है।`,"Phone probes /generate_204 or reads DHCP Option 114":`फ़ोन /generate_204 जाँचता है या DHCP विकल्प 114 पढ़ता है`,Physical:P,"Physical Media (Cat6 / Fiber)":`भौतिक माध्यम (Cat6 / फ़ाइबर)`,"Physical Port Bay":`भौतिक पोर्ट बे`,"Ping (0x9) and Pong (0xA)":`Ping (0x9) और Pong (0xA)`,"Ping Host B (192.168.2.20) from Host A (192.168.1.10)":`होस्ट A (192.168.1.10) से होस्ट B (192.168.2.20) को ping करें`,"Ping Office B Server from Office A Host":`दफ़्तर A के होस्ट से दफ़्तर B के सर्वर को ping करें`,"Ping sends Type 8 Echo Request and expects Type 0 Echo Reply.":`Ping टाइप 8 Echo Request भेजता है और टाइप 0 Echo Reply की उम्मीद करता है।`,"Plain HTTP reveals full URI and headers in ASCII hex dump; HTTPS hides them in TLS Application Data":`सादा HTTP पूरा URI और हेडर ASCII हेक्स डंप में दिखा देता है; HTTPS उन्हें TLS Application Data में छिपा लेता है`,"Plain RTMP sends the broadcast stream key over TCP 1935 without encryption.":`सादा RTMP प्रसारण की स्ट्रीम कुंजी को बिना एन्क्रिप्शन के TCP 1935 पर भेजता है।`,"Plain SMTP trusts the MAIL FROM header unless authenticated, letting spammers forge sender domains.":`सादा SMTP प्रमाणीकरण के बिना MAIL FROM हेडर पर भरोसा कर लेता है, जिससे स्पैमर भेजने वाले के डोमेन जाली बना सकते हैं।`,"Plaintext ASCII Headers + Body (MIME)":`सादे ASCII हेडर + बॉडी (MIME)`,"Plaintext Credentials & Data Sniffing":`सादे क्रेडेंशियल और डेटा की जासूसी`,"Plaintext HTTP headers, cookies, and form bodies can be read by any router or Wi-Fi sniffer in transit.":`सादे टेक्स्ट वाले HTTP हेडर, कुकी और फ़ॉर्म डेटा को रास्ते का कोई भी राउटर या Wi-Fi स्निफ़र पढ़ सकता है।`,"Plaintext IMAP Credential Theft":`सादे IMAP क्रेडेंशियल की चोरी`,"Play / Pause (Space)":`चलाएँ / रोकें (स्पेस)`,"Playback in browsers":`ब्राउज़र में प्लेबैक`,"Plug the cable back in":`केबल वापस लगाएँ`,"Point-to-Point Protocol over Ethernet":`ईथरनेट पर पॉइंट-टू-पॉइंट प्रोटोकॉल`,"Pop Out":`अलग खोलें`,"Port (80, 443, any)":`पोर्ट (80, 443, any)`,"Port 143 without STARTTLS leaks credentials.":`STARTTLS के बिना पोर्ट 143 क्रेडेंशियल लीक करता है।`,"Port 21 is control; port 20 is the server source port for active data transfers.":`पोर्ट 21 कंट्रोल है; पोर्ट 20 एक्टिव डेटा ट्रांसफ़र के लिए सर्वर का सोर्स पोर्ट है।`,"Port 587 is dedicated to authenticated MSA mail submission; port 25 is server-to-server relay.":`पोर्ट 587 प्रमाणित MSA मेल सबमिशन के लिए है; पोर्ट 25 सर्वर-से-सर्वर रिले के लिए।`,"Port 80 Closed (RST)":`पोर्ट 80 बंद (RST)`,"Port Closed (RST)":`पोर्ट बंद (RST)`,"Port Forwarding":`Port Forwarding`,"Portal denies voucher and keeps firewall closed":`पोर्टल वाउचर ठुकराता है और फ़ायरवॉल बंद रखता है`,"Post Office Protocol Version 3":`पोस्ट ऑफ़िस प्रोटोकॉल संस्करण 3`,"Power off Backend #2 and send HTTP requests from Client":`बैकएंड #2 बंद करें और क्लाइंट से HTTP अनुरोध भेजें`,Presentation:F,"Previous Packet (Left Arrow)":`पिछला पैकेट (बायाँ तीर)`,"Primary link fails and BGP withdraws route via UPDATE":`मुख्य लिंक विफल होता है और BGP, UPDATE से रूट वापस ले लेता है`,"Printer / Host C":`प्रिंटर / होस्ट C`,"Probe, Open Auth & Association Request":`प्रोब, खुला प्रमाणीकरण और असोसिएशन अनुरोध`,"Properties Inspector":`गुण इंस्पेक्टर`,"Protected Management Frames block spoofed deauthentication floods.":`सुरक्षित मैनेजमेंट फ़्रेम नकली डीऑथेंटिकेशन फ़्लड को रोकते हैं।`,"Protected Management Frames sign management frames so attackers cannot kick clients off Wi-Fi.":`सुरक्षित मैनेजमेंट फ़्रेम, मैनेजमेंट फ़्रेम पर हस्ताक्षर करते हैं ताकि हमलावर क्लाइंट को Wi-Fi से बाहर न निकाल सकें।`,"Protocol 1 is ICMP, 6 is TCP, and 17 is UDP.":`प्रोटोकॉल 1 ICMP है, 6 TCP है और 17 UDP है।`,"Protocol sequence ladder diagram":`प्रोटोकॉल सीक्वेंस डायग्राम`,"Proxy Server":`प्रॉक्सी सर्वर`,"Proxy forwards encrypted TLS bytes blindly":`प्रॉक्सी एन्क्रिप्टेड TLS बाइट आँख मूँदकर आगे भेजता है`,"Proxy forwards to Backend #1 (or #2 on failover)":`प्रॉक्सी बैकएंड #1 को (या फ़ेलओवर पर #2 को) भेजता है`,"Proxy opens TCP to 203.0.113.10:443 and replies 200 Connection Established.":`प्रॉक्सी 203.0.113.10:443 तक TCP खोलता है और 200 Connection Established से जवाब देता है।`,"Proxy rejects unauthenticated CONNECT request":`प्रॉक्सी बिना प्रमाणीकरण वाला CONNECT अनुरोध ठुकराता है`,"Public-key authentication (e.g., Ed25519)":`सार्वजनिक-कुंजी प्रमाणीकरण (जैसे Ed25519)`,"Publish SPF, DKIM, and DMARC DNS policies and require authenticated submission on port 587 with TLS.":`SPF, DKIM और DMARC DNS नीतियाँ प्रकाशित करें और पोर्ट 587 पर TLS के साथ प्रमाणित सबमिशन अनिवार्य करें।`,"QUIC Initial Amplification / 0-RTT Replay":`QUIC Initial एम्प्लिफ़िकेशन / 0-RTT रीप्ले`,"QUIC Transport & HTTP/3":`QUIC ट्रांसपोर्ट और HTTP/3`,"QUIC identifies connections by Connection ID rather than the 4-tuple IP/port.":`QUIC कनेक्शन को IP/पोर्ट 4-ट्यूपल के बजाय Connection ID से पहचानता है।`,"QUIC reimagines transport over UDP port 443 with TLS 1.3 baked in from packet #1 (1-RTT or 0-RTT resume), independent streams that eliminate TCP head-of-line blocking, and Connection IDs that survive Wi-Fi-to-5G handoffs.":`QUIC, UDP पोर्ट 443 पर ट्रांसपोर्ट को नए सिरे से गढ़ता है: पहले पैकेट से TLS 1.3 साथ (1-RTT या 0-RTT रेज़्यूम), स्वतंत्र स्ट्रीम जो TCP की हेड-ऑफ़-लाइन ब्लॉकिंग हटाती हैं, और कनेक्शन ID जो Wi-Fi से 5G में बदलने पर भी बने रहते हैं।`,"QUIC requires Initial packets >=1200 bytes to thwart amplification and restricts 0-RTT to idempotent GET requests.":`QUIC एम्प्लिफ़िकेशन रोकने के लिए Initial पैकेट >=1200 बाइट माँगता है और 0-RTT को idempotent GET अनुरोधों तक सीमित रखता है।`,"QUIC runs over UDP so middleboxes don’t break new transport extensions and to eliminate TCP HoL blocking.":`QUIC, UDP पर चलता है ताकि बीच के उपकरण नए ट्रांसपोर्ट एक्सटेंशन न तोड़ें और TCP की HoL ब्लॉकिंग ख़त्म हो।`,"QUIT command inside body":`बॉडी के भीतर QUIT कमांड`,"QUIT commits DELE flags and closes mailbox cleanly.":`QUIT, DELE निशानों को पक्का करता है और मेलबॉक्स को साफ़-सुथरे ढंग से बंद करता है।`,"Query with DO=1":`DO=1 के साथ क्वेरी`,"RADIUS Access-Request & Challenge":`RADIUS Access-Request और चैलेंज`,"RADIUS Server":`RADIUS सर्वर`,"RADIUS approves VLAN + MSK key":`RADIUS VLAN + MSK कुंजी मंज़ूर करता है`,"RADIUS centralizes Authentication, Authorization, and Accounting (AAA) for enterprise 802.1X Wi-Fi/wired switches and VPNs, bridging client EAPOL messages to an identity directory.":`RADIUS एंटरप्राइज़ 802.1X Wi-Fi/वायर्ड स्विच और VPN के लिए प्रमाणीकरण, प्राधिकरण और लेखा (AAA) को एक जगह जोड़ता है, और क्लाइंट के EAPOL संदेशों को पहचान निर्देशिका से जोड़ता है।`,"RADIUS denies access and AP blocks network port":`RADIUS पहुँच अस्वीकार करता है और AP नेटवर्क पोर्ट रोक देता है`,"RADIUS returns Access-Accept with Master Session Key and assigned VLAN; AP authorizes port.":`RADIUS मास्टर सेशन कुंजी और तय VLAN के साथ Access-Accept लौटाता है; AP पोर्ट को अधिकृत करता है।`,"RADIUS uses UDP 1812 for authentication/authorization and 1813 for accounting.":`RADIUS प्रमाणीकरण/प्राधिकरण के लिए UDP 1812 और लेखा के लिए 1813 इस्तेमाल करता है।`,"RFC 1929 username/password subnegotiation sends credentials in plaintext unless wrapped inside SSH/TLS.":`RFC 1929 की यूज़रनेम/पासवर्ड सबनेगोशिएशन क्रेडेंशियल सादे टेक्स्ट में भेजती है, जब तक उसे SSH/TLS में न लपेटा जाए।`,"RFC 2177 IDLE lets the server push `* N EXISTS` immediately when mail arrives.":"RFC 2177 IDLE मेल आते ही सर्वर को `* N EXISTS` तुरंत पुश करने देता है।","RFC 3927 APIPA assigns a 169.254.0.0/16 address when DHCP times out.":`DHCP का समय समाप्त होने पर RFC 3927 APIPA, 169.254.0.0/16 का पता देता है।`,'RFC 5321 ends the DATA stream with a line containing only ".".':`RFC 5321 DATA स्ट्रीम को सिर्फ़ "." वाली एक पंक्ति से ख़त्म करता है।`,"RFC 8484 specifies `application/dns-message`.":"RFC 8484 `application/dns-message` तय करता है।","RFC 8910 defines DHCP Option 114 for Captive-Portal API discovery.":`RFC 8910 कैप्टिव-पोर्टल API खोज के लिए DHCP विकल्प 114 परिभाषित करता है।`,"RPKI (Resource Public Key Infrastructure)":`RPKI (रिसोर्स पब्लिक की इन्फ़्रास्ट्रक्चर)`,"RPKI ROAs bind IP prefixes to authorized origin ASNs.":`RPKI ROA, IP प्रीफ़िक्स को अधिकृत मूल ASN से बाँधते हैं।`,"RRSIG fails validation -> resolver returns SERVFAIL":`RRSIG जाँच में विफल -> रिज़ॉल्वर SERVFAIL लौटाता है`,"RRSIG holds the cryptographic signature covering an RRset.":`RRSIG एक RRset को ढकने वाला क्रिप्टोग्राफ़िक हस्ताक्षर रखता है।`,"RTMP is the backstage camera cable connecting a streamer’s OBS studio directly to Twitch or YouTube’s broadcast booth.":`RTMP पर्दे के पीछे का कैमरा केबल है जो स्ट्रीमर के OBS स्टूडियो को सीधे Twitch या YouTube के प्रसारण कक्ष से जोड़ता है।`,"RTMP is the persistent TCP-based ingest protocol used by OBS Studio and encoders to push low-latency live audio/video streams to ingest servers (port 1935) before HLS/DASH distribution.":`RTMP स्थायी TCP-आधारित इनजेस्ट प्रोटोकॉल है, जिसे OBS Studio और एन्कोडर HLS/DASH वितरण से पहले कम देरी वाली लाइव ऑडियो/वीडियो स्ट्रीम इनजेस्ट सर्वरों (पोर्ट 1935) तक भेजने में इस्तेमाल करते हैं।`,"RTMP uses TCP port 1935 (or 443 for RTMPS).":`RTMP TCP पोर्ट 1935 (या RTMPS के लिए 443) इस्तेमाल करता है।`,"RTMPS wraps the RTMP session inside TLS.":`RTMPS, RTMP सेशन को TLS में लपेट देता है।`,"RTP Media & BYE":`RTP मीडिया और BYE`,"RTP Video Stream":`RTP वीडियो स्ट्रीम`,'RTSP acts as a "network remote control" on port 554 for IP cameras and media servers (DESCRIBE -> SETUP -> PLAY -> TEARDOWN), while video frames stream over RTP.':`RTSP IP कैमरों और मीडिया सर्वरों के लिए पोर्ट 554 पर "नेटवर्क रिमोट कंट्रोल" का काम करता है (DESCRIBE -> SETUP -> PLAY -> TEARDOWN), जबकि वीडियो फ़्रेम RTP पर स्ट्रीम होते हैं।`,"RTSP is a VCR-style control channel; RTP carries the media frames.":`RTSP वीसीआर-शैली का कंट्रोल चैनल है; RTP मीडिया फ़्रेम ले जाता है।`,"RTSP is the Play/Pause/Rewind remote control for a security camera, while RTP is the live video river flowing onto your screen.":`RTSP सुरक्षा कैमरे का प्ले/पॉज़/रीवाइंड रिमोट है, और RTP वह लाइव वीडियो की नदी है जो आपकी स्क्रीन पर बहती है।`,"RTSP listens on port 554 (and 322 for RTSPS).":`RTSP पोर्ट 554 (और RTSPS के लिए 322) पर सुनता है।`,"RadSec (RFC 6614) wraps RADIUS inside TLS to eliminate MD5 vulnerabilities.":`RadSec (RFC 6614) MD5 की कमज़ोरियाँ मिटाने के लिए RADIUS को TLS के भीतर लपेटता है।`,"RadSec (TCP 2083)":`RadSec (TCP 2083)`,Random:I,"Random nonces guarantee unique Pairwise Transient Keys even when everyone shares one PSK.":`यादृच्छिक नॉन्स यह पक्का करते हैं कि सब एक ही PSK साझा करें तब भी Pairwise Transient Key अनोखी रहे।`,"Read Holding Registers":`Read Holding Registers`,"Read temperature & pressure registers":`तापमान और दबाव के रजिस्टर पढ़ें`,"Real Time Streaming Protocol (CCTV / IP Cameras)":`रियल टाइम स्ट्रीमिंग प्रोटोकॉल (CCTV / IP कैमरे)`,"Real-Time Messaging Protocol (Live Ingest)":`रियल-टाइम मैसेजिंग प्रोटोकॉल (लाइव इनजेस्ट)`,"Real-time voice/gaming prefers dropping a stale frame over stalling new frames for TCP retransmissions.":`रियल-टाइम आवाज़/गेमिंग पुराना फ़्रेम गिराना पसंद करती है, बजाय इसके कि TCP रीट्रांसमिशन के कारण नए फ़्रेम रुकें।`,"Receiver processes arriving datagrams":`रिसीवर आते डेटाग्राम प्रोसेस करता है`,"Receiver reads datagrams from socket buffer; optional app-level sequence checks handle loss.":`रिसीवर सॉकेट बफ़र से डेटाग्राम पढ़ता है; वैकल्पिक ऐप-स्तरीय सीक्वेंस जाँच नुक़सान संभालती है।`,"Receiving 3 duplicate ACKs signals an out-of-order gap and triggers immediate retransmission.":`3 डुप्लिकेट ACK मिलना क्रम से बाहर के अंतर का संकेत देता है और तुरंत रीट्रांसमिशन शुरू करता है।`,"Receiving a FIN":`FIN मिलना`,"Recursive 8.8.8.8":`रिकर्सिव 8.8.8.8`,"Recursive asks the server to return the final answer; iterative may return referrals":`रिकर्सिव सर्वर से अंतिम जवाब माँगती है; इटेरेटिव रेफ़रल लौटा सकती है`,"Recursive lookup: Resolver -> Root -> .com TLD -> Auth":`रिकर्सिव खोज: रिज़ॉल्वर -> रूट -> .com TLD -> ऑथोरिटेटिव`,"Recursive resolver caches the answer for 300s and delivers it to the client.":`रिकर्सिव रिज़ॉल्वर जवाब को 300s के लिए कैश करता है और क्लाइंट तक पहुँचाता है।`,"Recursive uses TCP only":`रिकर्सिव सिर्फ़ TCP इस्तेमाल करती है`,"Redirecting HTTPS causes cert errors; simple MAC-based allowlists can be bypassed by cloning an authenticated guest’s MAC.":`HTTPS को रीडायरेक्ट करने से सर्टिफ़िकेट त्रुटियाँ आती हैं; सिर्फ़ MAC पर आधारित अनुमति-सूचियाँ प्रमाणित अतिथि का MAC क्लोन करके पार की जा सकती हैं।`,Redo:L,"Redo (Ctrl+Y)":`फिर से करें (Ctrl+Y)`,"Regular DNS is shouting the website name out loud to the phonebook operator. DoH puts that question inside an encrypted HTTPS envelope indistinguishable from normal web browsing.":`सामान्य DNS वेबसाइट का नाम फ़ोनबुक ऑपरेटर को ज़ोर से चिल्लाकर बताने जैसा है। DoH वही सवाल एन्क्रिप्टेड HTTPS लिफ़ाफ़े में रखता है जो सामान्य वेब ब्राउज़िंग से अलग नहीं दिखता।`,"Relay agent forwards UDP/67 broadcasts as unicast to 10.0.0.50.":`रिले एजेंट UDP/67 ब्रॉडकास्ट को यूनिकास्ट बनाकर 10.0.0.50 को भेजता है।`,Reliability:R,"Remains constant":`स्थिर रहता है`,"Remote Authentication Dial-In User Service (802.1X)":`रिमोट ऑथेंटिकेशन डायल-इन यूज़र सर्विस (802.1X)`,"Remove firewall rule":`फ़ायरवॉल नियम हटाएँ`,"Remove the blocking firewall rule":`रोकने वाला फ़ायरवॉल नियम हटाएँ`,"Replace plain FTP with SFTP (over SSH port 22) or FTPS (TLS).":`सादे FTP की जगह SFTP (SSH पोर्ट 22 पर) या FTPS (TLS) अपनाएँ।`,"Replaces IPv4 ARP using multicast":`मल्टीकास्ट से IPv4 ARP की जगह लेता है`,"Require Message-Authenticator (RFC 3579) on all packets or run RadSec (RADIUS over TLS, port 2083).":`सभी पैकेट पर Message-Authenticator (RFC 3579) अनिवार्य करें या RadSec (TLS पर RADIUS, पोर्ट 2083) चलाएँ।`,"Require Proxy-Authorization and restrict CONNECT destination ports to 443.":`Proxy-Authorization अनिवार्य करें और CONNECT के गंतव्य पोर्ट केवल 443 तक सीमित रखें।`,"Requiring SMB Signing":`SMB साइनिंग अनिवार्य करना`,"Reset (R)":`रीसेट (R)`,"Reset Zoom":`ज़ूम रीसेट करें`,"Reset Zoom (100%)":`ज़ूम रीसेट (100%)`,"Resolve example.com -> 203.0.113.10":`example.com -> 203.0.113.10 हल करें`,"Resolver 8.8.8.8 caches A 203.0.113.10 for TTL=300s.":`रिज़ॉल्वर 8.8.8.8, A 203.0.113.10 को TTL=300s के लिए कैश करता है।`,"Resolver Cache Hit":`रिज़ॉल्वर कैश हिट`,"Resolver caches & replies to Client":`रिज़ॉल्वर कैश करता है और क्लाइंट को जवाब देता है`,"Resolver requests DNSSEC signatures":`रिज़ॉल्वर DNSSEC हस्ताक्षर माँगता है`,"Resolver verifies signature against DS hash in parent zone and sets AD=1 (Authenticated Data).":`रिज़ॉल्वर पैरेंट ज़ोन में DS हैश से हस्ताक्षर मिलाता है और AD=1 (Authenticated Data) सेट करता है।`,"Restart PLC":`PLC रीस्टार्ट करना`,"Restarting TCP":`TCP को फिर से शुरू करके`,"Reverse Proxy & 3-Backend Load Balancer":`रिवर्स प्रॉक्सी और 3-बैकएंड लोड बैलेंसर`,"Reverse Proxy & Load Balancer (TLS Termination)":`रिवर्स प्रॉक्सी और लोड बैलेंसर (TLS टर्मिनेशन)`,"Reverse Proxy / LB":`रिवर्स प्रॉक्सी / LB`,"Reverse only works with UDP":`रिवर्स सिर्फ़ UDP के साथ चलता है`,"Reverse proxy injects X-Forwarded-For and balances across healthy backends.":`रिवर्स प्रॉक्सी X-Forwarded-For जोड़ता है और स्वस्थ बैकएंड में लोड बाँटता है।`,"Reverse proxy runs periodic health probes to track healthy pool members.":`रिवर्स प्रॉक्सी स्वस्थ पूल सदस्यों का पता रखने के लिए समय-समय पर जाँच करता है।`,"Reverse proxy terminates TLS and routes around downed backends":`रिवर्स प्रॉक्सी TLS समाप्त करता है और बंद बैकएंड को बचाकर रूट करता है`,"Rogue DHCP Server":`नकली DHCP सर्वर`,"Rogue Router Advertisement (RA Spoofing)":`नकली राउटर विज्ञापन (RA स्पूफ़िंग)`,"Root (.)":`रूट (.)`,"Root DNS":`रूट DNS`,"Root Referral":`रूट रेफ़रल`,"Root nameserver (a.root-servers.net) responds with NS delegation for the .com top-level domain.":`रूट नेमसर्वर (a.root-servers.net) .com टॉप-लेवल डोमेन के लिए NS डेलिगेशन के साथ जवाब देता है।`,"Root nameservers answer referrals for top-level domains like .com, .org, and .net.":`रूट नेमसर्वर .com, .org और .net जैसे टॉप-लेवल डोमेन के लिए रेफ़रल के जवाब देते हैं।`,"Root server (.)":`रूट सर्वर (.)`,"Root server refers to .com TLD":`रूट सर्वर .com TLD की ओर भेजता है`,"Root, TLD, Stub":`रूट, TLD, स्टब`,"Round-Trip Time — elapsed time for a packet to travel to its destination and for the acknowledgment to return.":`राउंड-ट्रिप टाइम — पैकेट के गंतव्य तक पहुँचने और उसकी पावती लौटने में लगा समय।`,"Route from VLAN 10 to VLAN 20 via Router":`राउटर के ज़रिए VLAN 10 से VLAN 20 तक रूट करें`,Router:z,"Router 1 decrements TTL to 0 -> Time Exceeded":`राउटर 1 TTL घटाकर 0 करता है -> Time Exceeded`,"Router LPM & TTL-1":`राउटर LPM और TTL-1`,"Router Query":`राउटर क्वेरी`,"Router Solicitation / Advertisement":`राउटर सॉलिसिटेशन / एडवर्टाइज़मेंट`,"Router decrements TTL (64 -> 63), updates header checksum, and forwards to next hop.":`राउटर TTL घटाता है (64 -> 63), हेडर चेकसम अपडेट करता है और अगले हॉप को भेजता है।`,"Router drops packet and sends ICMP Time Exceeded":`राउटर पैकेट गिराता है और ICMP Time Exceeded भेजता है`,"Router forwards between 192.168.1.0/24 and 192.168.2.0/24 via connected routes.":`राउटर जुड़े हुए रूटों से 192.168.1.0/24 और 192.168.2.0/24 के बीच ट्रैफ़िक भेजता है।`,"Router hop limit":`राउटर की हॉप सीमा`,"Router interface 192.168.2.1 serves 192.168.2.0/24. Which subnet is Host B really in?":`राउटर इंटरफ़ेस 192.168.2.1, 192.168.2.0/24 को सेवा देता है। होस्ट B असल में किस सबनेट में है?`,"Router polls 224.0.0.1 for active listeners":`राउटर सक्रिय श्रोताओं के लिए 224.0.0.1 को पोल करता है`,"Router renews it":`राउटर उसे नवीनीकृत कर देता है`,"Router sends PADR; BRAS assigns Session ID in PADS.":`राउटर PADR भेजता है; BRAS PADS में सेशन ID देता है।`,"Router waits for group-specific query timeout before pruning":`छाँटने से पहले राउटर समूह-विशेष क्वेरी के टाइमआउट का इंतज़ार करता है`,"Routers decrement TTL to prevent infinite loops and update the IPv4 header checksum.":`राउटर अंतहीन लूप रोकने के लिए TTL घटाते हैं और IPv4 हेडर चेकसम अपडेट करते हैं।`,"Routers drop broadcasts by default unless DHCP Relay (ip helper-address) converts them to unicast":`जब तक DHCP Relay (ip helper-address) उन्हें यूनिकास्ट न बना दे, राउटर ब्रॉडकास्ट डिफ़ॉल्ट रूप से गिरा देते हैं`,"Routers emit ICMP Type 11 Code 0 (TTL exceeded in transit) whenever TTL reaches zero.":`जब भी TTL शून्य होता है, राउटर ICMP टाइप 11 कोड 0 (रास्ते में TTL समाप्त) भेजते हैं।`,"Routers only deliver to the subnet an interface belongs to. A host with an address from the wrong subnet is unreachable even though everything is plugged in and powered on.":`राउटर केवल उसी सबनेट तक पहुँचाते हैं जिसका इंटरफ़ेस हिस्सा है। ग़लत सबनेट के पते वाला होस्ट पहुँच से बाहर रहता है, भले सब कुछ जुड़ा और चालू हो।`,Routing:B,"Routing Loop & TTL Expiry":`रूटिंग लूप और TTL समाप्ति`,"Routing Protocol":`रूटिंग प्रोटोकॉल`,'Run "show running-config" on the web server and look for an access-list line.':`वेब सर्वर पर "show running-config" चलाएँ और access-list वाली पंक्ति खोजें।`,"Run `curl http://example.com -v`":"`curl http://example.com -v` चलाएँ","Run `dig bank.example.com` and verify AD=1 DNSSEC protection":"`dig bank.example.com` चलाएँ और AD=1 से DNSSEC सुरक्षा की जाँच करें","Run `dig example.com` twice on Client to observe cache miss then cache hit":"क्लाइंट पर `dig example.com` दो बार चलाएँ ताकि कैश मिस और फिर कैश हिट दिखे","Run `dig recipient.org MX` on Sender":"भेजने वाले पर `dig recipient.org MX` चलाएँ","Run `nmap 10.0.1.50` vs `nmap 172.16.0.10` from Internet Client":"इंटरनेट क्लाइंट से `nmap 10.0.1.50` बनाम `nmap 172.16.0.10` चलाएँ","Run `ping -t 4 10.99.99.1` to see ICMP TTL Exceeded":"ICMP TTL Exceeded देखने के लिए `ping -t 4 10.99.99.1` चलाएँ","Run `ping 203.0.113.10 -s 1400` on Host":"होस्ट पर `ping 203.0.113.10 -s 1400` चलाएँ","Run `show ip route` on AS64500":"AS64500 पर `show ip route` चलाएँ","Run `show ip route` on Router":"राउटर पर `show ip route` चलाएँ","Run an iPerf transfer across a lossy 10% link and watch Slow Start + Reno/CUBIC cwnd sawtooth.":`10% लॉस वाले लिंक पर iPerf ट्रांसफ़र चलाएँ और स्लो स्टार्ट तथा Reno/CUBIC cwnd की आरी देखें।`,"Run iPerf Traffic Generator":`iPerf ट्रैफ़िक जनरेटर चलाएँ`,"Runs directly over IPv4 (Proto 17) / IPv6":`सीधे IPv4 (प्रोटो 17) / IPv6 के ऊपर चलता है`,"Runs directly over IPv4 (Proto 6) / IPv6":`सीधे IPv4 (प्रोटो 6) / IPv6 के ऊपर चलता है`,"SAE (Dragonfly)":`SAE (Dragonfly)`,"SAE Commit (Dragonfly)":`SAE कमिट (Dragonfly)`,"SAE Commit/Confirm + Protected Management Frames (PMF)":`SAE कमिट/कन्फ़र्म + सुरक्षित मैनेजमेंट फ़्रेम (PMF)`,"SAE Confirm":`SAE कन्फ़र्म`,"SAE Confirm token mismatch rejects client":`SAE Confirm टोकन बेमेल होने पर क्लाइंट ठुकराया जाता है`,"SCADA HMI connects to PLC":`SCADA HMI, PLC से जुड़ता है`,"SDP Offer / ICE Candidates":`SDP ऑफ़र / ICE कैंडिडेट`,"SDP Offer/Answer + STUN Binding + SRTP Encrypted Media":`SDP ऑफ़र/आंसर + STUN बाइंडिंग + SRTP एन्क्रिप्टेड मीडिया`,"SELECT & FETCH Headers":`SELECT और हेडर FETCH`,"SERVFAIL / timeout when authoritative server is down":`ऑथोरिटेटिव सर्वर बंद होने पर SERVFAIL / टाइमआउट`,"SFTP runs as a subsystem over an encrypted SSH channel on port 22.":`SFTP पोर्ट 22 पर एन्क्रिप्टेड SSH चैनल के ऊपर उप-प्रणाली के रूप में चलता है।`,"SFTP runs over a single encrypted SSH connection on port 22.":`SFTP पोर्ट 22 पर एक ही एन्क्रिप्टेड SSH कनेक्शन पर चलता है।`,"SIP Toll Fraud & Eavesdropping":`SIP टोल फ़्रॉड और जासूसी`,"SIP is signaling only; RTP (Real-time Transport Protocol) carries audio/video.":`SIP सिर्फ़ सिग्नलिंग है; RTP (Real-time Transport Protocol) ऑडियो/वीडियो ले जाता है।`,'SIP is the telephone operator that rings the other phone ("INVITE", "Ringing!", "Picked up!"), and once connected, both people talk directly over RTP.':`SIP वह टेलीफ़ोन ऑपरेटर है जो दूसरे फ़ोन की घंटी बजाता है ("INVITE", "घंटी बज रही है!", "फ़ोन उठा लिया!"), और जुड़ने के बाद दोनों लोग सीधे RTP पर बात करते हैं।`,"SIP sets up, modifies, and tears down voice and video VoIP calls (INVITE / 180 Ringing / 200 OK / ACK) while actual voice packets travel separately over RTP.":`SIP आवाज़ और वीडियो VoIP कॉल शुरू, बदलता और ख़त्म करता है (INVITE / 180 Ringing / 200 OK / ACK), जबकि असली आवाज़ के पैकेट RTP पर अलग से जाते हैं।`,"SIP uses 5060 (UDP/TCP) and SIPS uses 5061 (TLS).":`SIP 5060 (UDP/TCP) और SIPS 5061 (TLS) इस्तेमाल करता है।`,"SIP uses BYE to tear down an established dialog.":`SIP स्थापित डायलॉग को ख़त्म करने के लिए BYE इस्तेमाल करता है।`,"SLAAC prefix discovery (ICMPv6 133/134)":`SLAAC प्रीफ़िक्स खोज (ICMPv6 133/134)`,"SMB (port 445) powers Windows and NAS network file shares, printers, and named pipes. SMBv3 adds AES-128-GCM encryption, multichannel throughput, and signing to block relay attacks.":`SMB (पोर्ट 445) Windows और NAS के नेटवर्क फ़ाइल शेयर, प्रिंटर और नेम्ड पाइप चलाता है। SMBv3 रिले हमलों को रोकने के लिए AES-128-GCM एन्क्रिप्शन, मल्टीचैनल थ्रूपुट और साइनिंग जोड़ता है।`,"SMB Relay & WannaCry (SMBv1 EternalBlue)":`SMB रिले और WannaCry (SMBv1 EternalBlue)`,"SMB Signing cryptographically signs every SMB packet so relayed tokens fail.":`SMB साइनिंग हर SMB पैकेट पर क्रिप्टोग्राफ़िक हस्ताक्षर करती है, इसलिए रिले किए टोकन विफल हो जाते हैं।`,"SMB makes a folder on a remote server look like a normal hard drive letter (Z:) on your own computer.":`SMB दूर के सर्वर के फ़ोल्डर को आपके अपने कंप्यूटर पर सामान्य हार्ड ड्राइव अक्षर (Z:) जैसा दिखा देता है।`,"SMBv1 is deprecated and insecure; SMBv3 provides modern security and performance.":`SMBv1 पुराना और असुरक्षित है; SMBv3 आधुनिक सुरक्षा और प्रदर्शन देता है।`,"SMTP is the postal truck that drops letters at the recipient’s post office (found by checking the MX address book). You announce who it’s from, who it’s for, and hand over the letter.":`SMTP वह डाक ट्रक है जो चिट्ठी प्राप्तकर्ता के डाकघर (MX पता-पुस्तिका देखकर मिला) पर छोड़ता है। आप बताते हैं किसकी ओर से है, किसके लिए है, और चिट्ठी सौंप देते हैं।`,"SMTP pushes outbound email from mail clients to submission servers (port 587) and between domain Mail Transfer Agents (port 25) after resolving DNS MX records.":`SMTP भेजी जाने वाली ईमेल को मेल क्लाइंट से सबमिशन सर्वर (पोर्ट 587) तक और DNS MX रिकॉर्ड हल करने के बाद डोमेन के मेल ट्रांसफ़र एजेंटों (पोर्ट 25) के बीच पहुँचाता है।`,"SMTP pushes outbound mail; IMAP syncs inbound mailboxes":`SMTP बाहर जाती मेल पहुँचाता है; IMAP आने वाले मेलबॉक्स सिंक करता है`,"SNI (Server Name Indication)":`SNI (Server Name Indication)`,"SNI sends the target hostname in ClientHello so the server picks the right certificate.":`SNI, ClientHello में लक्ष्य होस्टनेम भेजता है ताकि सर्वर सही सर्टिफ़िकेट चुन सके।`,"SOCKS Protocol Version 5":`SOCKS प्रोटोकॉल संस्करण 5`,"SOCKS5 added UDP relay, IPv6 addressing, domain name resolution, and authentication.":`SOCKS5 ने UDP रिले, IPv6 एड्रेसिंग, डोमेन नाम रेज़ोल्यूशन और प्रमाणीकरण जोड़ा।`,"SOCKS5 is a protocol-agnostic session proxy (port 1080) capable of relaying any TCP or UDP traffic (used by SSH dynamic port forwarding and Tor) without understanding HTTP.":`SOCKS5 प्रोटोकॉल-निरपेक्ष सेशन प्रॉक्सी (पोर्ट 1080) है जो HTTP समझे बिना कोई भी TCP या UDP ट्रैफ़िक आगे पहुँचा सकता है (SSH का डायनामिक पोर्ट फ़ॉरवर्डिंग और Tor इसे इस्तेमाल करते हैं)।`,"SOCKS5 is a universal courier pipe: you tell it the final IP and port, and it passes any kind of TCP or UDP packets through without caring what app created them.":`SOCKS5 एक सार्वभौमिक कूरियर पाइप है: आप अंतिम IP और पोर्ट बताते हैं, और वह किसी भी तरह के TCP या UDP पैकेट पास कर देता है, चाहे उन्हें किसी भी ऐप ने बनाया हो।`,"SOCKS5 rejects credentials during subnegotiation":`SOCKS5 सबनेगोशिएशन के दौरान क्रेडेंशियल ठुकराता है`,"SPF authorizes sender IPs, DKIM cryptographically signs headers/body, and DMARC sets enforcement policy.":`SPF भेजने वाले IP को अधिकृत करता है, DKIM हेडर/बॉडी पर क्रिप्टोग्राफ़िक हस्ताक्षर करता है, और DMARC लागू करने की नीति तय करता है।`,"SRTP (keyed via DTLS)":`SRTP (कुंजी DTLS से)`,"SSH establishes an encrypted, mutually authenticated channel over untrusted networks for remote shell access, SFTP file transfer, and port tunneling.":`SSH अविश्वसनीय नेटवर्कों पर रिमोट शेल, SFTP फ़ाइल ट्रांसफ़र और पोर्ट टनलिंग के लिए एन्क्रिप्टेड, आपसी प्रमाणित चैनल बनाता है।`,"SSH is like opening an armored, soundproof tunnel to a distant server where you prove who you are with an unforgeable cryptographic key instead of shouting passwords across the street.":`SSH दूर के सर्वर तक बख़्तरबंद, ध्वनिरोधी सुरंग खोलने जैसा है, जहाँ आप गली में पासवर्ड चिल्लाने के बजाय नक़ली न बन सकने वाली क्रिप्टोग्राफ़िक कुंजी से अपनी पहचान साबित करते हैं।`,"SSH uses TCP port 22 (replacing insecure Telnet on port 23).":`SSH TCP पोर्ट 22 इस्तेमाल करता है (पोर्ट 23 के असुरक्षित Telnet की जगह)।`,"SSH-2.0 banner exchange on port 22":`पोर्ट 22 पर SSH-2.0 बैनर आदान-प्रदान`,"SSL Stripping":`SSL स्ट्रिपिंग`,"STA and AP exchange Dragonfly Commit messages derived from password + elliptic curve.":`STA और AP पासवर्ड और एलिप्टिक कर्व से निकले Dragonfly Commit संदेश बदलते हैं।`,"STA computes PTK, returns SNonce plus a Message Integrity Code proving it knows the password.":`STA PTK निकालता है और SNonce के साथ संदेश अखंडता कोड लौटाता है, जो साबित करता है कि उसे पासवर्ड पता है।`,"STA replies with SNonce & MIC":`STA, SNonce और MIC के साथ जवाब देता है`,"STARTTLS Upgrade":`STARTTLS अपग्रेड`,"STARTTLS negotiates TLS encryption over the existing socket before AUTH or DATA.":`STARTTLS, AUTH या DATA से पहले मौजूदा सॉकेट पर TLS एन्क्रिप्शन तय करता है।`,"STARTTLS upgrades the plaintext TCP socket to encrypted TLS before transferring email content.":`ईमेल की सामग्री भेजने से पहले STARTTLS सादे टेक्स्ट वाले TCP सॉकेट को एन्क्रिप्टेड TLS में बदल देता है।`,"STAT shows mailbox count; RETR 1 downloads full RFC 5322 email.":`STAT मेलबॉक्स की गिनती दिखाता है; RETR 1 पूरा RFC 5322 ईमेल डाउनलोड करता है।`,"STUN / Signaling":`STUN / सिग्नलिंग`,"STUN Public IP Discovery":`STUN से सार्वजनिक IP की खोज`,"STUN returns the XOR-MAPPED-ADDRESS seen from outside the NAT.":`STUN वह XOR-MAPPED-ADDRESS लौटाता है जो NAT के बाहर से दिखता है।`,"SYN -> SYN-ACK -> ACK (Seq/Ack sync)":`SYN -> SYN-ACK -> ACK (Seq/Ack तालमेल)`,"SYN / SYN-ACK / ACK on port 443":`पोर्ट 443 पर SYN / SYN-ACK / ACK`,"SYN Cookies":`SYN Cookies`,"SYN Cookies let legitimate 3-way handshakes complete even under heavy SYN flood.":`भारी SYN फ़्लड में भी SYN Cookies वैध 3-वे हैंडशेक पूरे होने देती हैं।`,"SYN Flood & SYN Cookies Defense":`SYN फ़्लड और SYN Cookies से बचाव`,"SYN Flood DoS":`SYN फ़्लड DoS`,"SYN and ACK":`SYN और ACK`,"SYN cookies avoid storing half-open state until the client returns the third handshake ACK.":`SYN cookies तब तक आधी-खुली स्थिति नहीं रखतीं जब तक क्लाइंट हैंडशेक का तीसरा ACK नहीं लौटाता।`,"SYN only":`सिर्फ़ SYN`,"Save topology snapshot name...":`टोपोलॉजी स्नैपशॉट का नाम...`,"Saved snapshots:":`सहेजे गए स्नैपशॉट:`,"Scalar + Elliptic Curve Element exchange":`स्केलर + एलिप्टिक कर्व तत्व का आदान-प्रदान`,"Second TCP socket transfers file bytes":`दूसरा TCP सॉकेट फ़ाइल के बाइट ले जाता है`,"Seconds (0.024s)":`सेकंड (0.024s)`,"Secure Shell Protocol (SSH-2)":`सिक्योर शेल प्रोटोकॉल (SSH-2)`,Security:V,"See rogue MAC conflict detected":`नकली MAC का टकराव पकड़ा जाते देखें`,"Segment OT networks behind strict industrial firewalls (Purdue Model) and use Modbus TCP Security (TLS).":`OT नेटवर्क को सख़्त औद्योगिक फ़ायरवॉल (Purdue मॉडल) के पीछे बाँटें और Modbus TCP Security (TLS) इस्तेमाल करें।`,"Segment SCADA HMI and Modbus TCP PLC (port 502) behind an OT firewall.":`OT फ़ायरवॉल के पीछे SCADA HMI और Modbus TCP PLC (पोर्ट 502) को अलग-अलग खंड में रखें।`,"Segment loss triggers Reno/CUBIC backoff":`सेगमेंट खोने पर Reno/CUBIC बैकऑफ़ शुरू होता है`,"Select a device on the canvas to inspect its ARP cache, MAC table, Routing table, and NAT translations.":`ARP कैश, MAC तालिका, रूटिंग तालिका और NAT ट्रांसलेशन देखने के लिए कैनवस पर कोई डिवाइस चुनें।`,"Select a device on the canvas to inspect its forwarding tables.":`फ़ॉरवर्डिंग तालिकाएँ देखने के लिए कैनवस पर कोई डिवाइस चुनें।`,"Select a device or cable on the canvas to configure front-panel ports, IP addresses, routing, firewall ACLs, or link loss/MTU.":`पोर्ट, IP पते, रूटिंग, फ़ायरवॉल नियम या लिंक लॉस/MTU सेट करने के लिए कैनवस पर कोई डिवाइस या केबल चुनें।`,"Select any captured frame or click a live packet on the topology canvas to decode its OSI headers and raw hex bytes.":`कोई भी कैप्चर किया हुआ फ़्रेम चुनें या टोपोलॉजी कैनवस पर चलते पैकेट पर क्लिक करें, ताकि उसके OSI हेडर और रॉ हेक्स बाइट देख सकें।`,"Select comparison pair":`तुलना की जोड़ी चुनें`,"Select preset lab":`तैयार लैब चुनें`,"Send HTTP GET and HTTPS GET from Client":`क्लाइंट से HTTP GET और HTTPS GET भेजें`,"Send Packets":`पैकेट भेजें`,"Sender queries DNS for the MX record of recipient.org -> mail.recipient.org (198.51.100.25).":`भेजने वाला DNS से recipient.org का MX रिकॉर्ड पूछता है -> mail.recipient.org (198.51.100.25)।`,"Sender resolves MX record, delivers via SMTP, and recipient picks up mail via IMAP.":`भेजने वाला MX रिकॉर्ड हल करता है, SMTP से पहुँचाता है, और प्राप्तकर्ता IMAP से मेल उठाता है।`,"Sender transmits envelope addresses, email headers/MIME body, ending with <CRLF>.<CRLF> -> 250 OK.":`भेजने वाला लिफ़ाफ़े के पते, ईमेल हेडर और MIME बॉडी भेजता है, और <CRLF>.<CRLF> -> 250 OK पर ख़त्म करता है।`,"Senders can forge the 32-bit Source IP header field unless edge networks filter egress traffic.":`जब तक एज नेटवर्क बाहर जाते ट्रैफ़िक को फ़िल्टर न करें, भेजने वाले 32-बिट सोर्स IP फ़ील्ड को जाली बना सकते हैं।`,"Sending ARP requests":`ARP अनुरोध भेजकर`,"Sending ICMP Echo Requests to a subnet broadcast address with a spoofed source IP floods the victim.":`जाली सोर्स IP के साथ सबनेट ब्रॉडकास्ट पते पर ICMP Echo Request भेजना पीड़ित पर बाढ़ ला देता है।`,"Sends ICMP Unreachable":`ICMP Unreachable भेजता है`,"Sends TCP RST":`TCP RST भेजता है`,"Separate Engineering (VLAN 10) and Finance (VLAN 20) on one switch with Router-on-a-Stick.":`Router-on-a-Stick से एक स्विच पर इंजीनियरिंग (VLAN 10) और वित्त (VLAN 20) को अलग करें।`,Serial:H,Server:U,"Server Down":`सर्वर बंद`,"Server Initial + Handshake":`सर्वर Initial + Handshake`,"Server Message Block (SMBv3 File Sharing)":`सर्वर मैसेज ब्लॉक (SMBv3 फ़ाइल शेयरिंग)`,"Server Timestamps (T2, T3)":`सर्वर टाइमस्टैम्प (T2, T3)`,"Server commits lease (86400s)":`सर्वर लीज़ पक्की करता है (86400s)`,"Server computes Sec-WebSocket-Accept":`सर्वर Sec-WebSocket-Accept निकालता है`,"Server derives handshake keys immediately, sends its X25519 share, encrypted certificate chain, and Finished.":`सर्वर तुरंत हैंडशेक कुंजियाँ निकालता है और अपना X25519 शेयर, एन्क्रिप्टेड सर्टिफ़िकेट चेन और Finished भेजता है।`,"Server hashes key + GUID, responds HTTP/1.1 101 Switching Protocols, switching socket framing.":`सर्वर कुंजी + GUID का हैश बनाता है, HTTP/1.1 101 Switching Protocols से जवाब देता है और सॉकेट फ़्रेमिंग बदल देता है।`,"Server offers 192.168.1.50":`सर्वर 192.168.1.50 की पेशकश करता है`,"Server opens ephemeral data port (e.g. 50120)":`सर्वर अस्थायी डेटा पोर्ट खोलता है (जैसे 50120)`,"Server pushes * EXISTS on new mail":`नई मेल आने पर सर्वर * EXISTS भेजता है`,"Server pushes frames without client polling":`क्लाइंट की पोलिंग के बिना सर्वर फ़्रेम भेजता है`,"Server rejects FTP credentials on control channel":`सर्वर कंट्रोल चैनल पर FTP क्रेडेंशियल ठुकराता है`,"Server rejects IMAP login credentials":`सर्वर IMAP लॉगिन क्रेडेंशियल ठुकराता है`,"Server rejects SYN with immediate TCP RST":`सर्वर तुरंत TCP RST से SYN ठुकरा देता है`,"Server rejects invalid Origin header with HTTP 403":`सर्वर अमान्य Origin हेडर को HTTP 403 से ठुकरा देता है`,"Server rejects invalid SMB session credentials":`सर्वर अमान्य SMB सेशन क्रेडेंशियल ठुकराता है`,"Server rejects wrong key/password with USERAUTH_FAILURE":`सर्वर ग़लत कुंजी/पासवर्ड को USERAUTH_FAILURE से ठुकराता है`,"Server replies with Initial + Handshake packets; connection is ready in 1 RTT total!":`सर्वर Initial + Handshake पैकेट से जवाब देता है; कनेक्शन कुल 1 RTT में तैयार है!`,"Server responds with TCP RST instead of SYN-ACK":`सर्वर SYN-ACK की जगह TCP RST भेजता है`,"Server sends DHCPACK finalizing the 24-hour lease; client runs gratuitous ARP and configures eth0.":`सर्वर DHCPACK भेजकर 24 घंटे की लीज़ पक्की करता है; क्लाइंट ग्रैच्युटस ARP चलाता है और eth0 कॉन्फ़िगर करता है।`,"Server streams multicast UDP to 239.1.1.5; host later sends Leave to prune traffic.":`सर्वर 239.1.1.5 को मल्टीकास्ट UDP स्ट्रीम करता है; होस्ट बाद में ट्रैफ़िक छाँटने के लिए Leave भेजता है।`,"ServerHello + Certificate":`ServerHello + सर्टिफ़िकेट`,"ServerHello + Encrypted Cert in same flight":`उसी उड़ान में ServerHello + एन्क्रिप्टेड सर्टिफ़िकेट`,"Servers listen on UDP port 67 and clients listen on UDP port 68.":`सर्वर UDP पोर्ट 67 पर और क्लाइंट UDP पोर्ट 68 पर सुनते हैं।`,"Service Server":`सेवा सर्वर`,Session:W,"Session Confirmed (PADR / PADS)":`सेशन की पुष्टि (PADR / PADS)`,"Session Initiation Protocol (VoIP Signaling)":`सेशन इनिशिएशन प्रोटोकॉल (VoIP सिग्नलिंग)`,"Session Setup & Tree Connect":`सेशन सेटअप और ट्री कनेक्ट`,"Session establishment and synchronization: SIP, WebRTC ICE/SDP, SOCKS5, RADIUS.":`सेशन बनाना और तालमेल: SIP, WebRTC ICE/SDP, SOCKS5, RADIUS.`,"Set DF=0 to allow IPv4 fragmentation or lower MTU / MSS clamping":`IPv4 फ़्रैगमेंटेशन की अनुमति के लिए DF=0 रखें या MTU घटाएँ / MSS क्लैंपिंग करें`,Share:G,"Shortest AS_PATH":`सबसे छोटा AS_PATH`,"Shortest subnet mask":`सबसे छोटा सबनेट मास्क`,"Show Hints & Solution":`संकेत और हल दिखाएँ`,"Show that UDP does not automatically retransmit lost packets":`दिखाएँ कि UDP खोए पैकेट अपने-आप दोबारा नहीं भेजता`,"Sign Route Origin Authorizations (ROAs) with RPKI and enforce IRR/MANRS route filtering.":`RPKI से Route Origin Authorization (ROA) पर हस्ताक्षर करें और IRR/MANRS रूट फ़िल्टरिंग लागू करें।`,"Signed Answer + DNSKEY/DS":`हस्ताक्षरित जवाब + DNSKEY/DS`,"Signed Auth NS":`हस्ताक्षरित ऑथोरिटेटिव NS`,"Silent drop makes WireGuard invisible to unauthenticated port scanners.":`चुपचाप गिराने से WireGuard अप्रमाणित पोर्ट स्कैनर को दिखता ही नहीं।`,"Simple Mail Transfer Protocol":`सिंपल मेल ट्रांसफ़र प्रोटोकॉल`,"Simulate firewall dropping ICMP echo reply":`फ़ायरवॉल द्वारा ICMP इको रिप्लाई गिराने का अनुकरण करें`,"Simulated Frames":`सिम्युलेट किए गए फ़्रेम`,"Simulated loss or congestion reduces ssthresh and triggers fast retransmit / RTO recovery.":`नकली लॉस या कंजेशन ssthresh घटा देता है और फ़ास्ट रीट्रांसमिट / RTO रिकवरी शुरू करता है।`,"Simulation playback mode":`सिम्युलेशन प्लेबैक मोड`,"Simulation speed":`सिम्युलेशन की गति`,"Simulator Capture Filter":`सिम्युलेटर कैप्चर फ़िल्टर`,"Simulator Dashboards and Packet Capture":`सिम्युलेटर डैशबोर्ड और पैकेट कैप्चर`,"Simulator Docked Console Deck":`सिम्युलेटर का कंसोल पैनल`,"Simultaneous Authentication of Equals (SAE / Dragonfly) resists offline brute force.":`Simultaneous Authentication of Equals (SAE / Dragonfly) ऑफ़लाइन ब्रूट-फ़ोर्स का सामना करता है।`,"Simultaneous Authentication of Equals — WPA3 zero-knowledge password handshake immune to offline dictionary capture.":`साइमल्टेनियस ऑथेंटिकेशन ऑफ़ ईक्वल्स — WPA3 का ज़ीरो-नॉलेज पासवर्ड हैंडशेक, जो ऑफ़लाइन डिक्शनरी हमले के लिए कैप्चर से सुरक्षित है।`,"Single Initial packet carries TLS ClientHello":`एक ही Initial पैकेट TLS ClientHello ले जाता है`,"Single Step Next Event":`एक घटना आगे बढ़ें`,"Site-to-Site WireGuard VPN Tunnel":`साइट-टू-साइट WireGuard VPN टनल`,"Site-to-site VPN bridges private RFC 1918 subnets securely across public internet.":`साइट-टू-साइट VPN सार्वजनिक इंटरनेट के पार निजी RFC 1918 सबनेट को सुरक्षित रूप से जोड़ता है।`,"Skip DNS query and connect directly to port 443":`DNS क्वेरी छोड़कर सीधे पोर्ट 443 से जुड़ें`,"Skip root/TLD/authoritative DNS traversal":`रूट/TLD/ऑथोरिटेटिव DNS का पूरा सफ़र छोड़ दें`,"Slow Start":`स्लो स्टार्ट`,"Small MTU (576 B)":`छोटा MTU (576 B)`,"Smallest MTU":`सबसे छोटा MTU`,"Smurf Amplification & Ping Flood":`स्मर्फ़ एम्प्लिफ़िकेशन और पिंग फ़्लड`,"So every device and session uses unique encryption keys":`ताकि हर डिवाइस और हर सेशन की एन्क्रिप्शन कुंजियाँ अनोखी हों`,Solution:K,Source:q,"Source IP changes to router IP":`सोर्स IP बदलकर राउटर का IP हो जाता है`,"Spanning Tree":`Spanning Tree`,"Split 1400B packet into IPv4 fragments (MF=1, Offset)":`1400B पैकेट को IPv4 टुकड़ों में बाँटें (MF=1, Offset)`,"Spoofing a victim’s source IP in small ANY/TXT queries triggers huge responses directed at the victim.":`छोटी ANY/TXT क्वेरी में पीड़ित का सोर्स IP जाली बनाकर डालने से बहुत बड़े जवाब पीड़ित की ओर जाते हैं।`,Stack:J,"Standard Ethernet II supports a 1500-byte payload MTU.":`मानक ईथरनेट II 1500-बाइट पेलोड MTU देता है।`,"Standard FTP sends usernames, passwords, and file contents unencrypted.":`मानक FTP यूज़रनेम, पासवर्ड और फ़ाइलों की सामग्री बिना एन्क्रिप्शन के भेजता है।`,"Standard NSEC records allow walking every subdomain in a zone.":`मानक NSEC रिकॉर्ड से किसी ज़ोन के हर सबडोमेन तक चलकर पहुँचा जा सकता है।`,"Starts a new email draft":`नया ईमेल ड्राफ़्ट शुरू करता है`,"Stateful FW":`स्टेटफ़ुल फ़ायरवॉल`,"Static / Connected":`स्टैटिक / जुड़ा हुआ`,"Static IP Correlation / Metadata":`स्थिर IP सहसंबंध / मेटाडेटा`,"Static RSA key exchange":`स्थिर RSA कुंजी विनिमय`,"Station discovers SSID via Beacon/Probe and associates with the Access Point.":`स्टेशन Beacon/Probe से SSID खोजता है और एक्सेस पॉइंट से जुड़ता है।`,Stealth:Y,"Step Back One Event":`एक घटना पीछे जाएँ`,"Stratum 0 is an atomic/GPS clock; Stratum 1 servers sync directly to Stratum 0.":`स्ट्रेटम 0 परमाणु/GPS घड़ी है; स्ट्रेटम 1 सर्वर सीधे स्ट्रेटम 0 से तालमेल रखते हैं।`,"Stratum-1 NTP":`स्ट्रेटम-1 NTP`,"Stratum-1 server records arrival T2 and departure T3 in 64-bit NTP fixed-point format.":`स्ट्रेटम-1 सर्वर 64-बिट NTP फ़िक्स्ड-पॉइंट फ़ॉर्मैट में आगमन T2 और प्रस्थान T3 दर्ज करता है।`,"Stream 0 (HTML) & Stream 4 (CSS) without HoL blocking":`स्ट्रीम 0 (HTML) और स्ट्रीम 4 (CSS), बिना HoL ब्लॉकिंग के`,"Stream 0 Loss (No HoL Block)":`स्ट्रीम 0 में लॉस (HoL ब्लॉक नहीं)`,"Stream 0 packet drops while Stream 4 delivers uninterrupted":`स्ट्रीम 0 का पैकेट गिरता है जबकि स्ट्रीम 4 बिना रुकावट पहुँचाती रहती है`,"Stream Key Exposure on Plain RTMP":`सादे RTMP पर स्ट्रीम कुंजी का खुलासा`,"Stream flows until host sends Leave":`स्ट्रीम तब तक चलती है जब तक होस्ट Leave न भेजे`,"Strict-Transport-Security (HSTS)":`Strict-Transport-Security (HSTS)`,"Strictly verify X.509 chain, expiry, SAN hostname, OCSP stapling, and Certificate Transparency.":`X.509 चेन, समाप्ति तिथि, SAN होस्टनेम, OCSP स्टेपलिंग और Certificate Transparency की सख़्ती से जाँच करें।`,"Strip/overwrite X-Forwarded-For at the edge reverse proxy before forwarding upstream.":`अपस्ट्रीम भेजने से पहले एज रिवर्स प्रॉक्सी पर X-Forwarded-For हटाएँ या ओवरराइट करें।`,"Stub Query":`शुरुआती क्वेरी`,"Stub clients send recursive queries (RD=1) to 8.8.8.8, which then sends iterative queries to root/TLD/auth.":`स्टब क्लाइंट 8.8.8.8 को रिकर्सिव क्वेरी (RD=1) भेजते हैं, जो फिर रूट/TLD/ऑथोरिटेटिव को इटेरेटिव क्वेरी भेजता है।`,"Stub resolver":`स्टब रिज़ॉल्वर`,"Stub resolver queries 8.8.8.8, which walks the DNS hierarchy to resolve www.example.com to 203.0.113.10.":`रिज़ॉल्वर 8.8.8.8 से पूछता है, जो DNS पदानुक्रम से गुज़रकर www.example.com को 203.0.113.10 में बदलता है।`,"Submission server rejects invalid SMTP credentials":`सबमिशन सर्वर अमान्य SMTP क्रेडेंशियल ठुकराता है`,"Subnet Mask":`सबनेट मास्क`,"Subsequent Ethernet frames (802.1Q / IPv4) are forwarded only to Port 2, never flooded to Host C.":`आगे के ईथरनेट फ़्रेम (802.1Q / IPv4) केवल पोर्ट 2 को भेजे जाते हैं, होस्ट C तक कभी फ़्लड नहीं होते।`,"Supplicant sends EAP-Identity to Authenticator AP":`सप्लिकेंट, ऑथेंटिकेटर AP को EAP-Identity भेजता है`,"Supplicant, Authenticator (Switch/AP), Authentication Server (RADIUS)":`सप्लिकेंट, ऑथेंटिकेटर (स्विच/AP), ऑथेंटिकेशन सर्वर (RADIUS)`,"Supported ciphers, SNI, X25519 key share":`समर्थित साइफ़र, SNI, X25519 की-शेयर`,"Switch (8 ports)":`स्विच (8 पोर्ट)`,"Switch Flood & Learn":`स्विच फ़्लड और सीखना`,"Switch learns MAC-A on Port 1 & floods":`स्विच पोर्ट 1 पर MAC-A सीखता है और फ़्लड करता है`,"Switch records 02:42:ac:11:00:10 on Port 1 and floods the broadcast frame to Ports 2 and 3.":`स्विच पोर्ट 1 पर 02:42:ac:11:00:10 दर्ज करता है और ब्रॉडकास्ट फ़्रेम को पोर्ट 2 और 3 पर फ़्लड करता है।`,"Switch the router on":`राउटर चालू करें`,"Switched directly Port 1 -> Port 2":`सीधे पोर्ट 1 -> पोर्ट 2 स्विच हुआ`,"Switches inspect the Source MAC field of every arriving frame and bind it to the ingress port.":`स्विच हर आने वाले फ़्रेम का सोर्स MAC फ़ील्ड देखकर उसे आने वाले पोर्ट से जोड़ देते हैं।`,Switching:X,"Symmetric NAT (TURN Relay)":`सिमेट्रिक NAT (TURN रिले)`,"T1 (client send), T2 (server recv), T3 (server send), T4 (client recv) cancel out symmetric RTT.":`T1 (क्लाइंट भेजे), T2 (सर्वर पाए), T3 (सर्वर भेजे), T4 (क्लाइंट पाए) सममित RTT को हटा देते हैं।`,"TCP (+ TLS for WSS)":`TCP (+ WSS के लिए TLS)`,"TCP (Control) + UDP/TCP (RTP Media)":`TCP (कंट्रोल) + UDP/TCP (RTP मीडिया)`,"TCP (Dual Channels)":`TCP (दो चैनल)`,"TCP + Greeting + EHLO":`TCP + अभिवादन + EHLO`,"TCP + TLS 1.2/1.3 (or QUIC for HTTP/3)":`TCP + TLS 1.2/1.3 (या HTTP/3 के लिए QUIC)`,"TCP + Version Exchange":`TCP + संस्करण आदान-प्रदान`,"TCP / UDP Associate":`TCP / UDP असोसिएट`,"TCP 3-Way Handshake & HTTP GET":`TCP 3-वे हैंडशेक और HTTP GET`,"TCP Congestion Control (Sawtooth cwnd)":`TCP कंजेशन कंट्रोल (आरी जैसा cwnd)`,"TCP Congestion Window (cwnd vs ssthresh)":`TCP कंजेशन विंडो (cwnd बनाम ssthresh)`,"TCP Connect to Port 502":`पोर्ट 502 पर TCP कनेक्शन`,"TCP Connection":`TCP कनेक्शन`,"TCP Handshake":`TCP हैंडशेक`,"TCP Port 179 Session":`TCP पोर्ट 179 सेशन`,"TCP RST Injection":`TCP RST इंजेक्शन`,"TCP Reno/CUBIC congestion control, L2 MAC learning, LPM routing, and libpcap export.":`TCP Reno/CUBIC कंजेशन कंट्रोल, L2 MAC लर्निंग, LPM रूटिंग और libpcap एक्सपोर्ट।`,"TCP adapts send rate dynamically to link capacity and packet drops.":`TCP अपनी भेजने की दर को लिंक की क्षमता और पैकेट लॉस के अनुसार बदलता रहता है।`,"TCP control flags governing connection setup, byte acknowledgment, immediate abort, and graceful teardown.":`TCP कंट्रोल फ़्लैग जो कनेक्शन बनाने, बाइट की पावती, तुरंत तोड़ने और शालीनता से बंद करने को नियंत्रित करते हैं।`,"TCP cwnd / ssthresh Sawtooth":`TCP cwnd / ssthresh का आरी जैसा ग्राफ़`,'TCP is like a registered phone call: first both say "Can you hear me? / Yes, can you hear me? / Yes!" then number every sentence and repeat any part that broke up.':`TCP एक पंजीकृत फ़ोन कॉल जैसा है: पहले दोनों कहते हैं "क्या आप मुझे सुन रहे हैं? / हाँ, क्या आप सुन रहे हैं? / हाँ!" फिर हर वाक्य को नंबर देते हैं और जो हिस्सा कट गया उसे दोहराते हैं।`,"TCP port 443":`TCP पोर्ट 443`,"TCP port changes":`TCP पोर्ट बदलता है`,"TCP probes bandwidth cautiously (+1 MSS per RTT) to avoid saturating queues.":`कतारें न भर जाएँ इसलिए TCP बैंडविड्थ को सावधानी से परखता है (हर RTT पर +1 MSS)।`,"TCP provides reliable, ordered, congestion-controlled byte-stream delivery over unreliable IP networks using sequence numbers, acknowledgments, sliding windows, and adaptive congestion control.":`TCP अविश्वसनीय IP नेटवर्क पर भरोसेमंद, क्रमबद्ध और कंजेशन-नियंत्रित बाइट-स्ट्रीम डिलीवरी देता है। इसके लिए वह सीक्वेंस नंबर, एक्नॉलेजमेंट, स्लाइडिंग विंडो और अनुकूली कंजेशन कंट्रोल का उपयोग करता है।`,"TCP puts every webpage item on one single-lane train track—if one boxcar stalls, all cars behind it wait. QUIC gives each item its own fast lane over UDP with built-in encryption.":`TCP वेबपेज की हर चीज़ को एक ही लेन वाली रेल पटरी पर रखता है: एक डिब्बा अटके तो पीछे सब रुकते हैं। QUIC हर चीज़ को UDP पर बिल्ट-इन एन्क्रिप्शन के साथ अपनी तेज़ लेन देता है।`,"TCP slow start":`TCP स्लो स्टार्ट`,"TCP to Proxy":`प्रॉक्सी तक TCP`,"TIME_WAIT (2*MSL) prevents old delayed segments from corrupting a new connection on the same 4-tuple.":`TIME_WAIT (2*MSL) पुराने देरी से आए सेगमेंट को उसी 4-ट्यूपल पर नए कनेक्शन को बिगाड़ने से रोकता है।`,"TLD Referral":`TLD रेफ़रल`,"TLD server":`TLD सर्वर`,"TLS & Authentication":`TLS और प्रमाणीकरण`,"TLS 1.3 1-RTT Handshake":`TLS 1.3 का 1-RTT हैंडशेक`,"TLS 1.3 Handshake":`TLS 1.3 हैंडशेक`,"TLS 1.3 Session to Port 443":`पोर्ट 443 पर TLS 1.3 सेशन`,"TLS 1.3 cuts handshake latency from 2 RTTs (TLS 1.2) down to 1 RTT by sending key shares in ClientHello.":`ClientHello में कुंजी-शेयर भेजकर TLS 1.3 हैंडशेक की देरी 2 RTT (TLS 1.2) से घटाकर 1 RTT कर देता है।`,"TLS 1.3 provides confidentiality, integrity, and server authentication in a single 1-RTT handshake using ephemeral Diffie-Hellman (ECDHE) for forward secrecy and AEAD ciphers.":`TLS 1.3 एक ही 1-RTT हैंडशेक में गोपनीयता, अखंडता और सर्वर की पहचान की पुष्टि देता है। फ़ॉरवर्ड सीक्रेसी के लिए यह अस्थायी Diffie-Hellman (ECDHE) और AEAD साइफ़र का उपयोग करता है।`,"TLS AEAD Encrypted HTTP/1.1 or Binary HTTP/2 Frames":`TLS AEAD से एन्क्रिप्टेड HTTP/1.1 या बाइनरी HTTP/2 फ़्रेम`,"TLS Downgrade / POODLE / BEAST":`TLS डाउनग्रेड / POODLE / BEAST`,"TLS Record Layer (5B header + AEAD encrypted payload)":`TLS रिकॉर्ड लेयर (5B हेडर + AEAD एन्क्रिप्टेड पेलोड)`,"TLS certificate lifetime":`TLS सर्टिफ़िकेट की अवधि`,"TLS encryption prevents passive LAN sniffers on shared media from reading sensitive HTTP data.":`TLS एन्क्रिप्शन साझा माध्यम पर निष्क्रिय LAN स्निफ़र को संवेदनशील HTTP डेटा पढ़ने से रोकता है।`,"TLS extensions announcing application protocol (h2/http1.1) and target hostname before encryption completes.":`TLS एक्सटेंशन जो एन्क्रिप्शन पूरा होने से पहले एप्लिकेशन प्रोटोकॉल (h2/http1.1) और लक्ष्य होस्टनेम बताते हैं।`,"TLS silently downgrades to plaintext HTTP":`TLS चुपचाप सादे HTTP पर उतर जाता है`,"TLS termination offloads CPU-heavy crypto from app servers and allows L7 inspection/routing.":`TLS समापन ऐप सर्वरों से भारी CPU वाला क्रिप्टो हटा देता है और L7 निरीक्षण/रूटिंग संभव बनाता है।`,"TTL is decremented by 1 and header checksum is recomputed":`TTL 1 घटता है और हेडर चेकसम दोबारा निकाला जाता है`,"TTL prevents infinite Layer 3 forwarding loops by triggering ICMP Type 11.":`TTL, ICMP टाइप 11 चलाकर लेयर 3 फ़ॉरवर्डिंग के अंतहीन लूप को रोकता है।`,"TTL reaching 1":`TTL का 1 तक पहुँचना`,"TTL=1 Expiry":`TTL=1 समाप्ति`,"TTL=3 reaches 203.0.113.10":`TTL=3 203.0.113.10 तक पहुँचता है`,"TURN (Traversal Using Relays around NAT) relays media packets as a fallback.":`TURN (Traversal Using Relays around NAT) विकल्प के तौर पर मीडिया पैकेट रिले करता है।`,"TV Box / Client sends IGMPv3 Membership Report joining 239.1.1.5.":`टीवी बॉक्स / क्लाइंट 239.1.1.5 में शामिल होने के लिए IGMPv3 Membership Report भेजता है।`,"Tagged Bidirectional Commands + MIME Body Parts":`टैग वाले दोतरफ़ा कमांड + MIME बॉडी हिस्से`,"Target CLI device":`CLI का लक्ष्य डिवाइस`,Telnet:Z,"Telnet cleartext":`Telnet सादा टेक्स्ट`,"Test your knowledge on any of the 39 protocols or take the mixed challenge.":`39 प्रोटोकॉल में से किसी पर भी अपनी जानकारी परखें या मिली-जुली चुनौती लें।`,"Text-based SIP Headers + SDP Body":`टेक्स्ट-आधारित SIP हेडर + SDP बॉडी`,"The DNS server has no record for the website":`DNS सर्वर के पास वेबसाइट का रिकॉर्ड नहीं है`,"The Dark Router":`अंधेरा राउटर`,"The ISP is blocking port 80":`ISP पोर्ट 80 रोक रहा है`,"The Missing Name":`ग़ायब नाम`,"The Over-Eager Firewall":`ज़रूरत से ज़्यादा सख़्त फ़ायरवॉल`,"The PC can still see its own network settings, but nothing past the first hop works.":`PC को अपनी नेटवर्क सेटिंग अब भी दिखती है, पर पहले हॉप के आगे कुछ नहीं चलता।`,"The PC has a duplicate IP address":`PC का IP पता डुप्लिकेट है`,"The PC has the wrong subnet mask":`PC का सबनेट मास्क ग़लत है`,"The PC is using the wrong DNS server":`PC ग़लत DNS सर्वर इस्तेमाल कर रहा है`,"The PPP + PPPoE header consumes 8 bytes inside the 1500B Ethernet frame":`PPP + PPPoE हेडर 1500B ईथरनेट फ़्रेम के भीतर 8 बाइट खा जाता है`,"The PSK never crosses the air; peers prove knowledge of PMK via a MIC over the nonces.":`PSK कभी हवा से नहीं गुज़रती; पीयर नॉन्स पर MIC से साबित करते हैं कि उन्हें PMK पता है।`,"The Silent Laptop":`चुप लैपटॉप`,"The Supplicant (device) authenticates via the Authenticator (AP/switch) to the RADIUS server.":`सप्लिकेंट (डिवाइस) ऑथेंटिकेटर (AP/स्विच) के ज़रिए RADIUS सर्वर से प्रमाणित होता है।`,"The WebSocket Protocol (WS / WSS)":`WebSocket प्रोटोकॉल (WS / WSS)`,"The Wi-Fi router is powered off":`Wi-Fi राउटर बंद है`,"The Wrong Neighbourhood":`ग़लत मोहल्ला`,"The authoritative server no longer has a record for example.com":`ऑथोरिटेटिव सर्वर के पास अब example.com का रिकॉर्ड नहीं है`,"The cable between the PC and the router is disconnected":`PC और राउटर के बीच का केबल निकला हुआ है`,"The cable to the ISP is unplugged":`ISP वाला केबल निकला हुआ है`,"The client cannot reach its DNS resolver":`क्लाइंट अपने DNS रिज़ॉल्वर तक नहीं पहुँच पा रहा`,"The entire original inner IP packet (header + payload)":`पूरा मूल भीतरी IP पैकेट (हेडर + पेलोड)`,"The error names who blocked the packet. Read it carefully.":`त्रुटि बताती है कि पैकेट किसने रोका। ध्यान से पढ़ें।`,'The error says "No route / link down" before the packet even leaves the PC.':`पैकेट के PC से निकलने से पहले ही त्रुटि कहती है "No route / link down"।`,"The host assigns an APIPA link-local IP (169.254.x.x)":`होस्ट ख़ुद को APIPA लिंक-लोकल IP (169.254.x.x) दे देता है`,"The hostname must first be resolved to an IP address via DNS.":`पहले DNS से होस्टनेम को IP पते में हल करना पड़ता है।`,"The network card shuts down":`नेटवर्क कार्ड बंद हो जाता है`,"The root server is powered off":`रूट सर्वर बंद है`,"The router has stopped doing NAT":`राउटर ने NAT करना बंद कर दिया है`,"The router interface for Subnet A is shut down":`सबनेट A का राउटर इंटरफ़ेस बंद है`,"The router is out of IP addresses":`राउटर के IP पते ख़त्म हो गए हैं`,"The server replies with SYN+ACK to acknowledge the client’s SYN and send its own ISN.":`सर्वर क्लाइंट के SYN की पावती देने और अपना ISN भेजने के लिए SYN+ACK से जवाब देता है।`,"The trace shows the resolver was reached and gave a definite answer, so connectivity is fine.":`ट्रेस दिखाता है कि रिज़ॉल्वर तक पहुँचा गया और उसने पक्का जवाब दिया, इसलिए कनेक्टिविटी ठीक है।`,"The web server firewall is blocking pings":`वेब सर्वर का फ़ायरवॉल ping रोक रहा है`,"The web server has the wrong IP address":`वेब सर्वर का IP पता ग़लत है`,"There is no difference":`कोई अंतर नहीं`,"They are identical":`दोनों एक जैसे हैं`,"They disable TLS":`वे TLS बंद कर देते हैं`,"They probe a known plain-HTTP URL (e.g. /generate_204) or read DHCP Option 114":`वे किसी जाने-पहचाने सादे-HTTP URL (जैसे /generate_204) की जाँच करते हैं या DHCP विकल्प 114 पढ़ते हैं`,"They scan port 22":`वे पोर्ट 22 स्कैन करते हैं`,"They send BGP UPDATE":`वे BGP UPDATE भेजते हैं`,"Three Autonomous Systems exchange prefixes; break primary link and watch BGP re-converge.":`तीन ऑटोनॉमस सिस्टम प्रीफ़िक्स बदलते हैं; मुख्य लिंक तोड़ें और BGP का दोबारा तालमेल देखें।`,"Time To Live in DNS tells caches how many seconds to store the record before re-querying.":`DNS में Time To Live कैश को बताता है कि दोबारा पूछने से पहले रिकॉर्ड को कितने सेकंड सँभालकर रखना है।`,"Time To Live — 8-bit IPv4 hop counter decremented by each router; prevents infinite routing loops and powers traceroute.":`टाइम टू लिव — 8-बिट IPv4 हॉप काउंटर जिसे हर राउटर एक घटाता है; अंतहीन रूटिंग लूप रोकता है और traceroute इसी पर चलता है।`,"Tiny 2–6 byte framed messages flow bidirectionally; client frames are XOR-masked.":`2–6 बाइट के छोटे फ़्रेम वाले संदेश दोनों दिशाओं में बहते हैं; क्लाइंट के फ़्रेम XOR से मास्क किए जाते हैं।`,"To allocate a new IP":`नया IP देने के लिए`,"To allow delayed packets to drain and ensure the peer received the final ACK":`देरी वाले पैकेट निकल जाने देने और यह पक्का करने के लिए कि पीयर को अंतिम ACK मिला`,"To assign IP addresses":`IP पते देने के लिए`,"To assign MAC addresses":`MAC पते देने के लिए`,"To bypass TCP":`TCP को लाँघने के लिए`,"To change SSID":`SSID बदलने के लिए`,"To compress HTML":`HTML को संपीड़ित करने के लिए`,"To compress JSON":`JSON संपीड़ित करने के लिए`,"To compute TCP checksums":`TCP चेकसम निकालने के लिए`,"To disable MAC addresses":`MAC पते बंद करने के लिए`,"To disable SNI":`SNI बंद करने के लिए`,"To double bandwidth":`बैंडविड्थ दोगुनी करने के लिए`,"To encrypt files":`फ़ाइलें एन्क्रिप्ट करने के लिए`,"To encrypt remaining bytes":`बचे हुए बाइट एन्क्रिप्ट करने के लिए`,"To flush DNS cache":`DNS कैश साफ़ करने के लिए`,"To increment TTL":`TTL बढ़ाने के लिए`,"To inform all other DHCP servers whose offers were declined":`बाक़ी सभी DHCP सर्वरों को बताने के लिए जिनके ऑफ़र ठुकराए गए`,"To prevent cache poisoning of legacy transparent HTTP proxies":`पुराने पारदर्शी HTTP प्रॉक्सी के कैश पॉइज़निंग को रोकने के लिए`,"To prevent passive observers from seeing server identity/metadata":`ताकि निष्क्रिय पर्यवेक्षक सर्वर की पहचान/मेटाडेटा न देख सकें`,"To reduce MTU":`MTU घटाने के लिए`,"To reset MAC tables":`MAC तालिकाएँ रीसेट करने के लिए`,"To reset TCP seq":`TCP seq रीसेट करने के लिए`,"To route BGP":`BGP रूट करने के लिए`,"To sign certificates so browsers trust the server’s public key":`सर्टिफ़िकेट पर हस्ताक्षर करने के लिए ताकि ब्राउज़र सर्वर की सार्वजनिक कुंजी पर भरोसा करें`,"To speed up HTTP":`HTTP तेज़ करने के लिए`,"To tell a peer its public IP:port behind NAT":`NAT के पीछे बैठे पीयर को उसका सार्वजनिक IP:पोर्ट बताने के लिए`,"To transcode 4K video":`4K वीडियो ट्रांसकोड करने के लिए`,"To trigger DNS caching":`DNS कैशिंग चालू करने के लिए`,"To verify you are connecting to the genuine server and not a MITM proxy":`यह जाँचने के लिए कि आप असली सर्वर से जुड़ रहे हैं, MITM प्रॉक्सी से नहीं`,"Toggle 20% Loss":`20% लॉस चालू/बंद करें`,"Toggle Connect Cable":`केबल जोड़ने का मोड बदलें`,"Toggle Device Power":`डिवाइस चालू/बंद करें`,"Toggle Properties Inspector":`गुण इंस्पेक्टर दिखाएँ/छिपाएँ`,"Toggle SYN Cookies on Server":`सर्वर पर SYN Cookies चालू करें`,"Trace recursive vs iterative resolution with TTL caching across Root, .com TLD, and Authoritative servers.":`रूट, .com TLD और ऑथोरिटेटिव सर्वरों के पार TTL कैशिंग के साथ रिकर्सिव बनाम इटेरेटिव रेज़ोल्यूशन का पीछा करें।`,"Traceroute Hop 1 (TTL=1)":`ट्रेसरूट हॉप 1 (TTL=1)`,"Traceroute Hop 2 (TTL=2)":`ट्रेसरूट हॉप 2 (TTL=2)`,"Traceroute sends TTL=1; Home Router drops it and returns ICMP Type 11 Time Exceeded.":`ट्रेसरूट TTL=1 भेजता है; होम राउटर उसे गिराकर ICMP टाइप 11 Time Exceeded लौटाता है।`,"Traffic Gen":`ट्रैफ़िक जनरेटर`,"Traffic across WAN link is encapsulated inside encrypted UDP/51820":`WAN लिंक पर ट्रैफ़िक एन्क्रिप्टेड UDP/51820 के भीतर समाया रहता है`,"Traffic destination":`ट्रैफ़िक का गंतव्य`,"Traffic pattern":`ट्रैफ़िक का पैटर्न`,"Traffic source":`ट्रैफ़िक का स्रोत`,"Transit AS64510":`ट्रांज़िट AS64510`,"Transit AS64510 prepends 64510 -> AS_PATH [64510, 64511] and compares against direct link.":`ट्रांज़िट AS64510, 64510 जोड़ता है -> AS_PATH [64510, 64511] और सीधे लिंक से तुलना करता है।`,"Transmission Control Protocol":`ट्रांसमिशन कंट्रोल प्रोटोकॉल`,"Transparent Relay":`पारदर्शी रिले`,Transport:Q,"Transport Layer Security (TLS 1.3)":`ट्रांसपोर्ट लेयर सिक्योरिटी (TLS 1.3)`,"Transport-layer Head-of-Line (HoL) blocking":`ट्रांसपोर्ट-लेयर हेड-ऑफ़-लाइन (HoL) ब्लॉकिंग`,"Trigger ICMP Type 3 Code 4 Fragmentation Needed":`ICMP टाइप 3 कोड 4 Fragmentation Needed ट्रिगर करें`,"Trigger RTO timeout & cwnd drop to 1 MSS":`RTO टाइमआउट कराएँ और cwnd को 1 MSS तक गिराएँ`,"Trigger SYN burst against Web Server":`वेब सर्वर पर SYN बर्स्ट चलाएँ`,Troubleshooting:$,"Trunk port between Switch and Router carries tagged 802.1Q frames for VLAN 10 & 20":`स्विच और राउटर के बीच का ट्रंक पोर्ट VLAN 10 और 20 के टैग वाले 802.1Q फ़्रेम ले जाता है`,"Tunnel Mode wraps and encrypts the full original IP packet inside a new outer IP header.":`टनल मोड पूरे मूल IP पैकेट को नए बाहरी IP हेडर में लपेटकर एन्क्रिप्ट करता है।`,"Tunnel SOCKS5 inside SSH (`ssh -D 1080`) or TLS.":"SOCKS5 को SSH (`ssh -D 1080`) या TLS के भीतर टनल करें।","Two LANs Joined by a Router":`एक राउटर से जुड़े दो LAN`,"Two friends behind locked apartment gates (NATs) ask a lookout tower (STUN) what their outside gate numbers are, trade those numbers, and then throw video balls directly between gates.":`ताले लगे अपार्टमेंट गेटों (NAT) के पीछे बैठे दो दोस्त एक वॉचटावर (STUN) से अपने बाहरी गेट नंबर पूछते हैं, वे नंबर आपस में बदलते हैं, और फिर गेटों के बीच सीधे वीडियो की गेंद फेंकते हैं।`,"Type 0 Echo Reply":`टाइप 0 Echo Reply`,"Type 0 Echo Reply measures RTT":`टाइप 0 इको रिप्लाई RTT मापता है`,"Type 11 Time Exceeded":`टाइप 11 Time Exceeded`,"Type 11 and Type 3":`टाइप 11 और टाइप 3`,"Type 13 and Type 14":`टाइप 13 और टाइप 14`,"Type 3 Dest Unreachable":`टाइप 3 Dest Unreachable`,"Type 5 and Type 8":`टाइप 5 और टाइप 8`,"Type 8 Echo Request":`टाइप 8 Echo Request`,"Type 8 Echo Request reaches target":`टाइप 8 इको रिक्वेस्ट लक्ष्य तक पहुँचता है`,"Type 8 and Type 0":`टाइप 8 और टाइप 0`,"UDP (EAP-TLS / PEAP over 802.1X)":`UDP (802.1X पर EAP-TLS / PEAP)`,"UDP (IKEv2) + IP Proto 50 (ESP)":`UDP (IKEv2) + IP प्रोटो 50 (ESP)`,"UDP (port 443)":`UDP (पोर्ट 443)`,"UDP (queries), TCP (zone transfers / >512B)":`UDP (क्वेरी), TCP (ज़ोन ट्रांसफ़र / >512B)`,"UDP + Built-in TLS 1.3":`UDP + बिल्ट-इन TLS 1.3`,"UDP Amplification DDoS":`UDP एम्प्लिफ़िकेशन DDoS`,"UDP Associate, IPv6, and authentication":`UDP Associate, IPv6 और प्रमाणीकरण`,"UDP Query Dropped":`UDP क्वेरी गिरी`,"UDP avoids handshake and retransmission head-of-line delays":`UDP हैंडशेक और रीट्रांसमिशन से होने वाली हेड-ऑफ़-लाइन देरी से बचता है`,"UDP encrypts audio automatically":`UDP ऑडियो अपने-आप एन्क्रिप्ट करता है`,"UDP guarantees zero packet loss":`UDP शून्य पैकेट लॉस की गारंटी देता है`,"UDP headers contain just 4 two-byte fields: Src Port, Dst Port, Length, and Checksum (8 bytes).":`UDP हेडर में सिर्फ़ 4 दो-बाइट फ़ील्ड होते हैं: सोर्स पोर्ट, डेस्ट पोर्ट, लंबाई और चेकसम (8 बाइट)।`,"UDP ignores IP addresses":`UDP IP पतों को अनदेखा करता है`,"UDP is a lightweight, connectionless transport protocol with an 8-byte header and zero handshake or retransmission overhead, ideal for real-time audio/video, DNS, and QUIC.":`UDP एक हल्का, कनेक्शन-रहित ट्रांसपोर्ट प्रोटोकॉल है जिसमें 8-बाइट हेडर है और हैंडशेक या रीट्रांसमिशन का कोई बोझ नहीं; रियल-टाइम ऑडियो/वीडियो, DNS और QUIC के लिए आदर्श।`,"UDP is like tossing postcards into a mailbox as fast as you can: no phone call first, no waiting for receipts—fast and lightweight, even if one card blows away in the wind.":`UDP पोस्टकार्ड को जितनी तेज़ी से हो सके मेलबॉक्स में डालने जैसा है: न पहले फ़ोन कॉल, न रसीद का इंतज़ार; तेज़ और हल्का, भले ही हवा कोई कार्ड उड़ा ले जाए।`,"UPDATE (Prefix Announcement)":`UPDATE (प्रीफ़िक्स घोषणा)`,"UPDATE messages carry withdrawn routes, path attributes, and NLRI prefixes.":`UPDATE संदेश वापस लिए गए रूट, पथ विशेषताएँ और NLRI प्रीफ़िक्स ले जाते हैं।`,"USER / PASS -> +OK Logged in":`USER / PASS -> +OK Logged in`,"USER / PASS login on TCP 21":`TCP 21 पर USER / PASS लॉगिन`,"USER/PASS commands travel in plaintext without TLS.":`USER/PASS कमांड बिना TLS के सादे टेक्स्ट में जाते हैं।`,"Unauthenticated PLC Register Manipulation":`बिना प्रमाणीकरण के PLC रजिस्टर में छेड़छाड़`,"Unauthenticated deauthentication/disassociation attacks":`बिना प्रमाणीकरण वाले डीऑथेंटिकेशन/डिसएसोसिएशन हमले`,Undo:ee,"Undo (Ctrl+Z)":`पूर्ववत करें (Ctrl+Z)`,"Unencrypted SIP on port 5060 leaks caller IDs and credentials; weak PBX auth allows expensive international call hijack.":`पोर्ट 5060 पर बिना एन्क्रिप्शन वाला SIP कॉलर ID और क्रेडेंशियल लीक करता है; कमज़ोर PBX प्रमाणीकरण से महँगी अंतरराष्ट्रीय कॉल हाइजैक हो सकती हैं।`,"Unencrypted SOCKS5 Credentials":`बिना एन्क्रिप्शन वाले SOCKS5 क्रेडेंशियल`,"Unicast Ethernet Frame":`यूनिकास्ट ईथरनेट फ़्रेम`,"Unknown Peer Key (Silent Drop)":`अज्ञात पीयर कुंजी (चुपचाप गिराना)`,"Upgrade Rejected (403)":`अपग्रेड अस्वीकृत (403)`,"Upgrade: websocket + Sec-WebSocket-Key":`Upgrade: websocket + Sec-WebSocket-Key`,"Upgrades the plaintext TCP connection to TLS encryption":`सादे टेक्स्ट वाले TCP कनेक्शन को TLS एन्क्रिप्शन में अपग्रेड करता है`,"Upstream Routing & LB":`अपस्ट्रीम रूटिंग और लोड बैलेंसिंग`,'Use "Check cables and power" to look at the status lights on every device and link.':`हर डिवाइस और लिंक की स्थिति वाली बत्तियाँ देखने के लिए "केबल और बिजली जाँचें" इस्तेमाल करें।`,'Use "Check cables and power": one device is not powered on.':`"केबल और बिजली जाँचें" इस्तेमाल करें: एक डिवाइस चालू नहीं है।`,"Use ARP":`ARP का उपयोग करें`,"Use CHAP authentication and enable TCP MSS Clamping (1452) on home routers.":`CHAP प्रमाणीकरण इस्तेमाल करें और होम राउटर पर TCP MSS क्लैंपिंग (1452) चालू करें।`,"Use DHCP Option 114 (RFC 8910) with HTTP probes and pair with per-user Passpoint/802.1X.":`HTTP जाँच के साथ DHCP विकल्प 114 (RFC 8910) इस्तेमाल करें और उसे प्रति-उपयोगकर्ता Passpoint/802.1X से जोड़ें।`,"Use DNSSEC cryptographic signatures, source port randomization, and DoH/DoT.":`DNSSEC क्रिप्टोग्राफ़िक हस्ताक्षर, सोर्स पोर्ट रैंडमाइज़ेशन और DoH/DoT का उपयोग करें।`,"Use ICMP":`ICMP का उपयोग करें`,"Use IKEv2 with X.509 certificates or high-entropy keys and AES-GCM.":`X.509 सर्टिफ़िकेट या उच्च-एंट्रॉपी कुंजियों और AES-GCM के साथ IKEv2 इस्तेमाल करें।`,"Use RTMPS (RTMP over TLS)":`RTMPS (TLS पर RTMP) इस्तेमाल करें`,"Use SIPS (TLS on port 5061) and SRTP for voice media.":`आवाज़ के लिए SIPS (पोर्ट 5061 पर TLS) और SRTP इस्तेमाल करें।`,"Use UDP":`UDP का उपयोग करें`,"Use ephemeral peer keys or MASQUE/relay proxies when anonymity from endpoints is required.":`जब एंडपॉइंट से गुमनामी चाहिए तो अस्थायी पीयर कुंजियाँ या MASQUE/रिले प्रॉक्सी इस्तेमाल करें।`,"Use hashed NSEC3 records with opt-out to prevent easy zone walking.":`ज़ोन-वॉकिंग रोकने के लिए opt-out के साथ हैश वाले NSEC3 रिकॉर्ड इस्तेमाल करें।`,"Use long random passphrases (16+ chars) or upgrade to WPA3-SAE (Dragonfly) which resists offline dictionary attacks.":`लंबे यादृच्छिक पासफ़्रेज़ (16+ अक्षर) रखें या WPA3-SAE (Dragonfly) पर जाएँ, जो ऑफ़लाइन डिक्शनरी हमलों का सामना करता है।`,"Use mDNS obfuscated host candidates and TURN-only relay policies when IP privacy is required.":`IP की निजता चाहिए तो mDNS से छिपाए गए host कैंडिडेट और केवल-TURN रिले नीति अपनाएँ।`,"Use managed enterprise DoH policies or TLS-aware DNS proxies.":`प्रबंधित एंटरप्राइज़ DoH नीतियाँ या TLS-जागरूक DNS प्रॉक्सी इस्तेमाल करें।`,"Use strict RFC 9112 parsing, reject duplicate headers, or adopt HTTP/2 end-to-end.":`RFC 9112 के अनुसार सख़्त पार्सिंग करें, दोहरे हेडर अस्वीकार करें या शुरू से अंत तक HTTP/2 अपनाएँ।`,"User Authentication":`उपयोगकर्ता प्रमाणीकरण`,"User Datagram Protocol":`यूज़र डेटाग्राम प्रोटोकॉल`,"User-facing protocols: HTTP, HTTPS, DNS, DoH, SMTP, IMAP, POP3, FTP, SSH, SMB, Modbus.":`उपयोगकर्ता के सामने वाले प्रोटोकॉल: HTTP, HTTPS, DNS, DoH, SMTP, IMAP, POP3, FTP, SSH, SMB, Modbus.`,"Using a 64-bit Connection ID independent of IP/port":`IP/पोर्ट से स्वतंत्र 64-बिट Connection ID इस्तेमाल करके`,"VLANs & Inter-VLAN Routing":`VLAN और इंटर-VLAN रूटिंग`,"VLC / NVR Client":`VLC / NVR क्लाइंट`,"VPN Gateway A":`VPN गेटवे A`,"VPN Gateway B":`VPN गेटवे B`,"VPN gateways negotiate IKE Security Association parameters over UDP port 500.":`VPN गेटवे UDP पोर्ट 500 पर IKE सिक्योरिटी असोसिएशन के पैरामीटर तय करते हैं।`,"Validate the HTTP Origin header and use WSS (TLS) with CSRF tokens.":`HTTP Origin हेडर जाँचें और CSRF टोकन के साथ WSS (TLS) इस्तेमाल करें।`,"Validating Resolver":`जाँचने वाला रिज़ॉल्वर`,"Validating resolver sets EDNS0 DO (DNSSEC OK) bit requesting RRSIG signatures.":`जाँच करने वाला रिज़ॉल्वर RRSIG हस्ताक्षर माँगने के लिए EDNS0 का DO (DNSSEC OK) बिट सेट करता है।`,"Ver=5, Methods=[0x00, 0x02]":`Ver=5, Methods=[0x00, 0x02]`,"Verify Root -> TLD DS -> Zone DNSKEY":`रूट -> TLD DS -> ज़ोन DNSKEY की जाँच`,"Voice flows over RTP; BYE hangs up":`आवाज़ RTP पर बहती है; BYE कॉल काटता है`,"WPA2 4-Way Key Handshake":`WPA2 का 4-वे की हैंडशेक`,"WPA2 mandates AES-CCMP for strong confidentiality and integrity.":`मज़बूत गोपनीयता और अखंडता के लिए WPA2 में AES-CCMP अनिवार्य है।`,"WPA2 secures Wi-Fi networks using a 4-way EAPOL-Key handshake between the client and Access Point to prove both know the PSK without ever transmitting it over the air, deriving fresh AES-CCMP encryption keys.":`WPA2 क्लाइंट और एक्सेस पॉइंट के बीच 4-वे EAPOL-Key हैंडशेक से Wi-Fi सुरक्षित करता है, जो बिना PSK को हवा में भेजे साबित करता है कि दोनों उसे जानते हैं, और नई AES-CCMP एन्क्रिप्शन कुंजियाँ बनाता है।`,"WPA3 Simultaneous Authentication of Equals (SAE) replaces static PSK key derivation.":`WPA3 Simultaneous Authentication of Equals (SAE), स्थिर PSK कुंजी निर्माण की जगह लेता है।`,"WPA3 replaces WPA2’s vulnerable PSK derivation with SAE (Dragonfly) password-authenticated key exchange, providing forward secrecy and neutralizing offline dictionary cracking, plus mandatory Protected Management Frames (PMF).":`WPA3, WPA2 के कमज़ोर PSK निर्माण की जगह SAE (Dragonfly) पासवर्ड-प्रमाणित की एक्सचेंज लाता है, जिससे फ़ॉरवर्ड सीक्रेसी मिलती है, ऑफ़लाइन डिक्शनरी क्रैकिंग बेअसर होती है, और सुरक्षित मैनेजमेंट फ़्रेम (PMF) अनिवार्य होते हैं।`,"Weak pre-shared keys in legacy IKEv1 aggressive mode expose hashes to offline brute force.":`पुराने IKEv1 एग्रेसिव मोड में कमज़ोर प्री-शेयर्ड कुंजियाँ हैश को ऑफ़लाइन ब्रूट-फ़ोर्स के सामने खोल देती हैं।`,"Web Real-Time Communication (ICE / STUN / DTLS / SRTP)":`वेब रियल-टाइम कम्युनिकेशन (ICE / STUN / DTLS / SRTP)`,"Web Server":`वेब सर्वर`,"Web Server replies with ICMP Type 0 Echo Reply; Client calculates round-trip latency.":`वेब सर्वर ICMP टाइप 0 Echo Reply से जवाब देता है; क्लाइंट राउंड-ट्रिप देरी निकालता है।`,"Web server is powered off and unreachable":`वेब सर्वर बंद है और उस तक पहुँचा नहीं जा सकता`,"WebRTC enables sub-second peer-to-peer browser video, audio, and data channels by discovering public NAT mappings via STUN/TURN, punching holes with ICE, securing keys via DTLS, and streaming encrypted SRTP.":`WebRTC ब्राउज़रों के बीच एक सेकंड से कम देरी वाले सीधे वीडियो, ऑडियो और डेटा चैनल देता है: STUN/TURN से सार्वजनिक NAT मैपिंग खोजता है, ICE से रास्ता बनाता है, DTLS से कुंजियाँ सुरक्षित करता है और एन्क्रिप्टेड SRTP स्ट्रीम करता है।`,"WebRTC mandates DTLS key exchange paired with SRTP media encryption.":`WebRTC, DTLS कुंजी विनिमय के साथ SRTP मीडिया एन्क्रिप्शन अनिवार्य करता है।`,"WebSocket includes native Ping and Pong control frames.":`WebSocket में Ping और Pong नाम के अपने कंट्रोल फ़्रेम होते हैं।`,"WebSocket upgrades a standard HTTP/1.1 TCP connection into a persistent, full-duplex, low-overhead bidirectional message channel for live chat, trading feeds, and multiplayer games.":`WebSocket एक सामान्य HTTP/1.1 TCP कनेक्शन को लाइव चैट, ट्रेडिंग फ़ीड और मल्टीप्लेयर गेम के लिए स्थायी, दोतरफ़ा और कम बोझ वाले संदेश चैनल में बदल देता है।`,"What Content-Type carries binary DNS wire messages in DoH?":`DoH में बाइनरी DNS संदेश कौन-सा Content-Type ले जाता है?`,"What EtherType carries WPA2 4-way handshake frames?":`WPA2 4-वे हैंडशेक के फ़्रेम कौन-सा EtherType ले जाता है?`,"What IP protocol number identifies ICMP inside an IPv4 header?":`IPv4 हेडर के भीतर कौन-सा IP प्रोटोकॉल नंबर ICMP की पहचान है?`,"What IP protocol number identifies UDP?":`कौन-सा IP प्रोटोकॉल नंबर UDP की पहचान है?`,"What are the four PPPoE Discovery packets in order?":`PPPoE डिस्कवरी के चार पैकेट क्रम से कौन-से हैं?`,"What does IGMP Snooping on a switch prevent?":`स्विच पर IGMP Snooping क्या रोकता है?`,"What does Modbus Function Code 03 do?":`Modbus फ़ंक्शन कोड 03 क्या करता है?`,"What does Stratum 1 mean in NTP?":`NTP में स्ट्रेटम 1 का क्या मतलब है?`,"What does a validating resolver return when a DNSSEC signature fails verification?":`DNSSEC हस्ताक्षर की जाँच विफल होने पर जाँच करने वाला रिज़ॉल्वर क्या लौटाता है?`,"What does mandatory PMF (802.11w) in WPA3 prevent?":`WPA3 में अनिवार्य PMF (802.11w) किसे रोकता है?`,"What does the STARTTLS command do in SMTP?":`SMTP में STARTTLS कमांड क्या करता है?`,"What does the TTL value in a DNS record control?":`DNS रिकॉर्ड में TTL मान क्या नियंत्रित करता है?`,"What does the acronym DORA stand for in DHCP?":`DHCP में DORA का पूरा रूप क्या है?`,"What happens at every Layer 3 router as an IPv4 packet is forwarded?":`IPv4 पैकेट आगे भेजते समय हर लेयर 3 राउटर पर क्या होता है?`,"What happens before the browser sends an HTTP GET to www.example.com if the IP is unknown?":`अगर IP पता मालूम न हो तो www.example.com को HTTP GET भेजने से पहले ब्राउज़र क्या करता है?`,"What happens during the SSH KEX_ECDH phase?":`SSH के KEX_ECDH चरण में क्या होता है?`,"What happens if no DHCP server responds on a Windows/macOS host?":`अगर Windows/macOS होस्ट को कोई DHCP सर्वर जवाब न दे तो क्या होता है?`,"What happens if the server presents an expired X.509 certificate?":`अगर सर्वर एक्सपायर्ड X.509 सर्टिफ़िकेट पेश करे तो क्या होता है?`,"What header prevents SSL-stripping attacks after a user’s first visit?":`उपयोगकर्ता की पहली विज़िट के बाद कौन-सा हेडर SSL-स्ट्रिपिंग हमले रोकता है?`,"What is TLS termination at a load balancer?":`लोड बैलेंसर पर TLS समापन क्या है?`,"What is the EtherType value for ARP?":`ARP का EtherType मान क्या है?`,"What is the IPv4 multicast address range?":`IPv4 मल्टीकास्ट पता सीमा क्या है?`,"What is the difference between a recursive query and an iterative query?":`रिकर्सिव क्वेरी और इटेरेटिव क्वेरी में क्या अंतर है?`,"What is the key difference between a forward proxy and a reverse proxy?":`फ़ॉरवर्ड प्रॉक्सी और रिवर्स प्रॉक्सी में मुख्य अंतर क्या है?`,"What is the purpose of a STUN server in WebRTC?":`WebRTC में STUN सर्वर का उद्देश्य क्या है?`,"What is the standard maximum payload (MTU) of an untagged Ethernet II frame?":`बिना टैग वाले ईथरनेट II फ़्रेम का मानक अधिकतम पेलोड (MTU) क्या है?`,"What key exchange replaces PSK in WPA3-Personal?":`WPA3-Personal में PSK की जगह कौन-सा कुंजी विनिमय आता है?`,"What privacy threat does DoH eliminate on public Wi-Fi?":`सार्वजनिक Wi-Fi पर DoH निजता का कौन-सा ख़तरा मिटाता है?`,"What problem in HTTP/2 over TCP does HTTP/3 over QUIC solve?":`TCP पर HTTP/2 की कौन-सी समस्या QUIC पर HTTP/3 हल करता है?`,"What property guarantees past recorded traffic cannot be decrypted even if the server’s long-term private key leaks later?":`कौन-सा गुण यह पक्का करता है कि सर्वर की दीर्घकालिक निजी कुंजी बाद में लीक हो जाए तब भी पहले रिकॉर्ड किया ट्रैफ़िक डिक्रिप्ट न हो सके?`,"What status code does a proxy return when a CONNECT tunnel succeeds?":`CONNECT सुरंग सफल होने पर प्रॉक्सी कौन-सा स्टेटस कोड लौटाता है?`,"What technology cryptographically validates that an ASN is authorized to originate a prefix?":`कौन-सी तकनीक क्रिप्टोग्राफ़िक रूप से जाँचती है कि कोई ASN किसी प्रीफ़िक्स को शुरू करने के लिए अधिकृत है?`,"What triggers TCP Fast Retransmit without waiting for RTO expiration?":`RTO समाप्त होने का इंतज़ार किए बिना TCP फ़ास्ट रीट्रांसमिट किससे शुरू होता है?`,'When a new kid joins class without a seat, they shout "Does anyone have a spare desk?" (Discover), the teacher points to Desk 50 (Offer), the kid says "I’ll take Desk 50!" (Request), and the teacher writes their name down (Ack).':`जब कोई नया बच्चा बिना सीट के कक्षा में आता है, तो वह पूछता है "क्या किसी के पास खाली डेस्क है?" (Discover), शिक्षक डेस्क 50 की ओर इशारा करते हैं (Offer), बच्चा कहता है "मैं डेस्क 50 लूँगा!" (Request), और शिक्षक उसका नाम लिख लेते हैं (Ack)।`,"When direct P2P hole-punching fails (e.g. symmetric NAT), which server relays WebRTC media?":`जब सीधा P2P होल-पंचिंग विफल हो (जैसे सिमेट्रिक NAT), तब WebRTC मीडिया कौन-सा सर्वर रिले करता है?`,"When does POP3 actually purge messages marked with DELE?":`DELE से चिह्नित संदेशों को POP3 असल में कब हटाता है?`,"When the client sends QUIT (UPDATE state)":`जब क्लाइंट QUIT भेजता है (UPDATE स्थिति)`,"When the very first hop is silent, test it directly. A powered-off device looks just like a broken link until you check its status.":`जब पहला हॉप चुप हो, तो उसे सीधे परखें। बंद डिवाइस भी टूटे लिंक जैसा दिखता है, जब तक उसकी स्थिति न जाँचें।`,'When you join hotel Wi-Fi, the gateway holds your internet gate shut and points your browser to the check-in desk ("Accept Terms") before letting packets out.':`जब आप होटल के Wi-Fi से जुड़ते हैं, तो गेटवे आपका इंटरनेट का दरवाज़ा बंद रखता है और पैकेट बाहर जाने देने से पहले आपके ब्राउज़र को रिसेप्शन डेस्क ("शर्तें स्वीकारें") पर भेज देता है।`,"When you plug into an office port or join corporate Wi-Fi, the switch acts like a security guard calling HQ (the RADIUS server) to check your employee badge before opening the gate.":`जब आप दफ़्तर के पोर्ट में प्लग लगाते हैं या कंपनी के Wi-Fi से जुड़ते हैं, तो स्विच सुरक्षा गार्ड की तरह मुख्यालय (RADIUS सर्वर) को फ़ोन करके गेट खोलने से पहले आपका कर्मचारी बैज जाँचता है।`,"When your home router plugs into a fiber ISP line, PPPoE rings the ISP’s front desk (PADI/PADO), logs in with your ISP username/password (CHAP), and gets your public internet IP.":`जब आपका घर का राउटर फ़ाइबर ISP लाइन से जुड़ता है, तो PPPoE ISP के रिसेप्शन पर घंटी बजाता है (PADI/PADO), आपके ISP यूज़रनेम/पासवर्ड से लॉगिन करता है (CHAP), और आपका सार्वजनिक इंटरनेट IP पाता है।`,"Where is RTMP primarily used today?":`आज RTMP मुख्य रूप से कहाँ इस्तेमाल होता है?`,"Which AEAD cipher does WireGuard use for all encrypted tunnel data?":`सुरंग के सारे एन्क्रिप्टेड डेटा के लिए WireGuard कौन-सा AEAD साइफ़र इस्तेमाल करता है?`,"Which BGP message advertises or withdraws IP prefixes?":`कौन-सा BGP संदेश IP प्रीफ़िक्स घोषित या वापस लेता है?`,"Which DNS record tells an SMTP server where to deliver mail for a domain?":`कौन-सा DNS रिकॉर्ड SMTP सर्वर को बताता है कि किसी डोमेन की मेल कहाँ पहुँचानी है?`,"Which DNS record type maps a domain name to an IPv6 address?":`कौन-सा DNS रिकॉर्ड प्रकार डोमेन नाम को IPv6 पते से जोड़ता है?`,"Which DNS server sits at the very top of the hierarchy?":`पदानुक्रम में सबसे ऊपर कौन-सा DNS सर्वर है?`,"Which DNSSEC record holds the digital signature for a record set?":`कौन-सा DNSSEC रिकॉर्ड किसी रिकॉर्ड-समूह का डिजिटल हस्ताक्षर रखता है?`,"Which HTTP header preserves the original client IP behind a reverse proxy?":`रिवर्स प्रॉक्सी के पीछे मूल क्लाइंट का IP कौन-सा HTTP हेडर सुरक्षित रखता है?`,"Which HTTP method asks a forward proxy to open a TCP tunnel for HTTPS?":`कौन-सा HTTP मेथड फ़ॉरवर्ड प्रॉक्सी से HTTPS के लिए TCP सुरंग खुलवाता है?`,"Which HTTP method is idempotent and retrieves a resource without modifying server state?":`कौन-सा HTTP मेथड idempotent है और सर्वर की स्थिति बदले बिना संसाधन लाता है?`,"Which HTTP status code confirms a successful WebSocket handshake?":`कौन-सा HTTP स्टेटस कोड सफल WebSocket हैंडशेक की पुष्टि करता है?`,"Which HTTP status code indicates a resource was successfully returned?":`कौन-सा HTTP स्टेटस कोड बताता है कि संसाधन सफलतापूर्वक लौटाया गया?`,"Which ICMP Type/Code is returned when a router decrements IP TTL to 0?":`जब कोई राउटर IP TTL घटाकर 0 कर दे तो कौन-सा ICMP टाइप/कोड लौटता है?`,"Which ICMP message pair does `ping` use?":"`ping` कौन-सा ICMP संदेश जोड़ा इस्तेमाल करता है?","Which IMAP command enables real-time push notifications without polling?":`कौन-सा IMAP कमांड बिना पोलिंग के रियल-टाइम पुश सूचनाएँ देता है?`,"Which IP protocol number does IGMP use?":`IGMP कौन-सा IP प्रोटोकॉल नंबर इस्तेमाल करता है?`,"Which IPsec sub-protocol provides both confidentiality (encryption) and integrity?":`कौन-सा IPsec उप-प्रोटोकॉल गोपनीयता (एन्क्रिप्शन) और अखंडता दोनों देता है?`,"Which Layer 4 protocol does QUIC run on top of?":`QUIC किस लेयर 4 प्रोटोकॉल के ऊपर चलता है?`,"Which MAC address is used for an Ethernet broadcast frame (like ARP Request)?":`ईथरनेट ब्रॉडकास्ट फ़्रेम (जैसे ARP Request) के लिए कौन-सा MAC पता इस्तेमाल होता है?`,"Which PPP sub-protocol assigns the subscriber’s IPv4 address and DNS servers?":`कौन-सा PPP उप-प्रोटोकॉल ग्राहक का IPv4 पता और DNS सर्वर देता है?`,"Which RFC standardizes announcing the captive portal URL directly in DHCP?":`DHCP में ही कैप्टिव पोर्टल का URL बताने को कौन-सा RFC मानकीकृत करता है?`,"Which RTSP command actually begins media transmission?":`कौन-सा RTSP कमांड असल में मीडिया का प्रसारण शुरू करता है?`,"Which SIP message ends an active call?":`कौन-सा SIP संदेश चालू कॉल को ख़त्म करता है?`,"Which SMB security setting prevents NTLM SMB Relay attacks?":`कौन-सी SMB सुरक्षा सेटिंग NTLM SMB रिले हमलों को रोकती है?`,"Which SSH flag spins up a local SOCKS5 proxy tunnel?":`कौन-सा SSH फ़्लैग स्थानीय SOCKS5 प्रॉक्सी सुरंग खड़ी करता है?`,"Which TCP port does BGP use for peering sessions?":`BGP पीयरिंग सेशन के लिए कौन-सा TCP पोर्ट इस्तेमाल करता है?`,"Which TCP port does Modbus TCP use?":`Modbus TCP कौन-सा TCP पोर्ट इस्तेमाल करता है?`,"Which TCP port does modern SMB (direct-hosted) use?":`आधुनिक SMB (सीधे होस्ट किया हुआ) कौन-सा TCP पोर्ट इस्तेमाल करता है?`,"Which TCP port is the modern standard for authenticated client email submission?":`प्रमाणित क्लाइंट ईमेल सबमिशन के लिए आधुनिक मानक TCP पोर्ट कौन-सा है?`,"Which TCP port is the standard for RTMP ingest?":`RTMP इनजेस्ट के लिए मानक TCP पोर्ट कौन-सा है?`,"Which TLS extension negotiates HTTP/2 vs HTTP/1.1 during the handshake?":`हैंडशेक के दौरान HTTP/2 बनाम HTTP/1.1 कौन-सा TLS एक्सटेंशन तय करता है?`,"Which TLS extension tells the server which hostname the client wants when multiple sites share one IP?":`जब कई साइटें एक IP साझा करें तब क्लाइंट को कौन-सा होस्टनेम चाहिए, यह सर्वर को कौन-सा TLS एक्सटेंशन बताता है?`,"Which UDP port does NTP use?":`NTP कौन-सा UDP पोर्ट इस्तेमाल करता है?`,"Which UDP port does RADIUS use for authentication?":`प्रमाणीकरण के लिए RADIUS कौन-सा UDP पोर्ट इस्तेमाल करता है?`,"Which UDP ports are used by IKEv2 and NAT Traversal?":`IKEv2 और NAT ट्रैवर्सल कौन-से UDP पोर्ट इस्तेमाल करते हैं?`,"Which UDP ports do DHCP servers and clients use?":`DHCP सर्वर और क्लाइंट कौन-से UDP पोर्ट इस्तेमाल करते हैं?`,"Which authentication method is strongly recommended over passwords for SSH?":`SSH में पासवर्ड की जगह कौन-सी प्रमाणीकरण विधि अत्यधिक सुझाई जाती है?`,"Which cipher suite is mandatory in WPA2?":`WPA2 में कौन-सा साइफ़र सूट अनिवार्य है?`,"Which default TCP port does RTSP use?":`RTSP डिफ़ॉल्ट रूप से कौन-सा TCP पोर्ट इस्तेमाल करता है?`,"Which default TCP port does SSH listen on?":`SSH डिफ़ॉल्ट रूप से कौन-से TCP पोर्ट पर सुनता है?`,"Which default port does HTTPS use?":`HTTPS डिफ़ॉल्ट रूप से कौन-सा पोर्ट इस्तेमाल करता है?`,"Which default port does SOCKS5 use?":`SOCKS5 डिफ़ॉल्ट रूप से कौन-सा पोर्ट इस्तेमाल करता है?`,"Which defense mitigates SYN flood memory exhaustion?":`कौन-सा बचाव SYN फ़्लड से मेमोरी ख़त्म होने को कम करता है?`,"Which feature does SOCKS5 add over SOCKS4?":`SOCKS4 के मुक़ाबले SOCKS5 कौन-सी सुविधा जोड़ता है?`,"Which file-transfer protocol runs natively inside an SSH channel?":`कौन-सा फ़ाइल-ट्रांसफ़र प्रोटोकॉल SSH चैनल के भीतर स्वाभाविक रूप से चलता है?`,"Which flags are set in the second packet of a TCP 3-way handshake?":`TCP 3-वे हैंडशेक के दूसरे पैकेट में कौन-से फ़्लैग सेट होते हैं?`,"Which heartbeat opcodes keep idle WebSocket connections alive?":`कौन-से हार्टबीट ऑपकोड निष्क्रिय WebSocket कनेक्शन को जीवित रखते हैं?`,"Which matching rule do routers use when multiple routes match a destination IP?":`गंतव्य IP से कई रूट मेल खाएँ तो राउटर कौन-सा मिलान नियम इस्तेमाल करते हैं?`,"Which mechanism replaces ARP in IPv6?":`IPv6 में ARP की जगह कौन-सा तंत्र लेता है?`,"Which modern extension protects RADIUS traffic with TLS?":`कौन-सा आधुनिक एक्सटेंशन RADIUS ट्रैफ़िक को TLS से सुरक्षित करता है?`,"Which port and transport protocol does standard DNS use for short queries?":`छोटी क्वेरी के लिए मानक DNS कौन-सा पोर्ट और ट्रांसपोर्ट प्रोटोकॉल इस्तेमाल करता है?`,"Which port does DNS over HTTPS (DoH) use?":`DNS over HTTPS (DoH) कौन-सा पोर्ट इस्तेमाल करता है?`,"Which ports are standard for IMAP and IMAPS (TLS)?":`IMAP और IMAPS (TLS) के मानक पोर्ट कौन-से हैं?`,"Which ports are used by standard FTP control and active data?":`मानक FTP का कंट्रोल और एक्टिव डेटा कौन-से पोर्ट इस्तेमाल करते हैं?`,"Which ports do POP3 and POP3S (TLS) use?":`POP3 और POP3S (TLS) कौन-से पोर्ट इस्तेमाल करते हैं?`,"Which ports does SIP use for plaintext and TLS signaling?":`SIP सादे टेक्स्ट और TLS सिग्नलिंग के लिए कौन-से पोर्ट इस्तेमाल करता है?`,"Which protocol carries the actual voice audio after SIP establishes the call?":`SIP के कॉल बना देने के बाद असली आवाज़ कौन-सा प्रोटोकॉल ले जाता है?`,"Which protocol encrypts WebRTC audio and video frames?":`WebRTC के ऑडियो और वीडियो फ़्रेम कौन-सा प्रोटोकॉल एन्क्रिप्ट करता है?`,"Which protocol improves upon WPA2-PSK to stop offline dictionary cracking?":`ऑफ़लाइन डिक्शनरी क्रैकिंग रोकने के लिए कौन-सा प्रोटोकॉल WPA2-PSK को बेहतर बनाता है?`,"Which secure alternative runs over SSH port 22 instead of FTP?":`FTP की जगह SSH पोर्ट 22 पर चलने वाला सुरक्षित विकल्प कौन-सा है?`,"Which sequence terminates an SMTP DATA message body?":`कौन-सा क्रम SMTP DATA संदेश की बॉडी को समाप्त करता है?`,"Which switch feature defends against rogue DHCP servers?":`कौन-सी स्विच सुविधा नकली DHCP सर्वरों से बचाती है?`,"Which switch security feature prevents ARP spoofing?":`कौन-सी स्विच सुरक्षा सुविधा ARP स्पूफ़िंग रोकती है?`,"Which transport protocol and default port does WireGuard use?":`WireGuard कौन-सा ट्रांसपोर्ट प्रोटोकॉल और डिफ़ॉल्ट पोर्ट इस्तेमाल करता है?`,"Which transport protocol does HTTP/1.1 use by default on port 80?":`HTTP/1.1 पोर्ट 80 पर डिफ़ॉल्ट रूप से कौन-सा ट्रांसपोर्ट प्रोटोकॉल इस्तेमाल करता है?`,"Which trio of DNS/email standards combats domain spoofing?":`DNS/ईमेल मानकों की कौन-सी तिकड़ी डोमेन स्पूफ़िंग से लड़ती है?`,"Who has 192.168.1.20? -> ff:ff:ff:ff:ff:ff":`192.168.1.20 किसके पास है? -> ff:ff:ff:ff:ff:ff`,"Why are certificates encrypted in TLS 1.3?":`TLS 1.3 में सर्टिफ़िकेट एन्क्रिप्ट क्यों किए जाते हैं?`,"Why do captive portals redirect plain HTTP rather than HTTPS?":`कैप्टिव पोर्टल HTTPS की जगह सादे HTTP को ही रीडायरेक्ट क्यों करते हैं?`,"Why do online games and VoIP prefer UDP over TCP?":`ऑनलाइन गेम और VoIP, TCP की जगह UDP क्यों पसंद करते हैं?`,"Why does FTP use Passive (PASV) mode behind home/office NAT firewalls?":`घर/दफ़्तर के NAT फ़ायरवॉल के पीछे FTP पैसिव (PASV) मोड क्यों इस्तेमाल करता है?`,"Why does HTTPS require a Certificate Authority (CA)?":`HTTPS को सर्टिफ़िकेट अथॉरिटी (CA) की ज़रूरत क्यों है?`,"Why does SSH warn on first connection about an unknown host key fingerprint?":`पहली बार जुड़ने पर SSH अज्ञात होस्ट कुंजी फ़िंगरप्रिंट की चेतावनी क्यों देता है?`,"Why does WPA2 derive a fresh PTK per session using ANonce and SNonce?":`WPA2 हर सेशन में ANonce और SNonce से नई PTK क्यों निकालता है?`,"Why does the active closer enter TIME_WAIT after sending the final ACK?":`पहले बंद करने वाला अंतिम ACK भेजकर TIME_WAIT में क्यों जाता है?`,"Why does the client send DHCPREQUEST as a broadcast even after receiving an offer?":`ऑफ़र मिलने के बाद भी क्लाइंट DHCPREQUEST को ब्रॉडकास्ट क्यों करता है?`,"Why is plain HTTP unsafe on public Wi-Fi?":`सार्वजनिक Wi-Fi पर सादा HTTP असुरक्षित क्यों है?`,"Why is standard PPPoE MTU 1492 bytes instead of 1500 bytes?":`मानक PPPoE MTU 1500 की जगह 1492 बाइट क्यों है?`,"Why must Modbus PLCs never be exposed directly to the public internet?":`Modbus PLC को सार्वजनिक इंटरनेट पर सीधे कभी क्यों नहीं खोलना चाहिए?`,"Why must WebSocket frames sent from a browser client be masked?":`ब्राउज़र क्लाइंट से भेजे WebSocket फ़्रेम मास्क क्यों किए जाने चाहिए?`,"Why should SMBv1 always be disabled?":`SMBv1 हमेशा बंद क्यों रखना चाहिए?`,"Why shouldn’t firewalls blindly block ALL ICMP?":`फ़ायरवॉल को सारा ICMP आँख मूँदकर क्यों नहीं रोकना चाहिए?`,"Wi-Fi Captive Portal (RFC 8910 / HTTP 302 Redirect)":`Wi-Fi कैप्टिव पोर्टल (RFC 8910 / HTTP 302 रीडायरेक्ट)`,"Wi-Fi Protected Access 3 (SAE Dragonfly)":`Wi-Fi प्रोटेक्टेड एक्सेस 3 (SAE Dragonfly)`,"Wi-Fi WPA2 / Captive Portal / RADIUS":`Wi-Fi WPA2 / कैप्टिव पोर्टल / RADIUS`,"Wire Hex + ASCII Dump":`वायर हेक्स + ASCII डंप`,"WireGuard Modern Cryptographic VPN":`WireGuard: आधुनिक क्रिप्टोग्राफ़िक VPN`,"WireGuard assigns static internal tunnel IPs mapped to peer public keys.":`WireGuard पीयर की सार्वजनिक कुंजियों से जुड़े स्थिर आंतरिक टनल IP देता है।`,"WireGuard drops invalid handshakes silently without replying":`WireGuard अमान्य हैंडशेक को बिना जवाब दिए चुपचाप गिरा देता है`,"WireGuard is a lean, kernel-space Layer 3 VPN tunnel running over UDP/51820 using Curve25519, ChaCha20-Poly1305, and BLAKE2s with a single 1-RTT Noise handshake and silent stealth drop on unauthenticated packets.":`WireGuard एक हल्की, कर्नेल-स्पेस लेयर 3 VPN सुरंग है जो UDP/51820 पर Curve25519, ChaCha20-Poly1305 और BLAKE2s के साथ चलती है; इसमें एक ही 1-RTT Noise हैंडशेक है और अप्रमाणित पैकेट चुपचाप गिरा दिए जाते हैं।`,"WireGuard puts your entire private office envelope inside an unbreakable outer armored pouch addressed between two VPN gateways—outsiders only see scrambled UDP envelopes.":`WireGuard आपके पूरे निजी दफ़्तर का लिफ़ाफ़ा एक अटूट बख़्तरबंद बाहरी थैली में रखता है जो दो VPN गेटवे के बीच भेजी जाती है; बाहरवालों को सिर्फ़ उलझे हुए UDP लिफ़ाफ़े दिखते हैं।`,"WireGuard runs over UDP (default port 51820) avoiding TCP-over-TCP meltdown.":`WireGuard UDP (डिफ़ॉल्ट पोर्ट 51820) पर चलता है, जिससे TCP-ओवर-TCP की गड़बड़ी से बचता है।`,"WireGuard uses a fixed modern suite: Curve25519, ChaCha20-Poly1305, BLAKE2s, SipHash24.":`WireGuard एक निश्चित आधुनिक सूट इस्तेमाल करता है: Curve25519, ChaCha20-Poly1305, BLAKE2s, SipHash24.`,Wireless:te,"Wireshark Packet Capture Table":`Wireshark-शैली पैकेट कैप्चर तालिका`,"Wireshark capture display filter":`Wireshark-शैली कैप्चर डिस्प्ले फ़िल्टर`,"Wireshark display filter":`Wireshark-शैली डिस्प्ले फ़िल्टर`,"Without SYN cookies, half-open queue fills; with SYN cookies, ISN encodes state statelessly":`SYN cookies के बिना आधी-खुली कतार भर जाती है; SYN cookies के साथ ISN स्थिति को बिना सहेजे कूटबद्ध करता है`,"Without TLS-interception CA trust, the proxy only forwards opaque encrypted bytes.":`TLS-इंटरसेप्शन CA पर भरोसे के बिना प्रॉक्सी सिर्फ़ अपारदर्शी एन्क्रिप्टेड बाइट आगे भेजता है।`,"Without care, 0-RTT early data can be replayed across servers.":`सावधानी न बरती जाए तो 0-RTT का शुरुआती डेटा सर्वरों में दोबारा चलाया जा सकता है।`,"Write valve setpoint register":`वाल्व सेटपॉइंट रजिस्टर में लिखें`,"Wrong Passphrase (Confirm Fail)":`ग़लत पासफ़्रेज़ (Confirm विफल)`,"Wrong Wi-Fi Password":`ग़लत Wi-Fi पासवर्ड`,"X-Forwarded-For (or RFC 7239 Forwarded) records the originating client IP.":`X-Forwarded-For (या RFC 7239 का Forwarded) मूल क्लाइंट का IP दर्ज करता है।`,"X-Forwarded-For / Forwarded":`X-Forwarded-For / Forwarded`,"X-Forwarded-For Spoofing":`X-Forwarded-For स्पूफ़िंग`,"X-Frame-Options":`X-Frame-Options`,Yes:ne,"Yes, always":`हाँ, हमेशा`,"Yes, every 576B":`हाँ, हर 576B पर`,"Yes, every SAE session produces a fresh ephemeral PMK":`हाँ, हर SAE सेशन नई अस्थायी PMK बनाता है`,"Yes, in Msg 1":`हाँ, संदेश 1 में`,"Yes, inside DNS":`हाँ, DNS के भीतर`,"Yes, via partial BODYSTRUCTURE/FETCH":`हाँ, आंशिक BODYSTRUCTURE/FETCH से`,"You write down when you sent a text (T1), your friend writes when they got it (T2) and replied (T3), and you note when you got the reply (T4) so you can cancel out delivery delay and set your watch accurately.":`आप लिखते हैं कि संदेश कब भेजा (T1), आपका दोस्त लिखता है कब मिला (T2) और कब जवाब दिया (T3), और आप लिखते हैं जवाब कब मिला (T4); इससे डिलीवरी की देरी हटाकर आप अपनी घड़ी सटीक मिला सकते हैं।`,"Zero-Handshake Send":`बिना हैंडशेक भेजना`,"Zero-knowledge proof of shared PMK":`साझा PMK का ज़ीरो-नॉलेज प्रमाण`,"Zone Enumeration via NSEC":`NSEC से ज़ोन गणना`,"Zoom In":`ज़ूम इन`,"Zoom Out":`ज़ूम आउट`,"`ssh -D 1080` starts dynamic SOCKS5 forwarding over the encrypted SSH tunnel.":"`ssh -D 1080` एन्क्रिप्टेड SSH सुरंग पर डायनामिक SOCKS5 फ़ॉरवर्डिंग शुरू करता है।","a001 NO LOGIN failed":`a001 NO LOGIN failed`,"application/dns-message":`application/dns-message`,"application/dns-message (POST/GET over HTTPS)":`application/dns-message (HTTPS पर POST/GET)`,"application/octet-dns":`application/octet-dns`,"connect & publish":`connect और publish`,"cwnd (MSS)":`cwnd (MSS)`,"cwnd grows exponentially (2 -> 4 -> 8 MSS)":`cwnd तेज़ी से दोगुना होता जाता है (2 -> 4 -> 8 MSS)`,"iPerf3 TCP cwnd":`iPerf3 TCP cwnd`,"icon in Safari.":`आइकन (Safari में)।`,"image/png":`image/png`,"ssh -D":`ssh -D`,"ssh -L":`ssh -L`,"ssh -V":`ssh -V`,"ssh -X":`ssh -X`,"text/html":`text/html`};export{e as Act,t as Add,n as Application,r as Architecture,i as Aspect,a as Authentication,o as Authoritative,s as Blowfish,c as Browser,l as Challenge,u as Client,d as Close,f as Confidentiality,p as Connection,m as Defense,h as Destination,g as ETag,_ as Ethernet,v as Fiber,y as Foundations,b as Gateway,x as Host,S as Info,C as Install,w as Internet,T as Lab,E as Layer,D as Link,O as Medium,k as Methods,A as Network,j as Never,M as New,N as Nothing,P as Physical,F as Presentation,I as Random,L as Redo,R as Reliability,z as Router,B as Routing,V as Security,H as Serial,U as Server,W as Session,G as Share,K as Solution,q as Source,J as Stack,Y as Stealth,X as Switching,Z as Telnet,Q as Transport,$ as Troubleshooting,ee as Undo,te as Wireless,ne as Yes,re as default};